quests[11898] = { id = 11898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbruch", description = "Auf der niedrigsten Ebene der Tempelstadt befindet sich ein grauer, in Licht getauchter Altar. Stellt Euch davor und sprecht die Worte auf den Schriftrollen laut aus, damit Euch der Eintritt in die grauenhafte Nekropole namens Naxxanar gewährt wird.\n\nSeid vorsichtig, {name}. Prinz Valanar wird mit Sicherheit von seinem persönlichen Gefolge umgeben sein - ein jeder bereit, seinen Meister unter Einsatz seines Lebens zu schützen.\n\nIhr müsst einen Weg durch die Nekropole bis zum Sitz des Prinzen finden. Falls Ihr ihn nicht besiegen solltet, {name}, befürchte ich, dass mein Volk niemals die Sicherheit Eisnebels erleben wird.", sourceObjective = "Besiegt Prinz Valanar und seine Leutnants Vanthryn den Erbarmungslosen und Luthion den Grässlichen. Meldet Euch anschließend bei Häuptling Orkan in Taunka'le.", progress = "Habt Ihr Prinz Valanar besiegt?", completion = "Nachdem der Prinz besiegt worden ist, sind die Truppen der Geißel in der Boreanischen Tundra verschwunden. Aber machen wir uns nichts vor: Sie werden nicht lange fernbleiben, weshalb ich Durm darauf vorbereiten muss, die Dorfbewohner nach Eisnebel zu führen.\n\n<Der Häuptling schüttelt zögerlich seinen Kopf.>\n\nIch hatte zwar schon viele Meinungsverschiedenheiten mit Durm, aber ich vertraue auf sein Urteil und seine Fähigkeiten. Ich kann Taunka'le nicht aufgeben, also werde ich es so lange verteidigen, bis ich erschlagen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11899] = { id = 11899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelen der vom Fluch befreiten", description = "Die Mechagnome in den Teichen gen Westen sind uns ein großes Rätsel. Kurze Zeit, nachdem die Gnome von der Pumpstation und aus der Umgebung verschwanden, sind sie aufgetaucht.\n\nSie stellen eine Gefahr dar und man muss sich um sie kümmern.\n\nNehmt diesen Seelenfänger und wendet ihn auf die Überreste der Mechagnome an, um ihre Seelen einzufangen. Wenn Ihr zurückkommt, werden wir sie freilassen und so vielleicht herausfinden, was mit ihnen geschehen ist.", sourceObjective = "Fangt mithilfe von Großmutters Seelenfänger 10 Seelen der Mechagnome von Kurbelzisch. Kehrt anschließend zu Großmutter Taiga in Taunka'le zurück, sobald Ihr das erledigt habt.", completion = "Nun müssen wir die gefangenen Seelen befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[11900] = { id = 11900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähler ablesen", description = "Ich hatte gehofft, dass die Auswirkungen des Nexus nur auf diese Region beschränkt wären. Vor Kurzem haben wir jedoch Meldungen aus allen Teilen Azeroths erhalten, die darauf hinweisen, dass die geologische Instabilität rapide ansteigt!\n\nDer Nexus muss regelmäßig überwacht werden, während ich nach einer Lösung des Problems suche.\n\nIch habe in ganz Kaltarra empfindliche Instrumente aufgestellt, die als Malygos' Seherkugeln getarnt sind. Eines befindet sich im Graben in der Nähe des Nexus und die anderen drei sind in den Gebäuden entlang der Talgrenze versteckt. Sucht sie alle auf und kehrt mit den Messwerten zu mir zurück.", sourceObjective = "Erzmagier Berinand im Transitusschild möchte, dass Ihr mit den Messwerten seiner Instrumente in Kaltarra zu ihm zurückkehrt.", completion = "Die Sache ist schlimmer als erwartet.\n\nMalygos leitet zu viel Energie in diesen Ort. Wenn niemand ihn aufhält, wird aus Azeroth eine weitere Scherbenwelt...\n\nZum Glück glaube ich, eine provisorische Lösung gefunden zu haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[11901] = { id = 11901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppen? Welche Truppen?", description = "Die Geißel ist überall, {class}. Wir haben mithilfe der Bauern und Kumpels eine Miliz zusammengestellt, doch das wird einfach nicht genügen.\n\nDie eine Einsatztruppe, die uns von der Valianzfeste geschickt wurde, verteidigt die Mine. Wir haben schon seit Tagen nichts von ihnen gehört!\n\nWenn Ihr uns wirklich helfen wollt, wieso geht Ihr dann nicht zur Mine und seht nach? Vielleicht können wir sie dazu bringen, uns Verstärkung zu schicken.", sourceObjective = "Gerald Grün in Fernhain möchte, dass Ihr Euch in die Mine im Norden begebt und herausfindet, was mit der Einsatztruppe, die dorthin geschickt wurde, geschehen ist.", completion = "Euer Magen fühlt sich mulmig an, als Ihr Euch dem Korn nähert. Der Gestank ist fast unerträglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[11902] = { id = 11902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädliche Beweise", description = "Die Kornsäcke verströmen den faulen Gestank, den Ihr mittlerweile mit der Seuche verbindet. Das wird wahrscheinlich erklären, was mit den Verteidigern der Mine, den Fußsoldaten, geschehen ist.\n\nAm besten gebt Ihr Gerald Grün Bescheid.", sourceObjective = "Kehrt zu Gerald Grün in Fernhain zurück.", completion = "Die armen Jungs... sie hatten nie eine Chance!\n\nDas klingt jedenfalls, als hätten wir einen Maulwurf in unseren Reihen. Wahrscheinlich ein Agent des Kults der Verdammten. Verflucht sollen diese Wahnsinnigen sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[11903] = { id = 11903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zu handeln", description = "Nun, {name}. Da den letzten Rest unserer Truppen in Fernhain nun der Tod oder Schlimmeres geholt hat, bleibt uns nur eins übrig: selbst gegen diese Geißel zu kämpfen.\n\nWir haben in dem, was von Fernhain übrig ist, Milizen stationiert. Ohne Eure Hilfe ist ihre Chance, zu gewinnen, gering. Geht und steht ihnen bei. Meine Jungs und ich werden diesen Pfad bewachen. Wir können nicht zulassen, dass die Geißel durchbricht!", sourceObjective = "Gerald Grün in Fernhain möchte, dass Ihr 14 verseuchte Aasfresser tötet.", completion = "Ihr habt Euch mit der Geißel in der einzigen Sprache verständigt, die sie kennt: Gewalt und Tod. Unglücklicherweise kommen immer mehr!", sourceObjectiveStatus = "unverified-source-field" }
quests[11904] = { id = 11904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Früchte unserer Arbeit", description = "Es kommen immer mehr Diener der Geißel... doch aufgeben dürfen wir nicht! Hört zu, {name}. Im Inneren dieser Mine gibt es einen Wagen beladen mit dem letzten Rest Erz, den die Allianz auf dieser Seite des Kontinents für lange Zeit sehen wird.\n\nDas Problem ist nur, dass die Wegrollsperre des Wagens verschlossen ist. Als das Militär dort hineingegangen ist, hat Hauptmann Jacobs alles an wichtiger Ausrüstung, inklusive des Wegrollsperrenschlüssels, beschlagnahmt.\n\nDie Seuche, von der die Soldaten in der Mine infiziert wurden, muss auch Jacobs infiziert haben. Nehmt ihm den Schlüssel ab und bergt das Erz.", sourceObjective = "Geht zur Mine in Fernhain, nehmt Hauptmann Jacobs den Wegrollsperrenschlüssel ab und macht den Wagen mit Erz los. Kehrt zu Gerald Grün in Fernhain zurück, sobald Ihr Eure Aufgabe beendet habt.", completion = "Ich danke Euch, {name}. Dieses Erz wird in der kommenden Zeit von entscheidender Wichtigkeit für die Allianz sein. Ich gehe mal davon aus, dass unser heutiges Handeln den Lauf der Dinge beeinflussen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11905] = { id = 11905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Unvermeidliche hinauszögern", description = "Azeroths Leylinien werden zum Nexus umgeleitet.\n\nDer Zustrom arkaner Energien verursacht einen Riss zwischen den Dimensionen.\n\nIch kann es zwar nicht aufhalten, habe jedoch einen Weg gefunden, es zu verlangsamen.\n\nNehmt diesen Gegenstand und aktiviert ihn in der Nähe des sich bildenden Risses.", sourceObjective = "Das Abbild der Kriegsmagierin Kaitlyn im Nexus möchte, dass Ihr den interdimensionalen Refabrikator in der Nähe des Risses benutzt.", progress = "Wart Ihr schon beim Riss?", completion = "Ausgezeichnete Arbeit, {name}. Die Erdbeben lassen schon nach.\n\nMit etwas Glück haben wir uns genug Zeit verschafft, um einen Weg zu finden, wie wir Malygos' Pläne durchkreuzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11906] = { id = 11906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Teiche säubern", description = "<Eisenauge läuft eine Träne über die Wange.>\n\nIch habe gehört, dass Ihr wieder zu den Teichen im Westen zurückgeht. Ich habe etwas für Euch zu tun, wenn Ihr schon einmal dort draußen seid, {race}.\n\nDie Gnome, die sich einen feuchten Dreck um das Land scheren, haben es mit ihren Maschinen verschmutzt. Ich möchte, dass Ihr alle Ersatzteile, über die Ihr stolpert, aufsammelt.\n\nBringt sie mir und ich werde mich darum kümmern, dass sie anständig entsorgt werden, bevor wir diesen Ort für immer verlassen.", sourceObjective = "Sammelt 15 Ersatzteile von Kurbelzisch und bringt sie zu Eisenauge in Taunka'le.", progress = "Wenn wir uns nicht um das Land kümmern, wird es hier bald keinen Raum für Leben mehr geben.", completion = "Es ist der Weg der Taunka, das Land in einem makellosen Zustand zu verlassen, bevor wir weiterziehen.\n\nWir werden uns schon bald auf den Weg zu unserer Hauptsiedlung Eisnebel machen. Ihr habt uns dabei geholfen, viel schneller abzureisen.\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11907] = { id = 11907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Offiziere", description = "Es ist bekannt, dass Ritzelmeister Mechazod vier Offiziere hat, welche die Roboter in den Teichen kontrollieren.\n\nWir müssen ihnen ein Ende machen!\n\nUnsere Fernläufer und Schneefährtenleser behaupten, dass, falls man die Ventile an der West-, Nord-, Zentral- und Südstation zudrehen sollte, seine Offiziere auf schnellstem Wege herbeieilen würden, um zu verhindern, dass man ihnen einen Strich durch die Rechnung macht.\n\nDie genannten Stationen befinden sich bei den rotierenden Lichtern in den Teichen um die Pumpstation herum.\n\nBeeilt Euch, {name}!", sourceObjective = "Besiegt Twonkie, ED-210, Max Kawummso und Molok den Zermalmer und meldet Euch anschließend beim Weisen Erde und Himmel in Taunka'le.", completion = "Ich danke Euch, {name}.\n\nDadurch, dass diese seltsamen Kreaturen zerstört wurden, sollte es ein Leichtes sein, mit dem Rest der Teiche fertigzuwerden.\n\nWir schulden Euch Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[11908] = { id = 11908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Referenzmaterial", description = "Ich war für die Erntegolems verantwortlich - eine wichtige Aufgabe, bis die Geißel den größten Teil des Ackerlands zerstörte. Ich habe jedoch eine Idee, wie wir die Erntegolems nützlich wieder einsetzen können.\n\nIch kann die Erntesammler so verkabeln, dass sie uns im Kampf gegen die Geißel helfen.\n\nJetzt bin ich auch nicht gerade ein Experte, was das angeht, deshalb brauche ich mein Handbuch. Das Problem ist aber, dass ich es in der Werkstatt vergessen habe... welche ungünstigerweise das brennende Gebäude dort neben der Mine ist. Meint Ihr, Ihr könntet es für mich holen?", sourceObjective = "Jeremias Hohning möchte, dass Ihr das Buch \"Felder, Fabriken und Werkstätten\" aus dem brennenden Gebäude neben der Mine in Fernhain holt.", progress = "Habt Ihr mir mein Buch besorgt?", completion = "Ausgezeichnet! Darin sollte stehen, was ich wissen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[11909] = { id = 11909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt den Ritzelmeister", description = "Dieser Ritzelmeister Mechazod ist ganz offensichtlich nicht ganz bei Trost. Wenn seine sogenannte Heilung und Unsterblichkeit bedeuten, dass alle von uns zu Robotersklaven werden, dann muss man ihn aufhalten!\n\nDie Winde, die mir den Weg weisen, flüstern mir zu, dass er sich auf dem Dach der Pumpstation in der Mitte des Teiches gen Westen befindet.\n\nHöchstwahrscheinlich befindet er sich in dem Führerhäuschen ganz oben auf dem Gebäude. Geht dort hoch und untersucht sein Zeug.\n\n{name}, Ihr müsst Mechazod entgegentreten, wenn wir überleben sollen!", sourceObjective = "Untersucht das Handbuch des Ritzelmeisters und bringt Mechazods Kopf zu Großmutter Taiga in Taunka'le.", progress = "Ist es vorbei? Geht von Ritzelmeister Mechazod keine Bedrohung mehr aus?", completion = "<Die Großmutter gibt einen tiefen erleichterten Seufzer von sich.>\n\nEs ist vollbracht... Ihr habt uns gerettet! Hättet Ihr ihn hier nicht aufgehalten, wer weiß, wie weit sich dieser Fehler der Gnome verbreitet hätte?\n\nAngesichts der Bedrohung durch die blauen Großdrachen und den Nexuskrieg, geschweige denn den Lichkönig, ist das Letzte, was wir brauchen, eine frei herumlaufende, verrückte Schöpfung der Titanen!\n\nIch danke Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11910] = { id = 11910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Urtume", description = "Offensichtlich hat die Instabilität in dieser Region Auswirkungen auf die einheimischen Kreaturen gehabt.\n\nMich interessieren die Urtume und ihre jüngsten Adaptationen. Ich vermute, dass ihr Wandel zu diesen 'magiegebundenen' Urtumen vielleicht Hinweise über unsere verzwickte Lage hier liefern wird.\n\nFür meine Forschungen brauche ich Proben beider Urtume. Beeilt Euch...", sourceObjective = "Erzmagier Berinand im Transitusschild möchte, dass Ihr 3 eiszeitliche Späne und 3 magiegebundene Späne von den Urtumen in Kaltarra besorgt.", progress = "Habt Ihr die Proben, die ich angefordert habe, gesammelt?", completion = "Ja, ja. Die sollten auf jeden Fall genügen.\n\nIch danke Euch, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11911] = { id = 11911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschleunigen", description = "Ich habe in der kurzen Zeit, die mir hier gegeben wurde, mehr gelernt, als in Jahrzehnten des Studiums.\n\nDiese Urtume sind einer ungeheuerlich hohen Dosis arkaner Energie ausgesetzt. Es verwandelt sie buchstäblich in etwas... anderes.\n\nIch bin zuversichtlich, dass ihre Metamorphose noch eine weitere Stufe beinhaltet. Beschafft mir Hinweise auf ihren endgültigen Zustand.", sourceObjective = "Das Abbild der Kriegsmagierin Kaitlyn im Nexus möchte, dass Ihr 5 arkane Splitter von kristallinen Beschützern beschafft.", progress = "Die kristallinen Urtume... Existieren sie wirklich?", completion = "Faszinierend!\n\nUnd sie sind auch noch aggressiv, meint Ihr. Das würde darauf hinweisen, dass irgendeine Intelligenz hinter dieser Manipulation steckt.\n\nGut möglich, dass es sich hier um kein natürliches Phänomen handelt...", sourceObjectiveStatus = "unverified-source-field" }
quests[11912] = { id = 11912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrückt nach Beeren", description = "Oh! Welch Erleichterung, einmal ein neues Gesicht zu erblicken! Ich hatte schon das Gefühl, man hätte uns aufgegeben.\n\nWir wurden vor Tagen von unseren Versorgungswegen abgeschnitten und die Situation sieht nicht gerade, nun ja, rosig aus. Um ehrlich zu sein, war das von Anbeginn ein Selbstmordauftrag, wenn Ihr mich fragt.\n\nVielleicht bin ich für all diese Brutalität nicht aus dem richtigen Holz geschnitzt - geschweige denn für diese bittere Kälte! Ich wäre viel lieber wieder zurück in Dalaran und dabei, uralte Texte zu untersuchen.\n\nDoch kommen wir zur Sache: Unsere Essensvorräte gehen zur Neige. Bitte, sammelt, was Ihr nur könnt, und bringt es mir.", sourceObjective = "Bibliothekarin Serrah im Transitusschild möchte, dass Ihr 10 Frostbeeren von den Frostbeerbüschen in Kaltarra besorgt.", progress = "Habt Ihr schon etwas zu essen gefunden?", completion = "Tja, es ist nicht viel, aber es sollte uns für einen weiteren Tag am Leben halten.\n\nIch meine, dass dies ein angebrachter Preis für Eure Mühen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11913] = { id = 11913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Risiko eingehen", description = "Ich habe mitgehört, was Ihr Gerald gesagt habt, und mir gefällt es gar nicht. Wenn Kultisten es schaffen konnten, das Korn in den Minen mit ihrer grauenhaften Seuche zu vergiften, hätten sie es genauso gut mit dem Korn draußen machen können.\n\nWir haben keine Zeit, die Spreu vom Weizen zu trennen. Wir müssen geschwind handeln und alles verbrennen.\n\nNehmt diese Fackel und steckt alle Kornsäcke, die Ihr dort draußen finden könnt, in Brand. Es wäre eine Tragödie, wenn wir diesen Angriff nur überlebt hätten, um anschließend vor der Seuche kapitulieren zu müssen.", sourceObjective = "Wendy Darren möchte, dass Ihr mithilfe von Wendys Fackel 8 Säcke Korn aus Fernhain verbrennt.", completion = "Ich danke Euch, {name}. Ich würde es nicht gerne sehen, wenn die Überlebenden des Angriffs auf Fernhain über verseuchtes Korn stolpern würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11914] = { id = 11914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis hüten", description = "Unsere Existenz hier draußen hängt gänzlich davon ab, ob man uns entdeckt. Sollte der Schild nicht funktionieren, auch nur für einen Moment, gehen Malygos' Diener uns an den Kragen.\n\nEine meiner Aufgaben ist, das Mana der Kriegsmagier auf einem gewissen Niveau zu halten, damit ihre Konzentration nicht nachlässt. Da wir von der Versorgung abgeschnitten sind, sehe ich mich gezwungen zu improvisieren.\n\nIch könnte Eure Hilfe gebrauchen, {name}.\n\nSehr nahe am Nexus tun sich die arkanen Schlangen an den reichen Manavorkommen gütlich. Wenn sie erst einmal besiegt sind, werden sie eine Manaessenz erzeugen, die ich gebrauchen kann.", sourceObjective = "Bibliothekarin Serrah im Transitusschild möchte, dass Ihr arkane Schlangen in der Nähe des Nexus tötet und 5 Nexusmanaessenzen sammelt.", progress = "Habt Ihr die Manaessenzen dabei, um die ich Euch gebeten habe?", completion = "Euer Dienst für Dalaran wird nicht unbemerkt bleiben, {race}.\n\nIch hoffe, dass Ihr mit dieser Entlohnung zufrieden seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11915] = { id = 11915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiel mit dem Feuer", description = "Möchtet Ihr ein paar heiße neue Fertigkeiten erlernen?\n\nOb Ihr jemals meine beeindruckende Fertigkeit erreichen werdet, sei zwar dahingestellt, aber ein oder zwei Kunststückchen werdet Ihr wahrscheinlich aufschnappen können, wenn Ihr <ein aufmerksamer Schüler/eine aufmerksame Schülerin> seid. Sprecht mit einem Feuerschluckmeister in einer der Hauptstädte der Horde. Sie sollten Euch weiterhelfen können.", sourceObjective = "Sprecht mit einem Feuerschluckmeister in einer der Hordehauptstädte.", completion = "Grüße. Seid Ihr hier, um zu lernen, was man mit Feuer alles machen kann?", sourceObjectiveStatus = "unverified-source-field" }
quests[11916] = { id = 11916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllschreis Champion", description = "Ihr habt Euch allen Herausforderungen, mit denen Ihr konfrontiert wurdet, gestellt und sie mit links gemeistert. Es ist Euch zu verdanken, {name}, dass die Horde nun in Nordend Fuß gefasst hat.\n\nDoch unsere Arbeit hat gerade erst begonnen. Wir müssen zur Eiskrone marschieren und ihre Mauern niederreißen!\n\nEuer nächster Auftrag beginnt im Osten, in Taunka'le. Unsere Verbündeten, die Taunka, sind in äußersten Schwierigkeiten und benötigen unsere Hilfe. Lasst Euch von Durgot Wolfsbruder, unserem Stallmeister, eine Reisemöglichkeit organisieren und sucht nach Häuptling Orkan in Taunka'le.", sourceObjective = "Geht nach Taunka'le und sucht Häuptling Orkan auf.", completion = "Ich befürchte, Ihr könntet zu spät sein, Champion. Viele meiner Brüder und Schwestern haben Taunka'le schon den Rücken gekehrt und suchen Unterschlupf in der Drachenöde weit im Osten.\n\nEs gibt hier jedoch noch viel zu erledigen und nur Wenige, die uns mit ihrer Kraft zur Hand gehen würden...", sourceObjectiveStatus = "unverified-source-field" }
quests[11917] = { id = 11917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nKehrt zum Lager am Zoramstrand zurück – dorthin, wo die großen Eisbrocken liegen. Sie nehmen mit ihrer Hilfe Verbindung mit den Elementaren auf – genau so, wie sie es in Silithus machen. Ich sage das nur ungern, doch die Geister werden Verständnis haben – Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", sourceObjective = "Beschwört mithilfe des Eisbrockens auf dem Zoramstrand im Eschental den Leutnant der Frostwelle, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf dem heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11918] = { id = 11918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundausbildung", description = "Das ist Krieg, <Sterblicher/Sterbliche>, und wir bilden die Speerspitze.\n\nEure kleinen Streitereien über Land oder Währung sind Nichtigkeiten, wenn man sie mit diesem Konflikt vergleicht. Wir stehen dem Aspekt Malygos und seinem gesamten blauen Drachenschwarm gegenüber. Alles, was Ihr wissen müsst, ist, dass es diese Welt nicht mehr geben wird, falls er siegen sollte.\n\nWir sind hier nur wenige und kämpfen gegen viele an. Dass wir sterben werden ist so gut wie sicher und unser endgültiger Erfolg liegt lediglich darin, unseren Feind zu verlangsamen.\n\nGeht jetzt. Beeilt Euch, während ich mich entscheide, was ich mit Euch machen soll.", sourceObjective = "Raelorasz im Transitusschild möchte, dass Ihr 10 Spruchwirker von Kaltarra tötet.", completion = "Gut, {class}, da Ihr Euch jetzt mit dem Feind vertraut gemacht habt, ist es Zeit, an die Arbeit zu gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11919] = { id = 11919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenjagd", description = "Die Blauen haben damit angefangen, ihre Drachen mit mysteriösen Runen zu bedecken. Ich muss herausfinden, was sie zu bedeuten haben.\n\n<Raelorasz ritzt sich mit einem Speer in die Hand und benetzt die Spitze mit seinem Blut.>\n\nNehmt dies hier und wendet es auf einen von ihnen an. Wartet, bis es gebändigt ist, und bringt es zu mir zurück, bevor die Wirkung nachlässt.\n\nIhre Jungen gehen in der nordwestlichen Ecke des Tals auf Nahrungssuche.", sourceObjective = "Raelorasz möchte, dass Ihr mithilfe von Raelorasz' Speer ein Nexusdrachenjunges bändigt und es anschließend zu ihm zurückbringt. Er befindet sich im Transitusschild.", completion = "Das Schicksal dieser jungen Drachen muss Euer Gewissen nicht belasten, {race}. Malygos alleine trägt die Verantwortung hierfür.\n\nIch arbeite unablässig an der Lösung des Rätsels um diese Runen. Wir werden nicht mehr Leben nehmen, als unbedingt notwendig.", sourceObjectiveStatus = "unverified-source-field" }
quests[11920] = { id = 11920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kultisten unter uns", description = "Auf diesem Altar befinden sich alle Markierungen des Kults der Verdammten. Es scheint, als hätten Fanatiker vom Festland es bis nach Nordend geschafft. Es wäre vielleicht klug, den Kapitän des Schiffs darüber in Kenntnis zu setzen.\n\nVielleicht befindet er sich über Deck.", sourceObjective = "Sprecht mit Kapitän \"Linksdatsch\" Gaffelsegel an Deck der Sturmbrecher in der Valianzfeste.", completion = "Kultisten? Unter Deck? Ich werde wohl meine gesamte Crew auspeitschen lassen müssen!\n\nHört zu... wieso lassen wir nicht Admiralin Kantelbree die Angelegenheit in die Hand nehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[11921] = { id = 11921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmal Fackeln werfen", description = "Seid gegrüßt, Feuerjongleur! Macht es Euch Spaß, wenn Ihr Flammen wild umherwirbeln lasst? Das hört man doch gerne! Nun, haltet Ihr Euch für einen Experten in Sachen Fackelwürfe? Dann will ich Euch auf die Probe stellen...\n\nIhr kennt die Regeln: Werft die Fackeln auf die markierten Kohlenpfannen. Doch dieses Mal habt Ihr ein wenig mehr Zeit und VIEL mehr Kohlenpfannen zu treffen.\n\nBereit?", sourceObjective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister.", completion = "Wow, Ihr habt es geschafft! Spitze! Vielleicht könnt Ihr Euch nächstes Jahr für eine Stelle auf dem Fest bewerben!", sourceObjectiveStatus = "unverified-source-field" }
quests[11922] = { id = 11922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fackelwurf", description = "Ihr wollt also Feuerjongleur werden? Denkt Ihr, dass Ihr das Zeug dazu habt? Die Geschicklichkeit? Die Reflexe? ...den Mut? Wenn ja, dann wollen wir Euch mal auf die Probe stellen!\n\nNehmt diese Fackeln und rennt zum Freudenfeuer. Dort befinden sich Kohlenpfannen, über denen blinkende Markierungen schweben, die Ihr mit einer Fackel treffen müsst. Seid schnell! Um für einen Wurf Punkte zu bekommen, müsst Ihr die Fackel werfen, bevor die Markierung verschwindet!\n\nTrefft genug markierte Kohlenpfannen, bevor die Zeit abgelaufen ist, und kommt dann hierher zurück... um Eure nächste Lektion zu erhalten.", sourceObjective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerjongleur des Sonnenwendfests.", completion = "Gut gemacht! Die Lunte eines Feuerkreisels brennt schnell... doch Ihr werdet die Kunst des Feuerjonglierens noch schneller erlernen! Nun macht Euch bereit! Beim nächsten Test werdet Ihr so richtig ins Schwitzen kommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11923] = { id = 11923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fackeln fangen", description = "Da Ihr ja nun eine Fackel werfen könnt, lasst uns doch einmal sehen, ob Ihr auch eine fangen könnt!\n\nNehmt diesen Stapel unangezündete Fackeln, geht zum Feuer und werft eine davon hoch in die Luft! Fangt sie wieder auf, bevor sie auf den Boden fällt... und werft sie wieder in die Höhe! Fangt vier und kommt wieder zu mir zurück.\n\nVorsicht! Die Fackeln werden gefährlich, wenn sie auf dem Boden aufkommen! Viel Glück.", sourceObjective = "Fangt nacheinander 4 Fackeln und sprecht anschließend mit dem Feuerschluckmeister.", progress = "Fackeln zu fangen macht jede Menge Spaß, meint Ihr nicht? Seid jedoch vorsichtig! Ihr wollt bestimmt nicht angesengt werden!", completion = "Habt Ihr Euch verbrannt? Falls ja, dann werdet Ihr es Euch in Zukunft zweimal überlegen, bevor Ihr mit Feuer herumspielt...\n\nScherz! Gut gemacht! Es ist nun offiziell: Ihr seid ein Feuerjongleur des Freudenfeuers. Nun geht und amüsiert Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[11924] = { id = 11924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmal Fackeln fangen", description = "Fackeln zu fangen, hält einen auf Zack, daran besteht kein Zweifel. Denkt Ihr, dass Ihr es lange durchhalten werdet?\n\nNa dann lasst uns mal sehen...", sourceObjective = "Fangt 10 Fackeln und sprecht anschließend mit dem Feuerschluckmeister.", progress = "Fackeln zu fangen macht jede Menge Spaß, meint Ihr nicht? Seid jedoch vorsichtig! Ihr wollt bestimmt nicht angesengt werden!", completion = "Wie geht es Eurem Arm, {name}? Das war eine glanzvolle Vorstellung dort draußen - wie ein echter Meisterjongleur!", sourceObjectiveStatus = "unverified-source-field" }
quests[11925] = { id = 11925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmal Fackeln fangen", description = "Fackeln zu fangen, hält einen auf Zack, daran besteht kein Zweifel. Denkt Ihr, dass Ihr es lange durchhalten werdet?\n\nNa dann lasst uns mal sehen...", sourceObjective = "Fangt 10 Fackeln und sprecht anschließend mit dem Feuerschluckmeister.", progress = "Fackeln zu fangen macht jede Menge Spaß, meint Ihr nicht? Seid jedoch vorsichtig! Ihr wollt bestimmt nicht angesengt werden!", completion = "Wie geht es Eurem Arm, {name}? Das war eine glanzvolle Vorstellung dort draußen - wie ein echter Meisterjongleur!", sourceObjectiveStatus = "unverified-source-field" }
quests[11926] = { id = 11926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmal Fackeln werfen", description = "Seid gegrüßt, Feuerjongleur! Macht es Euch Spaß, wenn Ihr Flammen wild umherwirbeln lasst? Das hört man doch gerne! Nun, haltet Ihr Euch für einen Experten in Sachen Fackelwürfe? Dann will ich Euch auf die Probe stellen...\n\nIhr kennt die Regeln: Werft die Fackeln auf die markierten Kohlenpfannen. Doch dieses Mal habt Ihr ein wenig mehr Zeit und VIEL mehr Kohlenpfannen zu treffen.\n\nBereit?", sourceObjective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister.", completion = "Wow, Ihr habt es geschafft! Spitze! Vielleicht könnt Ihr Euch nächstes Jahr für eine Stelle auf dem Fest bewerben!", sourceObjectiveStatus = "unverified-source-field" }
quests[11927] = { id = 11927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man munkelt", description = "He, {name}. In der Gaststätte ist ein Mädchen, das nach Euch gefragt hat. Sie heißt Leryssa.\n\nIch denke nicht, dass sie Euch kennt, aber sie sagt, dass sie Eure Hilfe benötigt. Sie klang wirklich verzweifelt.", sourceObjective = "Geht zum Gasthaus in der Valianzfeste und sucht Leryssa auf.", completion = "Vielen Dank, dass Ihr gekommen seid, um mich zu sehen. Ich wusste nicht, an wen ich mich sonst hätte wenden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11928] = { id = 11928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fernhain", description = "Meine Jungs sollten die Sache von jetzt an in die Hand nehmen können, {name}. Die Valianzfeste kann weit mehr trotzen als diesen Angriffen. Ich mache mir jedoch um unser Ackerland und die Mine in Fernhain Sorgen.\n\nWir haben kurz vor dem Überfall eine komplette Einsatzgruppe ausgesandt, um unsere Schürfoperationen in der Mine zu beschützen - sie sollten in der Lage sein, unsere Zivilisten zu verteidigen.\n\nGerald Grün ist für die dortigen Dorfbewohner verantwortlich. An der Nordwand der Valianzfeste gibt es eine Passage, die Euch direkt zu ihm führen wird. Seht nach, wie Ihr ihm helfen könnt.", sourceObjective = "Reist nach Fernhain in der Boreanischen Tundra und sprecht mit Gerald Grün.", completion = "Ihr seid hier, um zu helfen? Dann kommt Ihr gerade rechtzeitig!", sourceObjectiveStatus = "unverified-source-field" }
quests[11929] = { id = 11929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taunka'les Untergang", description = "Wir sind verloren, {name}. Dieser Ort ist schon seit vielen Generationen unsere Heimat gewesen, doch er ist nicht länger sicher. Hier begegnet einem nur noch der Tod... Tod und die Erinnerung daran, wie es einst gewesen ist.\n\nIch habe die Evakuierung von Taunka'le beordert. Alle verbliebenen Taunka müssen den Ort sofort verlassen und sich auf den Weg zu unserer Hauptsiedlung Eisnebel in der Drachenöde machen.\n\n<Orkan deutet in Richtung Osten.>\n\nIhr müsst dabei helfen, mein Volk in Sicherheit zu bringen, {name}. Mutter Tauranook erwartet Euch am Eingang des Dorfes. Beeilt Euch! Die Geißel ist überall und kommt immer näher!", sourceObjective = "Sprecht mit Mutter Tauranook außerhalb von Taunka'le.", completion = "<Mutter Tauranook wischt sich die Tränen von den Wangen.>\n\nEs gab einmal eine Zeit, als ich über diese Tundra wandeln konnte und ich, so weit das Auge reichte, Schnee erblicken konnte.\n\nDoch der Schnee hat uns verlassen und uns damit signalisiert, dass unsere Zeit hier zu Ende ist. Wir verbinden viele glückliche Erinnerungen mit Taunka'le und der Boreanischen Tundra...\n\n<Mutter Tauranook wimmert.>\n\nVielleicht wird die Zukunft unsere Wiederkehr bringen - gemeinsam mit dem Schnee.", sourceObjectiveStatus = "unverified-source-field" }
quests[11930] = { id = 11930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quer durch Transborea", description = "Der Pfad durch Transborea im Osten ist der einzige Weg, um die Drachenöde zu erreichen. Viele Gefahren erwarten Euch auf der Reise durch die Tundra. Nehmt Euch vor der Geißel und ihrem Einfluss auf die Landkreaturen in Acht. Es gehen Gerüchte um, dass unsere eigenen Brüder und Schwestern von den Toten auferstehen und die Karawanen angreifen, die sich auf den Weg in die Drachenöde befinden! Verteidigt Eure Karawane und bringt die Evakuierten in Sicherheit!\n\nWartuk Eiskind erwartet Euch auf der anderen Seite der Brücke, welche in die Drachenöde führt.", sourceObjective = "Eskortiert die Evakuierten aus Taunka'le durch die Transborea bis zu Wartuk Eiskind in der Drachenöde.", completion = "<Wartuk sieht Euch mit einem grimmigen Gesichtsausdruck an.>\n\nEisnebel gibt es nicht mehr...", sourceObjectiveStatus = "unverified-source-field" }
quests[11931] = { id = 11931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Code entziffern", description = "Ich spüre, dass die Drachen in dieser Gegend über eine bestimmte Eigenart verfügen, doch was die Runen, mit denen ihr gesamter Körper bedeckt ist, zu bedeuten haben, entzieht sich mir noch immer.\n\nOhne einen Kodex wird es mich mehr Zeit kosten, sie zu deuten, als wir uns leisten können.\n\nNicht weit von hier entfernt befindet sich ein Verräter der Kirin Tor namens Caleras, der höchstwahrscheinlich über eine Kopie des Wälzers, den ich benötige, verfügt. Seine Handlanger besitzen die Runen, die ich für meine Übersetzung benötige.\n\nBeeilt Euch, <Sterblicher/Sterbliche>. Jede Minute, die verstreicht, gewinnt Malygos an Kraft.", sourceObjective = "Raelorasz im Transitusschild möchte, dass Ihr den azurblauen Kodex von Inquisitor Caleras besorgt und 3 schimmernde Runen seiner Zauberbindern von Kaltarra besorgt.", progress = "Beeilt Euch, Sterblicher.\n\nJede Minute, die verstreicht, gewinnt Malygos an Kraft.", completion = "Gut gemacht, {race}.\n\nHoffen wir mal, dass wir etwas finden, dass wir gegen Malygos verwenden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11932] = { id = 11932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feiglinge und Dummköpfe", description = "Hört mir zu, {name}. Nichts für ungut, aber die Mission, auf die sie Thassarian angesetzt haben, war ein reiner Selbstmord.\n\nEine Handvoll unserer Männer wurden losgeschickt, um einen Angriff auf die größte Ansammlung der Geißel in dieser Gegend zu starten. Nennt mich verrückt, aber ein Ziggurat der Geißel, die sich außerhalb einer verseuchten nerubischen Stadt befindet, mit nur zwölf Mann zu stürmen, ist nicht meine Art von Spaß.\n\nSolltet Ihr noch immer daran interessiert sein, Thassarian zu finden, dann hört dies: Wir sollten uns mit einem Tuskarr namens Ataika in Kaskala gen Nordosten treffen, um eine Überfahrt nach Osten zu arrangieren. Viel Glück auf Eurem vergeblichen Unterfangen.", sourceObjective = "Sprecht mit Ataika in Kaskala nordöstlich der Valianzfeste.", completion = "Ich kann mich an den Mann, von dem Ihr sprecht, erinnern. Er trug die Markierungen Karkuts.\n\nMöge Karkut unsere Gefallenen beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11933] = { id = 11933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme der Exodar", description = "Die Flamme, die aus dem Innersten der Exodar entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme der Exodar zum Geschichtenerzähler.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Dies scheint mir ein neues Feuer zu sein... Doch Ihr sagt, dass es von der Exodar stammt? Faszinierend! Dass Ihr es ins Innere des Schiffs schaffen konntet... Natürlich werde ich Euch dafür bezahlen. Solltet Ihr etwas Ähnliches finden, dann sucht mich bitte wieder auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[11934] = { id = 11934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Potenzial freisetzen", description = "Heute schaltet Ihr eine Seite in Eurem Zauberbuch frei, eine, von der Ihr gar nicht wusstet, dass sie überhaupt existiert. Bringt mir was und ich werde das Ding für Euch aufmachen.", sourceObjective = "Bringt diesem Typen ein bisschen Zeugs.", sourceObjectiveStatus = "unverified-source-field" }
quests[11935] = { id = 11935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Silbermond", description = "Diese Flamme, die aus Silbermond entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Silbermond zum Meister der Lehren.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Welch prächtiges Feuer! Ihr habt das hier in Silbermond gefunden, sagt Ihr? Unglaublich! Wer weiß, was wir mit den Flammen aller vier Städte vollbringen könnten?", sourceObjectiveStatus = "unverified-source-field" }
quests[11936] = { id = 11936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Plan ausbrüten", description = "Unser Vorhaben hier ist simpel: Wir sollen uns weiterhin vor Malygos verstecken, seine Brut beobachten und seine Pläne mit allen Mitteln vereiteln. Zu diesem Zweck habe ich eine Aufgabe für Euch.\n\nDie Blauen legen ihre Eier am Fuße des Nexus. Da sie so viel arkaner Energie ausgesetzt sind, werden sie sicherlich eher schlüpfen - und es ist nicht abzusehen, welchen Effekt es auf ihre Brut haben wird.\n\nIch habe nicht vor, das herauszufinden. Erschlagt die örtlichen Wyrmkin und benutzt ihre gefrorenen Äxte, um anschließend die Eier aufzuschlagen.", sourceObjective = "Raelorasz im Transitusschild möchte, dass Ihr Wyrmkin von Kaltarra erschlagt und mit ihren gefrorenen Äxten 5 Eier von blauen Drachen zertrümmert.", completion = "Es tut mir leid, die Vernichtung von Dracheneiern anzuordnen, ob Feind oder nicht.\n\nMöge der Zweck dieses Krieges die Mittel heiligen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11937] = { id = 11937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - all torch return quests are complete" }
quests[11938] = { id = 11938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit schinden", description = "Da wir nun über dieses Phylakterium verfügen, sollte ich keine Probleme haben, mir die benötigten Informationen zu beschaffen. Es wird jedoch nicht lange dauern, bis die Geißel in der Tempelstadt bemerkt, dass etwas faul ist.\n\nIch wäre nicht in der Lage, hier einen ausgewachsenen Angriff abzuwehren. Oder vielleicht doch? ...Ich will es lieber nicht herausfinden.\n\nIch möchte, dass Ihr dort hinuntergeht und ihnen ein paar Verluste zufügt. Hoffentlich werden sie lange genug abgelenkt sein, damit uns die beiden hier ihr Herz ausschütten können... bildlich gesprochen natürlich. Nehmt Lurid mit Euch - er wird vielleicht von Hilfe sein.", sourceObjective = "Thassarian in der Klagenden Ziggurat in der Boreanischen Tundra möchte, dass Ihr 20 Anhänger der Geißel in der Tempelstadt En'kilah erschlagt. Benutzt Lurids Knochen, falls Ihr Unterstützung benötigt.", completion = "Das sollte uns etwas Zeit verschaffen. Isidorus ist zwar kooperativ gewesen, doch ich hatte die traute Zweisamkeit mit dem Lich wirklich nötig.", sourceObjectiveStatus = "unverified-source-field" }
quests[11939] = { id = 11939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "?????" }
quests[11940] = { id = 11940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenjagd", description = "Ich brauche noch mehr Drachenjunge, um meine Untersuchung der Runen auf ihren Körpern fortzuführen.\n\nSie können in der nordwestlichen Ecke des Tals gefunden werden...\n\n<Raelorasz ritzt sich mit einem Speer in die Hand und benetzt die Spitze mit seinem Blut.>\n\nNehmt dies hier und wendet es auf eines von ihnen an. Wartet, bis es gebändigt ist, und bringt es zu mir zurück, bevor die Wirkung nachlässt.", sourceObjective = "Raelorasz möchte, dass Ihr mithilfe des mit Blut benetzten Speers ein Nexusdrachenjunges bändigt und es anschließend zu ihm zurückbringt. Er befindet sich im Transitusschild.", completion = "Das Schicksal dieser jungen Drachen muss Euer Gewissen nicht belasten, {race}. Malygos alleine trägt die Verantwortung hierfür.\n\nIch arbeite unablässig an der Lösung des Rätsels um diese Runen.\n\nLasst Euch versichern, dass wir nicht mehr Leben nehmen werden, als unbedingt notwendig.", sourceObjectiveStatus = "unverified-source-field" }
quests[11941] = { id = 11941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rätselhaft...", description = "Irgendetwas an diesem Altmetall hält Euch davon ab, es wegzuwerfen.\n\nVielleicht ist Raelorasz in der Lage, etwas Licht ins Dunkel zu bringen, welchen Nutzen das Ding hat.", sourceObjective = "Bringt das schillernde Fragment zu Raelorasz im Transitusschild.", progress = "Was habt Ihr da, {class}?", completion = "Es war eine weise Entscheidung, dies zu mir zu bringen, {name}.\n\n\n\nWenn Ihr wahrhaftig wünscht, unser Unterfangen zu unterstützen, egal wie hoch das Risiko ist, dann werde ich Euch seinen Zweck verraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11942] = { id = 11942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte der Macht", description = "Der Lich hat gesprochen, {name}. Die Hohepriester von En'kilah hüten das Geheimnis darüber, wie man Naxxanar betreten kann.\n\nGeht zur Säule des Blutes, Säule der Pein und Säule der Fäulnis und tötet jeden der Priester.\n\nKehrt wieder zurück, sobald Ihr die drei Schriftrollen an Euch gebracht habt.", sourceObjective = "Thassarian in der Klagenden Ziggurat möchte, dass Ihr in die Tempelstadt En'kilah geht und Hohepriester Talet-Khas Rolle aus der Säule der Pein, Hohepriester Nafersets Rolle aus der Säule der Fäulnis und Hohepriester Andoraths Rolle aus der Säule des Blutes besorgt.", progress = "Ihr lasst Euch Zeit, oder wie? Ich weiß nicht, wie lange ich diesen Lich noch gefesselt halten kann.", completion = "Ausgezeichnete Arbeit, {name}. Jetzt nur noch eine letzte Information.", sourceObjectiveStatus = "unverified-source-field" }
quests[11943] = { id = 11943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zelle", description = "Ihr habt ein Fragment eines speziellen Gefängnisses gefunden, {name}.\n\nMalygos' Diener sperren ihre gefangenen Magier und andere arkane Wesen in ähnlichen Gefängnissen ein, doch dieses hier wurde für etwas gebaut, das, wie soll ich sagen... stärker ist.\n\nGeht, in der Hoffnung, dass der Feind unseres Feindes unser Freund ist, und sucht die restlichen Fragmente des Gefängnisses.\n\nSie werden höchstwahrscheinlich im Besitz von Malygos' vertrautesten Untergebenen sein.", sourceObjective = "Raelorasz im Transitusschild möchte, dass Ihr General Cerulean die Gefängnisummantelung und Kriegshetzer Goredrak den Energiekern abnehmt.", progress = "Habt Ihr irgendein anderes Teil des Gefängnisses gefunden?", completion = "<Die Teile, die Ihr gesammelt habt, fangen an, in Raelorasz' Händen hell zu leuchten.>\n\nEs ist vollbracht.\n\nIch spüre die Anwesenheit eines mächtigen Wesens in diesem Gefängnis. Hoffen wir darauf, dass es sich als Verbündeter erweist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11944] = { id = 11944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umzingelt!", description = "Unsere Situation ist beinahe hoffnungslos. Uns wurde befohlen, mit einer Handvoll Männer die Klagende Ziggurat einzunehmen.\n\nWir können von Glück sprechen, wenn wir diese Position gegen die Geißel halten können. Wir sind zahlenmäßig unterlegen, haben Verletzte und sitzen in der Falle.\n\nWenn Ihr uns ein wenig entlasten könntet, wären wir in der Lage, unsere Position zu festigen. Tötet ein paar der Untoten, die sich um das Gebäude herum befinden - wir werden ihren Vorstoß abwehren.", sourceObjective = "Korporal Venn in Todeswehr möchte, dass Ihr 7 Verteidiger der Ziggurat niederstreckt.", completion = "Das sollte uns etwas Zeit verschaffen, {name}. Wir werden die Hoffnung auf Unterstützung aus der Valianzfeste nicht aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11945] = { id = 11945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf das Schlimmste gefasst sein", description = "Dunkle Zeiten sind über uns hereingebrochen. Karkuts Geist wandelt auf Erden und sammelt die Geister der toten Tuskarr ein.\n\nDie Söhne des Nebels haben viele unserer Brüder auf dem Gewissen. Bald schon wird unser geliebtes Kaskala in Schutt und Asche liegen.\n\nDoch es gibt noch Hoffnung. Vielleicht nicht für uns, aber wir haben unsere Familien nach Unu'pe geschickt. Wir kämpfen hier, um ihre Zukunft zu sichern.\n\nSie werden Vorräte brauchen, um nicht zu verhungern. Es gibt nicht genug Nahrungsmittel in Unu'pe. Bergt so viele Vorräte wie nur möglich, bevor es für unsere Familien zu spät ist.", sourceObjective = "Utaik möchte, dass Ihr nach Kaskala geht und 8 Kisten mit Vorräten von Kaskala sammelt.", progress = "Wart Ihr erfolgreich, {name}? Unsere Verwandten in Unu'pe sind von dem, was wir unternehmen, abhängig.", completion = "Ich danke Euch, {name}. Diese Vorräte werden unsere Cousins, Cousinen und Kinder mit Essen versorgen. Unser Stamm muss fortbestehen, selbst wenn Kaskala fallen sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[11946] = { id = 11946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keristrasza", description = "Ich bin... frei?\n\nIch war dazu bestimmt, für immer in einem leeren Abgrund umherzustreifen und nun bin ich errettet? Ihr könnt nicht nachvollziehen, wie dankbar ich Euch bin, <Sterblicher/Sterbliche>.\n\nAls ich mich weigerte, mich Malygos' Willen zu unterwerfen, hat er dies zu meinem Gefängnis gemacht, es zerschmettert und die Stücke verstreut. Würde ich auch Einhundert Eurer Lebenszeiten leben, vergessen werde ich Eure Gefälligkeit nicht.\n\nVielleicht werde ich mit der Zeit Wege finden, mich für Euren Gefallen erkenntlich zu zeigen. Fürs Erste müssen wir unsere Aufmerksamkeit jedoch auf Malygos richten. Ich bin schwach und es gibt viel zu erledigen.\n\nIch brauche Eure Hilfe, {name}.", sourceObjective = "Setzt das verstärkte arkane Gefängnis ein, um Keristrasza zu beschwören und mit ihr zu sprechen.\n\nBereitgestellter Gegenstand:", completion = "Wir können nicht warten, bis ich wieder zu Kräften komme.\n\nIn Bezug auf unsere Vorbereitungen muss ich mich auf Euch verlassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11947] = { id = 11947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nIm Schatten des Ethel Rethor im Nordwesten von Desolace befindet sich ein Lager. Dort haben sie Eisbrocken, mit denen sie Verbindung mit den Elementaren aufnehmen – genau so, wie sie es in Silithus machen. Ich sage das nur ungern, doch die Geister werden Verständnis haben – Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", sourceObjective = "Beschwört mithilfe des Eisbrockens am Ethel Rethor in Desolace den Leutnant des Eishagels, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf dem heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11948] = { id = 11948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nNeptulon hat schon seit längerem eine Operationsbasis auf einer Insel im Westen des Schlingendorntals. Dort hat der Schattenhammerkult Eisbrocken aufgestellt, mit deren Hilfe sie Verbindung mit dem Reich des Gezeitenjägers aufnehmen – genau so, wie sie es in Silithus machen. Ich sage das nur ungern, doch die Geister werden Verständnis haben – Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", sourceObjective = "Beschwört mithilfe des Eisbrockens auf der Insel der Wasserelementare im Westen des Schlingendorntals den Leutnant des Eiswinds, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf dem heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11949] = { id = 11949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ohne einen Kampf!", description = "Kaskala ist uns ein geheiligter Ort, {race}. Unsere Vorfahren wurden vom Geiste Tayutkas selbst hierher geführt.\n\nNun greifen uns diese scheußlichen Kreaturen grundlos aus dem Nebel heraus an.\n\nWir werden ihnen beweisen, dass unsere Speere nicht nur für den Walfang geeignet sind. Kämpft an unserer Seite, {race}. Vielleicht wird mein Volk sich in Zukunft für Eure Güte erkenntlich zeigen.", sourceObjective = "Ataika möchte, dass Ihr nach Kaskala geht und dort 12 Räuber der Kvaldir tötet.", completion = "Ich danke Euch, {name}. Ich werde tief in Eurer Schuld stehen, wenn ich hier jemals lebend davonkomme.", sourceObjectiveStatus = "unverified-source-field" }
quests[11950] = { id = 11950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muahits Weisheit", description = "Hört zu, {name}. Krieger wie ich sind entbehrlich. Sollte ich fallen, würden meine Brüder und Vettern meinen Speer aufheben und damit weiterkämpfen.\n\nAber ohne weise Ältere kann mein Volk nicht überleben. Dieser sture Muahit, der Ehrwürdigste unserer Schamanen, weigert sich, den Tayutka geweihten Altar auf der Insel in der Mitte zu verlassen. Es wäre ein schwerer Verlust, wenn diese Monster ihn erschlagen würden.\n\nIhr seid <ein Außenstehender/eine Außenstehende>, vielleicht wird er auf Euch hören. Bringt ihn zur Vernunft... bittet ihn darum, sich nach Unu'pe in Sicherheit zu bringen, bevor es zu spät ist.", sourceObjective = "Findet den Ältesten Muahit in Kaskala.", completion = "Ataika hat Euch geschickt, stimmt's? Nichts wird mich umstimmen.\n\nNoch ist nichts verloren. Die Geister sind noch immer mit uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[11951] = { id = 11951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Köder und Rute", description = "Während meiner Gefangenschaft konnte ich viel über Malygos lernen. Das Schicksal erlaubt es uns nun, dieses Wissen gegen ihn einzusetzen.\n\nEs gibt einen großen blauen Drachen, der über dem Nexus seine Kreise dreht, Saragosa. Sie dient zugleich als Wächterin des Aspekts und als seine Gefährtin. Falls irgendwelche ernsthaften Bedrohungen auftreten, alarmiert sie ihren Meister bezüglich der Gefahr.\n\nIch habe während meiner Gefangenschaft schwer unter Saragosa leiden müssen, und jetzt ist es an der Zeit für sie, zu sterben. Doch erst einmal brauchen wir den perfekten Köder...", sourceObjective = "Keristrasza hat Euch gebeten, 10 kristallisierte Manasplitter in Kaltarra zu sammeln.\n\nFalls Ihr Euer verstärktes arkanes Gefängnis verliert, sprecht mit Raelorasz beim Transitusschild.", progress = "Habt Ihr die Manasplitter gesammelt, die ich benötige?", completion = "Habt Dank, {name}.\n\nIch bin von den Folgen meiner Gefangenschaft geschwächt und meine Kraft kehrt nur langsam zurück.\n\nIch werde mit der Macht dieser Kristalle weise umgehen. Sie sind ein Nebenprodukt von Malygos' üblen Plänen. Mit etwas Glück werden sie ihren Teil zu seinem Verderben beitragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11952] = { id = 11952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nDer Feuerwachtgrat in der Sengenden Schlucht ist eine bekannte Bastion des Schattenhammerkults. Vor Kurzem haben sie damit begonnen, mithilfe der Eisbrocken in der Höhle Verbindung mit dem Reich des Gezeitenjägers aufzunehmen – genau so, wie sie es in Silithus machen. Ich sträube mich zwar sehr dagegen, doch die Geister werden Verständnis haben – Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", sourceObjective = "Beschwört mithilfe des Eisbrockens in der Höhle unter dem Feuerwachtgrat im Nordwesten der Sengenden Schlucht den Leutnant des Eises, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf dem heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11953] = { id = 11953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nSilithus ist der Hauptsitz des Schattenhammerkults auf Azeroth. Im Norden haben sie damit begonnen, mithilfe neuer Eisbrocken Verbindung mit dem Reich des Gezeitenjägers aufzunehmen. Ich sage das nur ungern, doch die Geister werden Verständnis haben - Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", sourceObjective = "Beschwört mithilfe des Eisbrockens in den Kavernen des Schattenhammers im Norden von Silithus den Leutnant des Gletschers, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte.", completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf dem heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11954] = { id = 11954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Wir müssen etwas unternehmen und das Gleichgewicht aufrechterhalten! Uns läuft die Zeit davon.\n\nUm Ahunes Gelingen zu garantieren, hat der Kult neben dem Dunklen Portal in Draenor ein Basislager errichtet. Sie verwenden Eisbrocken, um die Ankunft des Frostfürsten zu koordinieren. Ich sage das nur ungern, doch die Geister werden Verständnis haben - Ihr müsst einen von Ahunes Leutnants beschwören und ihn anschließend zerstören. Womöglich wird diese präventive Maßnahme genügen...", sourceObjective = "Beschwört mithilfe des Eisbrockens in der Nähe des Dunklen Portals auf der Höllenfeuerhalbinsel den eisigen Templer, zerstört ihn und kehrt anschließend zu einem der Urahnen des Irdenen Rings zurück. Letztere befinden sich in den Hauptstädten.", completion = "Ihr habt gute Arbeit geleistet. Es mag zwar wie ein Tropfen auf den heißen Stein wirken, doch selbst das kann positive Auswirkungen auf den Kampf insgesamt haben. Hier, nehmt dies und habt meinen Segen. Kehrt später wieder zurück - ich habe dann vielleicht mehr für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11955] = { id = 11955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahune der Frostfürst", description = "Ich glaube, dass Ihr stark genug seid, um Euch der ultimativen Aufgabe zu stellen, die uns noch bevorsteht.\n\nWir dürfen nicht zulassen, dass das eintrifft, was der Schattenhammer und Neptulons Nagaketzer vorhaben. Im Namen Azeroths und allen Lebens auf der Welt: Wir müssen handeln. Uns ist klar, was getan werden muss. Ihr müsst in die Sklavenunterkünfte tief im Inneren des Echsenkessels reisen und Euch dort mit unseren Schamanen treffen. Geht - und macht schnell!", sourceObjective = "Begebt Euch in die Sklavenunterkünfte im Echsenkessel in den Zangarmarschen und sprecht mit Numa Wolkenschwester.", sourceObjectiveStatus = "unverified-source-field" }
quests[11956] = { id = 11956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet das Phylakterium", description = "Keine Zeit für Geplauder, {name}. Ich wurde ausgesandt, um diese Ziggurat einzunehmen, was sich als purer Selbstmord erwiesen hat. Ich habe meine Pflicht als Soldat erfüllt, doch nun ist es an der Zeit, Antworten zu bekommen.\n\nDieser Lich verfügt über Wissen, das ich benötige, doch ich kann seinen irdischen Körper nicht verletzen, um an dieses Wissen heranzukommen.\n\nDer Lich bewahrt seine Seele in einem Phylakterium auf, und solange es verborgen bleibt, ist es mir unmöglich, ihm die Information zu entlocken.\n\nKehrt zum Lager zurück, nehmt mein Pferd Abenddämmerung, steigt auf und lasst Euch von ihm zum Phylakterium führen. Bringt es zu mir.", sourceObjective = "Begebt Euch nach Todeswehr und reitet mit Abenddämmerung zu der Stelle, an der sich Tanathals Phylakterium befindet. Nehmt es an Euch und bringt es anschließend zu Thassarian im Inneren der Klagenden Ziggurat.", progress = "Ihr seid zurück, {name}. Habt Ihr das Phylakterium mitgebracht?", completion = "Gerade rechtzeitig, {name}. Einen Lich festzuhalten, ist nicht so einfach, wie es aussieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11957] = { id = 11957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saragosas Ende", description = "Durch Verwendung der Manakristalle, die Ihr uns gebracht habt, habe ich diesen arkanen Fokus hergestellt.\n\nSaragosa ist ein Vielfraß. Sie wird seinen Verlockungen nicht widerstehen können. In seinem Inneren liegt Magie verborgen, die Ihre Macht erheblich verringern wird. Lasst uns hoffen, dass sie meine List nicht erkennt...\n\nMacht Euch bereit, {name}, und sprecht wieder mit mir, sobald Ihr bereit seid, Euch Saragosa zu stellen.", sourceObjective = "Keristrasza möchte, dass Ihr mithilfe des arkanen Kraftfokus' Saragosa anlockt und sie anschließend besiegt.", progress = "Saragosa darf nicht am Leben bleiben!", completion = "Diese Welt ist ein besser Ort, nun, da Saragosa nicht mehr existiert, doch unsere Arbeit ist noch nicht beendet.\n\nDie Zeit ist reif, Malygos selbst anzugreifen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11958] = { id = 11958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts darf verderben", description = "Die Wolvar sind seit jeher unsere natürlichen Feinde gewesen. Doch das Eindringen unseres Volkes in die große Drachenöde hat sie dazu gezwungen, sich auf eine kleine Lichtung im Norden zurückzuziehen.\n\nHeute Morgen war die Erde in Aufruhr - seitdem sind sie aggressiver denn je. Sie sind mehrmals über unsere Güter hergefallen... Dinge, die wir brauchen werden, wenn wir die bevorstehende Wanderung überleben wollen.\n\nSucht die Schneewehenwolvar auf und beschafft unsere Güter wieder; als Zeichen Eures guten Willens und der Freundschaft.", sourceObjective = "Beschafft von den Wolvar 6 gestohlene Güter von Moa'ki. Bringt sie zum Ältesten Ko'nani im Hafen Moa'ki zurück.", progress = "Das natürliche Gleichgewicht wurde in letzter Zeit mehrmals gestört.\n\nIch hoffe, dass Ihr uns dabei helfen werdet, den schmerzhaften Wandel unserer Lebensweise zu überleben.", completion = "Ich werde nicht behaupten, dass ich Euch gerne darum bitte, so etwas für uns zu tun. Es ist alles, was wir machen können, um unseren schnellen Aufbruch vorzubereiten - obwohl wir nicht genau wissen, wohin wir gehen sollen.\n\nMeine Zauberer sagen mir, dass Ihr gekommen seid, um das Land vor dem, der im Schatten wandelt, zu bewahren.\n\nIch vertraue darauf, dass Ihr auch das Volk dieses Landes retten werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11959] = { id = 11959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Loguhn", description = "Und schon kommt es statt schlimm noch schlimmer. Es gibt nur noch einen Weg... leider. Loguhn muss sterben!\n\nEr ist das Alphamännchen des Schneewehenstammes und ein wirklich übler Wolvar.\n\nDoch das ist die einzige Möglichkeit, eine kleine Atempause von ihren Angriffen und Raubzügen zu bekommen.\n\nIhr werdet den \"Reißer des Fleisches\" vor seiner Hütte am Nordhang der Lichtung finden. Er ist größer als die anderen und schwer zu verfehlen. Tötet ihn und zeichnet Euch mit seinem Blut, um sowohl Eure Überlegenheit als auch Euren Respekt zu zeigen.", sourceObjective = "Zeichnet Euch mit Loguhns Blut und kehrt dann zum Ältesten Ko'nani im Hafen Moa'ki zurück.", completion = "Loguhns ehrenhaftes Opfer durch Eure Hände ist genau das, was meine Leute brauchen. Jetzt werden wir das Beste mit den Wolvar machen, die um seinen Platz kämpfen.\n\nDas muss ausreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11960] = { id = 11960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukunftsplanungen", description = "Um unser Überleben zu sichern, müssen wir entschlossen gegen die Wolvar vorgehen. Ich mache mir jedoch Sorgen, dass wir in unserem Eifer zu viele von ihnen erschlagen werden.\n\nDie Schneewehenwolvar haben genauso wie wir das Recht zu überleben – also werden wir beide dafür sorgen, dass sie dieses Recht auch bekommen.\n\nWenn er es nicht schon längst getan hat, dann wird Euch Ältester Ko'nani darum bitten, mit den Wolvar fertigzuwerden. Und aus diesem Grund möchte ich auch, dass Ihr ihre Jungen einfangt und sie zu mir bringt, wenn Ihr Euch auf der Lichtung im Norden befindet.", sourceObjective = "Sammelt 12 Schneewehenwelpen und liefert sie anschließend bei Fallensteller Mau'i im Hafen Moa'ki ab.", progress = "Wie viele Jungen hättet Ihr in solch kurzer Zeit wohl retten können, hm?", completion = "Nun, ich schätze mal, dass Ihr genug von ihnen gerettet habt. Ich danke Euch, {race}.\n\nNun werden die Wolvar weiterhin mit uns überleben können - das heißt, wenn wir überhaupt überleben werden.\n\nDenkt Ihr, dass Ihr morgen wieder zurückkommen könntet, damit wir noch mehr von den Welpen retten können?", sourceObjectiveStatus = "unverified-source-field" }
quests[11961] = { id = 11961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister wachen über uns", description = "Mächtige Geister wachen über meinen Stamm - Kaskala wird nicht untergehen.\n\nIssliruk wird uns Mut verleihen, Tayutka wird dafür sorgen, dass unsere Überlebenden immer zu essen und ein Dach über dem Kopf haben, und Karkut wird über die Gefallenen wachen, damit sie nicht vom rechten Weg abkommen.\n\nDoch Issliruks Führung brauchen wir jetzt am nötigsten. Ich habe meinen Neffen Iruk darum gebeten, mir Issliruks Totem zu bringen, doch er wurde von den Speeren der Kvaldir durchbohrt und sein Körper fiel nördlich von hier ins Wasser. Bringt mir das Totem, {name}. Lasst nicht zu, dass meines Neffen Tod umsonst gewesen ist.", sourceObjective = "Ältester Muahit in der Bucht des Njordatems möchte, dass Ihr im Wasser nach Iruks Leiche sucht und Issliruks Totem bergt.", progress = "Das Totem, {race}. Habt Ihr es bei Euch?", completion = "Könnt Ihr Issliruks Gegenwart spüren, {name}? Er möchte nicht, dass seine Kinder von den Nebelläufern getötet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11962] = { id = 11962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine letzte Lieferung", description = "Das war's dann. Mithilfe der letzten Ladung Erz, die Ihr geborgen habt, sollten wir genug haben, um es zur Valianzfeste zu schicken.\n\nFalls Fernhain von der Landkarte Azeroths getilgt wird, dann lasst uns wenigstens diejenigen sein, die einst als Erste unser Land verteidigten und als Letzte aufgaben.\n\nBringt dieses Erz zu Hilda Steinschmiede - sie ist eine gute Freundin von mir. Sagt ihr, dass sie aus diesem Erz ein paar gute Waffen herstellen soll. Wir werden in Zukunft reichlich von ihnen benötigen.", sourceObjective = "Liefert die Kiste mit Erz aus Fernhain zu Hilda Steinschmiede in der Valianzfeste.", progress = "Was habt Ihr denn da?", completion = "Erz aus Fernhain? Bislang ist keine Lieferung vorgesehen. Stimmt etwas nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[11963] = { id = 11963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für Fernhain", description = "Fernhain wurde überrannt und alles, woran Gerald denkt, ist, mir meine Erzlieferung zu beschaffen? Ich versichere Euch, der Mann ist mindestens genauso beherzt wie einer unserer Soldaten an der Front.\n\nWir können nicht zulassen, dass die Zivilisten ihr Land verlieren, wenn sie dazu bereit sind, dafür zu kämpfen. Wir haben vielleicht nicht die nötigen Truppen übrig, doch wir können ihnen Waffen liefern.\n\nDiese hier waren eigentlich für die neuen Rekruten gedacht, aber mit dem Erz, das Ihr mir gebracht habt, kann ich den Bedarf abdecken. Lasst Gerald wissen, dass die Waffen auf dem Weg sind.", sourceObjective = "Kehrt zu Gerald Grün in Fernhain zurück.", completion = "Hilda schickt uns Waffen? Das sind ausgezeichnete Neuigkeiten, {name}. Ich wollte den Jungs gerade sagen, dass sie ihre Sachen packen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11964] = { id = 11964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rauchwerk für die Sommerflämmlinge", description = "Habt Ihr gewusst, dass unsere Feuer des Sonnenwendfestes in jedem Land brennen, in dem auch eine Siedlung der Allianz existiert? Sie befinden sich in den Lagern außerhalb der Städte und werden von Flammenwächtern gepflegt. Die Wächter kümmern sich darum, dass die Freudenfeuer hell brennen und die Feierlichkeiten weitergehen.\n\nJeder Flammenwächter hat einen Sommerflämmling bei sich - einen Abgesandten der Geister des Feuers.\n\nMöchtet Ihr einem Sommerflämmling Eure Ehrerbietung erweisen, {name}? Dann nehmt dieses Rauchwerk des Sommers und bringt es einem von ihnen. Besänftigt den kleinen Feuergeist und er könnte sich dafür erkenntlich zeigen.", sourceObjective = "Der Meister der Lehren möchte, dass Ihr einem SommerflämmlingRauchwerk des Sommers bringt. Die Flämmlinge befinden sich außerhalb jeder Siedlung der Allianz.", progress = "Feurige Grüße, verehrter {class}. Ihr befindet Euch auf geheiligtem Boden. Willkommen zum Sonnenwendfest.", completion = "Ah, und was haben wir denn hier? Welch angenehmes Aroma! Ich bin mir sicher, dass seine Flamme rein und hell leuchten wird!\n\nNehmt diese Blüte, {name} - nehmt und lasst mich alleine... Ich muss mich um diesen kostbaren Brennstoff kümmern...", sourceObjectiveStatus = "unverified-source-field" }
quests[11965] = { id = 11965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen!", description = "Fernhain hat nun wieder eine Chance, im Kampf zu bestehen, {name}. Das ist alles, was wir uns gewünscht haben, und Ihr habt es ermöglicht.\n\nAlles, was wir jetzt noch brauchen, ist ein Sammelpunkt. Ich werde meinen Männern sagen, dass sie die Waffen zu unserem Rathaus bringen sollen. Geht und läutet die Rathausglocke, damit alle Überlebenden wissen, wo sie sich sammeln müssen.\n\nEs ist an der Zeit, der Geißel zu beweisen, aus welchem Holz wir geschnitzt sind.", sourceObjective = "Geht zum Rathaus in Fernhain und lasst die Glocke läuten.", completion = "Danke nochmal dafür, dass Ihr uns geholfen habt, {name}. Die Einwohner Fernhains werden Euch nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11966] = { id = 11966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rauchwerk für die Festflämmlinge", description = "Habt Ihr gewusst, dass unsere Feuer des Sonnenwendfestes in jedem Land brennen, in dem auch eine Siedlung der Horde existiert? Sie befinden sich in den Lagern außerhalb der Städte und werden von Flammenbewahrern gepflegt. Die Bewahrer kümmern sich darum, dass die Freudenfeuer hell brennen und die Feierlichkeiten weitergehen.\n\nJeder Flammenbewahrer hat einen Festflämmling bei sich - einen Abgesandten der Geister des Feuers.\n\nMöchtet Ihr einem Festflämmling Eure Ehrerbietung erweisen, {name}? Dann nehmt dieses Rauchwerk des Sommers und bringt es einem von ihnen. Besänftigt den kleinen Feuergeist und er könnte sich dafür erkenntlich zeigen.", sourceObjective = "Der Geschichtenerzähler möchte, dass Ihr einem FestflämmlingRauchwerk des Sommers bringt. Die Flämmlinge befinden sich außerhalb jeder Siedlung der Horde.", progress = "Feurige Grüße, verehrter {class}. Ihr befindet Euch auf geheiligtem Boden. Willkommen zum Sonnenwendfest.", completion = "Ah, und was haben wir denn hier? Welch angenehmes Aroma! Ich bin mir sicher, dass seine Flamme rein und hell leuchten wird!\n\nNehmt diese Blüte, {name} - nehmt und lasst mich alleine... Ich muss mich um diesen kostbaren Brennstoff kümmern...", sourceObjectiveStatus = "unverified-source-field" }
quests[11967] = { id = 11967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Roten versammeln", description = "Malygos ist sich mit Sicherheit dessen bewusst, dass etwas nicht stimmt.\n\nIch kenne ihn. Seine Aufmerksamkeit ist auf mehrere Ziele gerichtet. Ich bin zuversichtlich, dass ich ihn aus der Sicherheit seines Reiches locken kann, wenn er davon erfährt, was mit seiner teuren Saragosa geschehen ist.\n\nBringt mich umgehend zu Raelorasz, {name}. Er muss jeden seiner Drachen dazu bewegen, sich Malygos zu stellen.", sourceObjective = "Keristrasza hat Euch gebeten, sie zu Raelorasz am Transitusschild zu bringen.", progress = "Habt Ihr Neuigkeiten für mich, {name}?", completion = "Mir ist die Nachricht über Keristraszas Rettung zu Ohren gekommen. Gepriesen seien Eure Taten.\n\nIch kann es kaum erwarten, wieder mit ihr zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11968] = { id = 11968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blatt wendet sich", description = "Die Geister haben unseren Hilferuf vernommen, {name}. Es ist ein Zeichen, dass Kaskala vielleicht noch gerettet werden kann.\n\nNutzt die Verwirrung aus, die das Wetter verursacht hat, und erschlagt den Anführer der Kvaldir. Euer Handeln wird die Schlacht zu unseren Gunsten wenden, da bin ich mir sicher.", sourceObjective = "Ältester Muahit möchte, dass Ihr Euch zur Bucht des Njordatems begebt und Heigarr den Schrecklichen erschlagt.", completion = "Ihr habt uns einen großen Gefallen erwiesen, {race}. Der Kampf ist noch nicht gewonnen, doch mein Volk hat nun eine Chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[11969] = { id = 11969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Falle zuschnappen lassen", description = "Dass sich mir diese Möglichkeit bietet, habe ich größtenteils Euren Mühen zu verdanken, {name}.\n\nDaher wäre es nur passend, wenn Ihr den Angriff auf Malygos einleiten würdet.\n\nNehmt diesen Funken und entzündet damit das Signalfeuer nordwestlich des Nexus. Keristrasza wird sich von dort an Eurer annehmen.", sourceObjective = "Raelorasz möchte, dass Ihr Raelorasz' Funken beim Signalfeuer in Kaltarra benutzt.", progress = "Habt Ihr Euch mit Keristrasza getroffen?", completion = "Wir haben Malygos einen Schlag verpasst, mussten es jedoch teuer bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11970] = { id = 11970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meister der Sommerlehre", description = "Eins ist sicher, unser Fest soll eine Zeit der Freude und des Lachens sein! Es ist jedoch wichtig, dass Ihr den Ursprung dieser Feiertage kennt und versteht. Bildung will ausgesucht sein und gewürdigt werden.\n\nDie Meister der Lehren in den Allianzhauptstädten werden Euch den Weg weisen können. Geht jetzt und lernt.", sourceObjective = "Sprecht mit einem Meister der Lehren in einer der Allianzhauptstädte.", completion = "Liebend gerne werde ich Euch zeigen, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[11971] = { id = 11971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Erzähler der Sommergeschichten", description = "Eins ist sicher, unser Fest soll eine Zeit der Freude und des Lachens sein! Es ist jedoch wichtig, dass Ihr den Ursprung dieser Feiertage kennt und versteht. Bildung will ausgesucht sein und gewürdigt werden.\n\nDie Geschichtenerzähler in den Hordehauptstädten werden Euch den Weg weisen können. Geht jetzt und lernt.", sourceObjective = "Sprecht mit einem Geschichtenerzähler in einer der Hordehauptstädte.", sourceObjectiveStatus = "unverified-source-field" }
quests[11972] = { id = 11972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitter von Ahune", description = "In diesen Splittern pulsiert ein Unheil verkündendes Licht. Halten sie die letzte Essenz des Frostfürsten in ihrem Inneren verborgen?", sourceObjective = "Bringt die Eissplitter zu Luma Himmelsmutter.", progress = "Seid gegrüßt, {name}. Ihr seht besorgt aus, solltet Euch jedoch freuen. Der Frostfürst ist besiegt!", completion = "Ja, diese Splitter enthalten in ihrem Inneren die letzte Essenz des Frostfürsten, die es auf dieser Welt gibt. Wir werden sie beseitigen und Ahune in die niederen Sphären der Kälte verbannen.\n\nDanke Euch, {name}. Euer Name wird für den Rest der Zeit in den Liedern des Irdenen Rings besungen werden. Bitte erweist uns eine Ehre und akzeptiert diese milde Gabe, ein Symbol Eurer Verwandtschaft mit Wärme und Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11973] = { id = 11973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsgefangene", description = "Malygos hat Keristrasza als seine Gefährtin auserkoren!\n\nDies darf nicht geschehen.\n\n{race}, Ihr müsst tun, was auch immer vonnöten ist, um ihr dieses Schicksal zu ersparen.", sourceObjective = "Kriegsmagierin Kaitlyn möchte, dass Ihr Keristrasza befreit.", completion = "So, es ist also vollbracht...\n\nWir für unseren Teil werden niemals vergessen, welch Opfer sie zu diesem Zweck gebracht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11974] = { id = 11974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nun, wenn ich einmal groß bin...", description = "Als Ihr so alt wart wie ich, wusstet Ihr dann, dass Ihr eines Tages, wenn Ihr groß seid, <ein/eine:c> {class} sein würdet?\n\nIch weiß nicht, was ich einmal werden will. Ich wollte einmal Blutritter werden, aber das will ich nicht mehr. Jetzt will ich Rockstar werden! Wie der Blutelf in L70ETC!\n\nWenn die nicht gerade auf Tour sind, dann hängen sie in Silbermond ab! Könntet Ihr mich dorthin bringen? Sie hängen auf einem Balkon in der Straße der Urahnen ab... Wahrscheinlich, damit die Fans nicht zu ihnen kommen. Aber das wird uns doch nicht davon abhalten, es trotzdem zu versuchen, nicht wahr?\n\nBitte bringt mich dorthin. Bitte!", sourceObjective = "Geht mit Eurem Waisenkind Salandria zur Straße der Urahnen in Silbermond, um L70ETC zu sehen. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11975] = { id = 11975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nun, wenn ich einmal groß bin...", description = "Vielleicht habe ich Euch das schon gefragt, aber als Ihr so alt wart wie ich, wusstet Ihr dann, dass Ihr eines Tages, wenn Ihr groß seid, <ein/eine:c> {class} sein würdet?\n\nIch weiß nicht, was ich einmal werden will. Vielleicht eine Magierin oder eine Hexenmeisterin oder ein Blutritter, wie ich davor schon mal gesagt hab? Oder vielleicht... ein Rockstar!! Wie Sig Nicious, der Blutelf, bei den 'Elite Tauren Chieftain'!\n\nHabe gehört, dass wenn die nicht gerade auf Tour sind, dann hängen sie in Silbermond ab! Könntet Ihr mich dorthin bringen? Sie sitzen auf einem Balkon in der Straße der Urahnen herum und warten darauf, dass Leute vorbeikommen.\n\nBitte bringt mich dorthin. Bitte!", sourceObjective = "Geht mit Eurem Waisenkind Salandria zur Straße der Urahnen in Silbermond, um die Elite Tauren Chieftain zu sehen. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt.", progress = "Die Elite Tauren Chieftain sind die besten!", completion = "Habt Ihr das gesehen? Die haben mir zugejubelt!!\n\nNun weiß ich, wie sie sich fühlen, wenn sie auf der Bühne stehen und singen! Ich konnte die Kraft und Energie spüren!\n\nFür mich ist es genauso wie in ihrem Lied!\n\nMy mind is made up, I am going to be a rock star when I grow up! (Mein Entschluss steht fest. Ich werde ein Rockstar sein, wenn ich groß bin!)", sourceObjectiveStatus = "unverified-source-field" }
quests[11976] = { id = 11976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eissplitter", description = "In diesen Splittern pulsiert ein Unheil verkündendes Licht. Halten sie die letzte Essenz des Frostfürsten in ihrem Inneren verborgen?", sourceObjective = "Bringt die Eissplitter zu Luma Himmelsmutter.", sourceObjectiveStatus = "unverified-source-field" }
quests[11977] = { id = 11977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Tauren unter Taunka", description = "<Wartuk deutet in Richtung Nordosten.>\n\nSie ist ziemlich freundlich, müsst Ihr wissen. Wäre Eure Abgesandte nicht gewesen, hätten die überlebenden Flüchtlinge womöglich die Hoffnung aufgegeben. Sie ist vielleicht nicht von Geburt an eine Taunka, doch der Stamm hat sie für die Zwischenzeit zur Dorfältesten auserkoren.\n\nWenn Ihr <derjenige seid, den/diejenige seid> die; ich meine, dann geht bitte zum Flüchtlingslager und stattet der Abgesandten Leuchthuf einen Besuch ab. Sie erwartet Euch.", sourceObjective = "Geht zum Flüchtlingslager von Westwind und sucht Abgesandte Leuchthuf auf.", completion = "Was Ihr hier sehen könnt, ist alles, was von den Taunka aus der Boreanischen Tundra und der Drachenöde übrig geblieben ist. Sie sind ein gebrochenes Volk... geschunden und von der Geißel fast ausgerottet.\n\n<Leuchthuf schüttelt ihren Kopf.>\n\nNur die Horde kann sie jetzt noch retten. Nur die Horde kann ihren gebrochenen Geist wieder heilen. Wir werden sie pflegen, bis sie wieder bei bester Gesundheit sind, und sie werden im Gegenzug die Horde in Nordend verstärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[11978] = { id = 11978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit offenen Armen empfangen", description = "Bevor wir diese Taunka offiziell in die Horde aufnehmen können, müssen wir den Nerubern der Anub'ar, von denen die Wälder hier in der Nähe nur so wimmeln, unsere Waffen wieder abnehmen. Sie gingen verloren, als eine Karawane von Agmars Hammer letzte Nacht in einen Hinterhalt der Geißel geriet.\n\nWagt Euch in die Wälder hinaus, die sich östlich des Flüchtlingslagers von Westwind befinden, und bringt mir diese Waffen zurück, {race}.", sourceObjective = "Abgesandte Leuchthuf im Flüchtlingslager von Westwind in der Drachenöde möchte, dass Ihr 10 Waffen der Horde beschafft.", progress = "Ohne Rüstungen und Waffen werden unsere neuesten Mitglieder schutzlos ihre Wanderung nach Agmars Hammer antreten müssen.", completion = "Das ist genau, was wir brauchen, {name}! Die Waffen der Horde zu schwingen, wird ihre Seele erfrischen und ihnen den nötigen Schutz gegen die Geißel geben.\n\nSeid Ihr bereit für das Aufnahmeritual?\n\n\n\nIhr werdet derjenige sein, der unsere neuen Verbündeten offiziell in die Horde aufnehmen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11979] = { id = 11979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Taunka und die Tauren", description = "Die Geißel hat Eisnebel, die Hauptstadt der Taunka, unter ihre Kontrolle gebracht! Alle Taunka, die das Massaker überlebt haben und fliehen konnten, wurden im Flüchtlingslager von Westwind an der westlichen Grenze der Drachenöde in Sicherheit gebracht.\n\nFürst Höllschrei glaubt, dass sich die Taunka der Horde anschließen müssen, wenn sie überleben wollen, und hat eine Taurenabgesandte nach Westwind entsandt, um unsere Beziehung zu den Wintertauren zu festigen. Reist zum Flüchtlingslager von Westwind und sucht Abgesandte Leuchthuf auf - Ihr werdet sie unterstützen.", sourceObjective = "Geht zum Flüchtlingslager von Westwind und sucht Abgesandte Leuchthuf auf.", completion = "Was Ihr hier sehen könnt, ist alles, was von den Taunka aus der Boreanischen Tundra und der Drachenöde übrig geblieben ist. Sie sind ein gebrochenes Volk... geschunden und fast ausgerottet.\n\n<Leuchthuf schüttelt ihren Kopf.>\n\nNur die Horde kann sie jetzt noch retten. Nur die Horde kann ihren gebrochenen Geist wieder heilen. Wir werden sie pflegen, bis sie wieder bei voller Gesundheit sind, und sie werden im Gegenzug die Horde in Nordend verstärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[11980] = { id = 11980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolz der Horde", description = "Ich gehörte zur Eskorte der Karawane, die mit einer Waffenlieferung auf dem Weg in dieses Lager war. Der Angriff kam schnell und ohne Vorwarnung. Wir bekämpften und erschlugen Dutzende dieser Biester, doch am Ende waren es einfach zu viele. Tor'zin und ich konnten gerade noch mit dem Leben davonkommen...\n\nWären wir nicht verletzt, würden wir uns selbst draußen in den Wäldern auf die Jagd nach diesen Scheusalen machen. Werdet Ihr uns dabei helfen, unseren verlorenen Stolz wiederzuerlangen? Sucht in den Wäldern östlich von hier nach Nerubern der Anub'ar und tötet sie! Für die Horde!", sourceObjective = "Blutwache Roh'kill im Flüchtlingslager von Westwind in der Drachenöde möchte, dass Ihr 15 Wegelagerer der Anub'ar niederstreckt.", completion = "<Roh'kill salutiert vor Euch.>\n\nIhr habt unsere Ehre bewahrt, {name}. Wir beide, Tor'zin und ich, danken Euch für diese selbstlose Tat!", sourceObjectiveStatus = "unverified-source-field" }
quests[11981] = { id = 11981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Kurun!", description = "Das Gesicht des Irdenen Kriegers ist überzogen mit Rissen und Furchen. Obwohl es ihm nicht möglich ist, zu bluten, könnt Ihr doch fühlen, dass der Krieger dem Tode nahe ist.\n\nDem Mund des Kriegers entflieht eine leise, heisere Stimme.\n\n\"Findet… Kurun... Ihr müsst Kurun... finden.\"\n\nEr schaut Euch hilflos an, als ob Ihr eine Antwort darauf geben könntet, wer oder was Kurun sein könnte.\n\n\"Unser... Anführer... er steht auf dem... Hügel, der Thor Modan überschaut... er befehligt uns. Bitte... sagt ihm... wir können die Stadt nicht... einnehmen...\"", sourceObjective = "Sprecht mit Kurun auf dem Hügel, der Thor Modan überblickt.", completion = "<Ihr überbringt Kurun die Nachricht, die der gefallene Irdene Euch gegeben hat.>\n\nSie kämpfen tapfer, aber er hat Recht. Ohne Hilfe werden wir die Eisenzwerge von Thor Modan nicht bezwingen können. Meine Riesen und die Irdenen haben lange gegen das Böse des Eisens gekämpft, aber unsere Streitmacht ist nicht groß genug, um den Kampf um Thor Modan zu gewinnen. Werdet Ihr uns helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[11982] = { id = 11982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es regnet Zerstörung", description = "Unter uns liegt die uralte Dunkeleisenbastion Thor Modan. Vor Tausenden von Jahren brachen die Steinriesen das Land entzwei, wobei Teile der Stadt zum Einsturz gebracht und ein großer Anteil des Rests freigelegt wurde.\n\nSelbst jetzt versuchen die Eisenzwerge, ihre alte Hauptstadt zurückzugewinnen, aber das werden wir nicht erlauben. Meine Riesen füllen den Graben mit Felsbrocken und Geröll, in der Hoffnung, ihn damit zu verschließen und die Eisendiener bei der Arbeit zu töten. Nehmt die Felsbrocken, die Ihr nordöstlich des Grabens findet, und helft uns, ihren Machenschaften einen Riegel vorzuschieben.", sourceObjective = "Kurun auf dem Hügel, der Thor Modan überblickt, möchte, dass Ihr die Arbeiten der Eisenzwerge dadurch stört, dass Ihr Felsbrocken in den freigelegten Bereich von Thor Modan werft.", progress = "Was habt Ihr zu berichten?", completion = "So schnell wir auch den Graben füllen, so schnell machen die Eisenzwerge ihn doch wieder frei. Wir werden die Stadt nicht allein durch den Angriff von oben einnehmen können. Ihr müsst den Irdenen helfen, die auf dem Platz unten kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11983] = { id = 11983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutschwur der Horde", description = "Sie sind bereit, {name}. Diese Taunka würden nur zu gerne der Horde beitreten und alles dafür geben, die Geißel aus der Welt zu schaffen.\n\n<Leuchthuf gibt Euch eine Schriftrolle, die das Siegel der Horde trägt.>\n\nIn dieser Schriftrolle steht der Blutschwur der Horde geschrieben. Die Tradition verlangt, dass unsere neuen Taunkabrüder- und -schwestern die darin befindlichen Worte verlauten lassen.\n\nNehmt diese Schriftrolle und verpflichtet die Taunka in den Dienst der Horde, Kommandant. Bringt die Rolle wieder zu mir zurück, wenn Ihr Euren Auftrag abgeschlossen habt.", sourceObjective = "Sprecht mit den Taunka im Flüchtlingslager von Westwind und bringt 5 von ihnen dazu, der Horde Treue zu geloben.\n\nBringt den Blutschwur der Horde wieder zur Abgesandten Leuchthuf, sobald Ihr diese Aufgabe abgeschlossen habt.", progress = "Sie werden der Horde zu mehr Kraft verhelfen, Kommandant.", completion = "Ich danke Euch dafür, Kommandant {name}. Sie hatten nichts mehr. Doch Euch ist es zu verdanken, dass sie einen neuen Sinn gefunden und damit neue Hoffnung geschöpft haben... Hoffnung auf ein Morgen... auf ein neues Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11984] = { id = 11984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Käfige vollmachen", description = "Der alte Budd hat auch schon bessere Tage erlebt.\n\nSeit unserem Aufenthalt in den Geisterlanden war er für uns komplett nutzlos. Wir mussten einen Weg finden, es selbst zu schaffen, und heutzutage bedeutet das, Trolle an den Höchstbietenden zu verkaufen.\n\nZum Glück haben wir vor Kurzem eine Verwendung für Budd gefunden. Irgendetwas an seinem Zustand erlaubt es ihm, mit den hiesigen Trollen in Kontakt zu treten, also haben wir ihm ein kleines Spiel beigebracht, das uns einigen Profit eingebracht hat.\n\nSeht selbst. Sprecht mit Budd, nehmt ihn mit in den Südwesten zu den Ruinen von Drak'Zin und benutzt diesen Käfig, sobald er einen Troll erwischt.", sourceObjective = "Samir am Granitquell möchte, dass Ihr mithilfe des Käfigs des Kopfgeldjägers einen Troll einfangt, der von Budd betäubt wurde.", completion = "Gut gemacht, {class}. Sieht so aus, als ob wir Budd noch ein wenig länger behalten werden.\n\nEuer Käfig wird gleich abgeholt. Hier ist Euer Anteil an der Belohnung.\n\nOh und willkommen im Lager. Bleibt ruhig, ich bin mir sicher, dass wir eine Verwendung für Euch finden...", sourceObjectiveStatus = "unverified-source-field" }
quests[11985] = { id = 11985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Bresche springen", description = "Wenn wir die Verteidiger in Thor Modan nicht besiegen, dann können die Eisenzwerge bis in alle Ewigkeit ausharren. Die Irdenen haben tapfer gegen die Konstrukte gekämpft, die die Söhne des Eisens aufgebaut haben.\n\nDie Tunnel verengen sich zu schnell, als dass meine Riesenkameraden uns von Nutzen sein könnten, was unsere Optionen einschränkt. Wärt Ihr bereit, Euch in die Stadt zu wagen und den Zwerg, der den Widerstand befehligt, zu töten?", sourceObjective = "Kurun auf dem Hügel, der Thor Modan überblickt, möchte, dass Ihr den Eisenthan Argrum tötet.", progress = "Ist es Euch gelungen, den Kommandanten zu töten?", completion = "Gut gemacht, {name}. Der Verlust des Kommandanten der Eisenzwerge sollte ausreichen, um die verbleibenden Verteidiger zu bezwingen. Die Irdenen sollten in der Lage sein, mit den Überlebenden fertigzuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11986] = { id = 11986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das beschädigte Tagebuch", description = "Dieses abgenutzte, mit Matsch beschmutzte Tagebuch hat auch schon bessere Tage gesehen. Beim Durchblättern fallen Euch Dutzende von Notizen, Diagrammen und Abbildungen ins Auge.\n\nDie Handschrift des Autors kommt Euch vage bekannt vor, aber Ihr könnt sie nicht einordnen, bis Ihr einen Eintrag seht, der mit dem Namen Brann Bronzebart unterschrieben ist.\n\nDie hintere Hälfte des Buches, die die jüngsten Einträge enthalten hätte, ist abgerissen worden. Seiten fliegen über das Schlachtfeld und es wird unmöglich sein, herauszufinden, was Brann entdeckt hat, bis das Buch wieder ganz ist.", sourceObjective = "Sammelt 8 der fehlenden Tagebuchseiten, ergänzt damit das Tagebuch und bringt Torthen Grabtief im Lager der Westfallbrigade das vervollständigte Buch.", progress = "Was habt Ihr da?", completion = "Ihr habt Branns Tagebuch gefunden? Das ist unglaublich! Seit einiger Zeit nun haben wir kein Lebenszeichen mehr von ihm erhalten und wir waren besorgt, dass er gefangen oder getötet worden sein könnte. Was hat er in Thor Modan entdeckt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11987] = { id = 11987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glückskarte: Silber" }
quests[11988] = { id = 11988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Runenschlüsselstein", description = "Brann erwähnt in seinem Tagebuch, dass er einen Runenschlüsselstein benutzte, um die entscheidenden Runen auf der von ihm gefundenen Scheibe zu erhellen. Ohne den Schlüsselstein ist auf der Scheibe wenig mehr als sinnloses Kauderwelsch zu lesen.\n\nAm Ende von Branns letztem Eintrag beschreibt er, wie es den Verteidigern der Eisenzwerge gelang, ihm den Schlüsselstein abzunehmen, ihn zu zerbrechen und die Einzelteile unter sich aufzuteilen. Bevor wir also die runenverzierte Scheibe entziffern können, müssen wir die Fragmente in unseren Besitz bringen. Jeder der Zwerge in Thor Modan oder in den Gebäuden drum herum könnte Fragmente bei sich haben.", sourceObjective = "Bringt Torthen Grabtief im Lager der Westfallbrigade 5 Fragmente des Runenschlüsselsteins.", progress = "Habt Ihr genügend Fragmente, um den Schlüsselstein wieder zusammenzusetzen?", completion = "<Torthen macht sich schnell daran, die von Euch gesammelten Fragmente zusammenzusetzen.>\n\nEs ist nicht vollständig, aber trotzdem sollte es uns ermöglichen, den Großteil der Informationen auf der Scheibe zu lesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11989] = { id = 11989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffenstillstand?", description = "Pass auf, Mann.\n\nDu bist <ein/eine:r> {race} und Drakuru hat mehr von euren Köpfen geschrumpft als er sich erinnern kann - und selbst wenn ich mich erinnern könnte, so weit könnt' ich gar nich' zählen. Da hast du Glück gehabt, dass ich in dies'm Käfich gefangen bin oder ich würd' der Liste glatt noch ein' hinzufüg'n. \n\nAber, da es is', wie es is', wie wär's, wenn wir unsere kleinen Meinungsverschiedenheiten kurz beseite schieben, hm?\n\nDrakuru weiß Dinge, Mann. Dinge, die dir bei deinen Anstrengungen helfen könn'.\n\n<Drakuru ritzt seine Handfläche an einem seiner Hauer ein und streckt seine Hand durch die Käfigstäbe.>\n\nAlso, was sachst du, Mann... Waffenstillstand?", sourceObjective = "Drakuru am Granitquell möchte, dass Ihr in der Nähe seines Käfigs das stumpfe Schnitzmesser benutzt und dann mit ihm sprecht.", progress = "Gute Wahl, Mann. Du wirst es nich' bereu'n…", completion = "So!\n\nNu' sin' wir durch Blut verbunden. 'Ne echte Verbindung, die wir da ham.\n\nHör Drakuru gut zu, {race}. Es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11990] = { id = 11990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phiole der Visionen", description = "Immer hübsch eins nach'm anner'n, Mann. Zuerst muss noch ein wenig Vorarbeit geleistet werden.\n\nKeine Ahnung, wie lange die mich hier behalten. Du brauchst ein mächtiges Elixier, damit wir in Kontakt bleib'n könn'.\n\nSo ein Glück, dass mir da gerade das Richtige einfällt! Un' die Zutaten finden sich alle in der Nähe.\n\nIch brauch'ne Phiole von dem hübschen kleinen Trollmädel da drüb'n, ein bisschen Wassergras aus'm See im Norden und ein paar Dunstblätter, die um das Lager herum zu finden sind.\n\nBeeil dich, Mann, bevor'se mich davonschlepp'n.", sourceObjective = "Drakuru am Granitquell möchte, dass Ihr ihm eine Kristallphiole, einen Wassergraswedel und 3 Dunstblätter bringt.", progress = "Hast du den Kram, Mann?", completion = "<Drakuru nimmt die Zutaten und verbindet sie geschickt in der Phiole.>\n\nSo viel dazu, Mann. Jetzt aber ab an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11991] = { id = 11991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Interpretationssache", description = "Da gibt's ein legendäres Set von Artefakten, seit Tausenden von Jahren verloren, hergestellt, um die Feste Drak'Tharon undurchdringlich zu machen.\n\nViele halt'n 'se für 'nen Mythos, aber Drakuru weiß es besser, Mann!\n\nIch war ganz kurz davor, herauszufinden, wo eins is', aber dann wurd' ich gefang'n, während ich dabei war, die Hieroglyphen zu deuten. Geh in den Südwesten und benutz dieses Elixier am Kohlenbecken in den Ruinen von Drak'Zin, damit ich die Deutung zu Ende bring'n kann.\n\nUm meine Seele dort zu beschwör'n, gehört in das Elixier ein bisschen gefrorenes Mojo. Ich hass' es, meine Brüder fallen zu seh'n, aber es is' ja für die gute Sache.", sourceObjective = "Drakuru möchte, dass Ihr 5 Flaschen gefrorenes Mojo von den Drakkaritrollen in den Ruinen von Drak'Zin beschafft und anschließend das Elixier bei Drakurus Kohlenbecken trinkt.", completion = "Ahh, gut... Gut gemacht, Mann.\n\nKann die Hieroglyphen auf den Mauern von hier aus gut lesen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11993] = { id = 11993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Runenprophezeiungen", description = "Wir haben keine Zeit zu verlieren! Nun, da wir den Runenschlüsselstein wieder zusammengesetzt haben - nun, fast zumindest - können wir den Inhalt der Runenplatten, an denen Brann vor seiner Flucht gearbeitet hat, entziffern.\n\nWir können nicht wissen, ob er alle drei Platten entziffern konnte, aber wir müssen einfach davon ausgehen, dass er genug Informationen gesammelt hat, um seinen nächsten Schritt zu planen.\n\nStellt Euch vor jede der Platten und benutzt den Schlüsselstein, um ihren Inhalt zu entschlüsseln. Brann könnte auf uns angewiesen sein!", sourceObjective = "Torthen Grabtief im Lager der Westfallbrigade möchte, dass Ihr die drei Runenplatten entziffert.", completion = "<Torthen hört zu, als Ihr den Inhalt der Runenplatten wiedergebt.>\n\nBei Madorans Hammer, er hat eine völlig neue Titanenstadt entdeckt!\n\n'Die Wiege von Stein und Eisen.'\n\n'Ulduar an den Sturm geschmiegt.'\n\nWas meint ihr, was das heißt? Könnte es sein, dass wir am Ende alle dorther stammen, nach all den Jahren?\n\nWir müssen ihm folgen, wir müssen ihn finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[11994] = { id = 11994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Junos Flaggentester" }
quests[11995] = { id = 11995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Sternenruh wird Eure Anwesenheit benötigt", description = "{class}, ich weiß, die Tuskarr werden Euch um viele Gefallen bitten, doch Ihr müsst so schnell wie möglich nach Sternenruh aufbrechen!\n\nDieser Aufruhr des Landes heute Morgen hat mit Sicherheit mehr Folgen, als nur den Einheimischen einige Unannehmlichkeiten zu bereiten.\n\nSternenruh liegt westlich der Kreuzung der Straße, die gen Norden aus dem Hafen hinausführt. Dort befindet sich Erzmagierin Modera. Sie wird euch erwarten.", sourceObjective = "Sprecht mit dem Abbild von Erzmagierin Modera in Sternenruh.", completion = "Ich habe Euch erwartet, {class}. Wir haben viel Arbeit vor uns, Ihr und ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[11996] = { id = 11996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Anwesenheit wird in Agmars Hammer verlangt", description = "{class}, ich weiß, die Tuskarr werden Euch um viele Gefallen bitten, doch Ihr müsst so schnell wie möglich nach Agmars Hammer aufbrechen!\n\nDieser Aufruhr des Landes heute Morgen hat mit Sicherheit mehr Folgen, als nur den Einheimischen einige Unannehmlichkeiten zu bereiten.\n\nAgmars Hammer liegt westlich der Kreuzung der Straße, die gen Norden aus dem Hafen hinausführt. Erzmagier Aethas Sonnenhäscher höchstpersönlich wird Euch erwarten!", sourceObjective = "Sprecht mit dem Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer.", completion = "Was hat denn so lange gedauert? Die Zeit wartet nur auf Aspekte, {race}.\n\nWir haben viel Arbeit zu tun - Ihr und ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[11997] = { id = 11997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefrorene Flamme", description = "Wir sollten jetzt aufbrechen, {name}. Ich kann ein Portal erschaffen, um Euch direkt hineinzubringen, aber es wird eine Weile dauern, bis ich ein weiteres erschaffen und mich Euch anschließen kann.\n\nDer Lichkönig wird ganz gewiss die magische Aura Eurer Ankunft bemerken. Ihr werdet also schnell und entschlossen handeln müssen, um Felo'melorn ausfindig zu machen und zu sichern.\n\nSollte Lyandra das Schwert haben, wird sie es nicht freiwillig hergeben. Seid auf alles gefasst, {name}.", sourceObjective = "Beschafft Felo'melorn von Lyandra Sonnenwanderer in der Eiskronenzitadelle.", completion = "Felo'melorn... Kaum zu glauben, dass in einem so eleganten Schwert so große Macht verborgen liegt!\n\nDie Legion wird dieser Waffe in Euren Händen nichts entgegenzusetzen haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[11998] = { id = 11998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schlag abschwächen", description = "Die beste Chance, unsere Streitkräfte schnell zum Eiskronengletscher zu bringen, ist das Tunnelnetzwerk unter der uralten Stadt der Eisenzwerge namens Thor Modan.\n\nBrugar Steinscher und seine Jungs von der Forscherliga werden zwar nicht sehr erfreut darüber sein, aber Befehl ist Befehl.\n\nDie Neuigkeiten würden vielleicht sogar besser rüberkommen, wenn Ihr ihm ein Fässchen vom Fusel des Fallenstellers Hugh Glass mitbringen würdet. Jener hält sich südöstlich von hier beim Handelsposten von Rotholz an der Baumgrenze auf.\n\nDer Mann ist nicht ganz richtig im Kopf, aber 'nen besseren Fusel findet Ihr hier draußen nicht.", sourceObjective = "Bringt Brugar Steinscher im Lager der Westfallbrigade ein Fässchen mit zum Heulen gutem Fusel.", progress = "Was habt Ihr denn da?", completion = "Lasst mich das einmal klarstellen: Ein {race}, den ich nicht kenne, bringt mir ein Fässchen mit dem besten Alk, den es in diesem elenden Wald gibt. Okay, na dann, was wollt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[11999] = { id = 11999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichenfleddern", description = "Die Mondruhgärten im Südwesten waren die letzte Ruhestätte einiger Hochgeborenen. Sie waren auch ein machtvoller Leyliniennexus.\n\nDer Blaue Drachenschwarm hat sich einer magischen Vorrichtung bedient, welche sie die Sognadel nennen, um diesen Nexus zu zerstören und die entfesselten Kräfte nach ihrem Willen nutzen zu können.\n\nIch brauche mehr Informationen und möchte, dass Ihr sie mir beschafft!\n\nNachdem das Land bei den Ruinen zerstört wurde, haben sich die Geister der Hochgeborenen erhoben und die anwesenden Magierjäger um die Hälfte dezimiert. Geht und durchsucht ihre Leichen nach Hinweisen.", sourceObjective = "Findet die Pläne der Mondruhgärten und bringt sie zum Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer.", progress = "Ihr seid zurückgekehrt. Was habt Ihr entdeckt?", completion = "Merkwürdig, sie streben ein Abkommen mit dem Astraleum an. Die Astralen könnten sich für Malygos und seinen Wahnsinn als machtvolle Verbündete erweisen.\n\nDas darf nicht geschehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12000] = { id = 12000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichenfleddern", description = "Die Mondruhgärten im Südwesten waren die letzte Ruhestätte einiger adliger Elfen, von Hochgeborenen. Sie waren auch ein machtvoller Leyliniennexus.\n\nDer blaue Drachenschwarm hat sich einer magischen Vorrichtung bedient, welche sie die Sognadel nennen, um diesen Nexus zu zerstören und die entfesselten Kräfte nach ihrem Willen nutzen zu können.\n\nIch brauche mehr Informationen und ich hoffe, Ihr werdet sie für mich beschaffen.\n\nNach dem Aufruhr bei den Ruinen haben sich die Geister der Hochgeborenen erhoben und die anwesenden Magierjäger um die Hälfte dezimiert. Geht und durchsucht ihre Leichen nach Hinweisen.", sourceObjective = "Findet die Pläne der Mondruhgärten und bringt sie zu Erzmagierin Modera in Sternenruh.", progress = "Ihr seid zurück. Was habt Ihr entdeckt?", completion = "Merkwürdig, sie streben ein Abkommen mit dem Astraleum an. Die Astralen könnten sich für Malygos und seinen Wahnsinn als machtvolle Verbündete erweisen.\n\nDas darf nicht geschehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12001] = { id = 12001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdtarot: Geringe Bestien", description = "Als Ihr Euren Blick auf die Karte fixiert, fängt das Bild an zu verschwimmen, sich zu verändern, bis Ihr Euch schließlich selbst sehen könnt, bekleidet mit den Fellen vieler Wölfe und Bären. Das Einzige, was Ihr daraus schließen könnt, ist, dass dies Euer Schicksal sein müsste, falls Ihr die Macht des Tarots anrufen solltet.", sourceObjective = "Sammelt 12 zerrissene Felle und benutzt anschließend das Jagdtarot, um den Jäger herbeizurufen. Ihr könnt die zerrissenen Felle nur von Bestien der Stufe 5 oder höher erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12002] = { id = 12002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brüder in der Schlacht", description = "Ich hoffe, dass Gryan weiß, dass ich meine Männer aus Thor Modan zurückgezogen habe, als die Schlacht begann. Wir können dort einfach nichts ausgraben, bevor nicht Ruhe eingekehrt ist.\n\nIhr scheint mir allerdings von der tapferen Sorte zu sein, und Ihr besitzt das Vertrauen von Starkmantel.\n\nThor Modan befindet sich gleich im Nordosten, und die Schlacht zwischen unseren irdenen Brüdern und den Schöpfungen dieser verfluchten Eisenzwerge dauert noch an. Helft unseren Brüdern, das Kräfteverhältnis auszugleichen und ich werde versuchen herauszufinden, wie wir diese Ausgrabung von Thor Modan bewerkstelligt kriegen.", sourceObjective = "Tötet 10 Runenschlachtgolems und kehrt zu Brugar Steinscher im Lager der Westfallbrigade zurück.", completion = "<Brugar hört sich Euren Bericht an.>\n\nHört sich fast so an, als würde sich die Lage langsam beruhigen. Wir werden beginnen, nach Eingängen zum Tunnelsystem der Eisenzwerge zu suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12003] = { id = 12003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach den Tunnels", description = "Wir fangen bei den abseits gelegenen Gebäuden an, nach dem Tunnelsystem zu suchen.\n\nAls ich das Gebiet mit meinen Männern verlassen habe, sah es so aus, als würden die Verteidiger der Eisenzwerge in den Gebäuden Schutz suchen. Seid vorsichtig, wenn Ihr sie untersucht.\n\nDie Eingänge zu den Tunnels werden wahrscheinlich hinten in den Gebäuden zu finden sein. Ich weiß zwar nicht genau, was Starkmantel dort zu finden erhofft, aber ich bezweifle, dass die Eisenzwerge die Suche besonders einfach machen werden.", sourceObjective = "Brugar Steinscher im Lager der Westfallbrigade möchte, dass Ihr das Nordgebäude, das Ostgebäude und das Südgebäude von Thor Modan untersucht.", completion = "<Brugar gibt einen Schwall zwergischer Schimpfwörter von sich.>\n\nKeine Eingänge? Kein einziger?\n\nWar ja klar, dass es nicht so einfach sein würde. Nun, ich denke, ein Streifzug durch die Stadt selber wird sich nicht vermeiden lassen. Meine Jungs werden nie an ihre eigentliche Arbeit zurückkehren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12004] = { id = 12004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhindert das Abkommen", description = "Wir müssen zwei Fliegen mit einer Klappe schlagen, {class} - und Ihr seid der Schläger.\n\nIn dem Fall sind unsere zwei Fliegen Windhändler Mu'fah und Goramosh. Sie sollten sich irgendwo in der westlichen Hälfte der Mondruhgärten aufhalten. Höchstwahrscheinlich befinden sie sich in dem größeren zweistöckigen Gebäude am Rande der Grube.\n\nIch hätte auch gerne einen Beweis ihres Ablebens, wenn es Euch nichts ausmacht.", sourceObjective = "Bringt Windhändler Mu'fahs Überreste und die Schuppen von Goramosh zum Abbild der Erzmagierin Modera in Sternenruh.", progress = "Habt Ihr ein Abkommen zwischen dem blauen Drachenschwarm und dem Astraleum verhindern können?", completion = "Goramoshs Bemerkung, dass es bereits zu einer Absprache gekommen sei, bereitet mir Sorge.\n\nDennoch müssen wir uns erstmal um zwei Würmer weniger Gedanken machen. Widmen wir uns also wichtigeren Angelegenheiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12005] = { id = 12005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhindert das Abkommen", description = "Wir müssen zwei Fliegen mit einer Klappe schlagen, {class} - und Ihr seid der Schläger.\n\nIn dem Fall sind unsere zwei Fliegen Windhändler Mu'fah und Goramosh. Sie sollten irgendwo in der westlichen Hälfte der Mondruhgärten sein. Höchstwahrscheinlich befinden sie sich in dem größeren zweistöckigen Gebäude, welches die Grube überblickt.\n\nUnd ich hätte gerne einen Beweis ihres Ablebens, wenn es Euch nichts ausmacht.", sourceObjective = "Bringt Windhändler Mu'fahs Überreste und die Schuppen von Goramosh zum Abbild des Erzmagiers Aethas Sonnenhäscher bei Agmars Hammer.", progress = "Habt Ihr ein Abkommen zwischen dem blauen Drachenschwarm und dem Astraleum verhindern können?", completion = "Schon gut, {class}. Legt sie einfach dort vor Agmars Thron auf den Boden.\n\n\n\nNur Goramoshs Bemerkung, dass es bereits zu einer Absprache gekommen sei, bereitet mir Sorge.\n\nDennoch müssen wir uns erstmal um zwei Würmer weniger Gedanken machen. Widmen wir uns also wichtigeren Angelegenheiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12006] = { id = 12006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rächt diese Gräueltat!", description = "Diese sogenannten Magierjäger kamen hierher und zerstörten unsere Ruhestätte.\n\nVerschafft uns Genugtuung oder ich werde dafür sorgen, dass Eure Operationsbasis von den Geistern der Toten überrannt wird!", sourceObjective = "Tötet insgesamt 15 Magierjäger der Drachenöde, Mondruhpirscher, Zauberer der Sognadel, Fokushexer oder eine Kombination aus mehreren. Kehrt zu Ethenial Mondnacht zurück, sobald Ihr das erledigt habt.", completion = "Also gut, Ihr habt getan, worum ich Euch gebeten habe, wenn nicht noch mehr.\n\nIch danke Euch, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12007] = { id = 12007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opfer müssen erbracht werden", description = "Ich hab's, Mann!\n\nIm Norden auf der Ziggurat bei Zeb'Halak gibt's einen Steinkopf mit Rubinaugen. Eines davon is' das Auge der Propheten! Bring's zu der Kohlenpfanne dort und trink mein Elixier.\n\nFür mein Elixier wirst du wieder einmal etwas Mojo benötigen – dieses Mal vom Kriegsherrn Zim'bo.\n\nEs is' nich' schön, Zim'bo zu töten, aber er hat 'nen Blutschwur geleistet, Drak'Tharon zu verteidigen, un' er hat versagt. Jetzt wird uns zumindest sein Mojo helfen, Drak'Tharon zurückzuerobern.", sourceObjective = "Drakuru möchte, dass Ihr ihm das Auge der Propheten zum Kohlenbecken in Zeb'Halak bringt.\n\nIhr müsst Zim'bos Mojo einsammeln, um Drakurus Elixier dort benutzen zu können.", progress = "Hast du das Auge der Propheten, Mann?", completion = "Das isses, Mann!\n\nUn' es is' sogar noch wertvoller, als ich gehofft hab'. Das bringt sicher mehr Leuten Hoffnung in diesen dunklen Zeiten.\n\nJetzt bloß keine Zeit verlier'n. Lass uns ma' gucken, wo das nächste Artefakt versteckt sein könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12008] = { id = 12008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agmars Hammer", description = "Direkt östlich dieses Flüchtlingslagers befindet sich Agmars Hammer - ein Zeichen dessen, welch Stärke die Horde in der Drachenöde besitzt.\n\nZwar hege ich keine Zweifel daran, dass unsere Brüder und Schwestern von der Horde schon das Ergebnis unserer Versuche sehen können, mit denen wir die Taunka zum Anschluss an die Horde bewegen wollen, doch ungeachtet dessen möchte ich, dass die Erfolgsnachricht von Euch höchstpersönlich an Oberanführer Agmar überreicht wird.\n\nGeht nun, {name}! Schnell wie der Wind! Ostwärts nach Agmars Hammer!", sourceObjective = "Reist nach Agmars Hammer in der Drachenöde und sprecht mit Oberanführer Agmar.", completion = "Während Ihr zweifellos anderswo für die Horde eingetreten seid, waren noch viel mehr mit der Erweiterung unseres Machtbereichs ins Landesinnere von Nordend beschäftigt. Selbst während wir hier noch sprechen, errichten unsere Streitkräfte Basen auf den gefrorenen Weiten dieses trostlosen Ödlands.\n\nWir haben die Geißel umzingelt. Der Sieg rückt näher, während sich unsere Armeen in Massen am Fuße Angrathars, der Pforte des Zorns, versammeln. Bald schon werden wir das Tor niederreißen und zur Eiskrone durchbrechen können.\n\nDoch es gibt noch viel Arbeit zu erledigen...\n\nZuerst müssen wir die Neruber aufhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[12009] = { id = 12009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tua'keas Krabbenfallen", description = "Wegen all der Probleme hab' ich alle meine Gehilfen verloren. Ich wollte nur einmal fragen, ob Ihr mir vielleicht helfen könnt?\n\nIch hab' überall hier im Wasser meine Krabbenfallen aufgestellt. Könntet Ihr sie mir zurückbringen? Ich bin zu alt für so etwas und die See kann sehr gefährlich sein.\n\nHier, bitte, nehmt diesen Atmungssack. Er wird Euch mit Luft versorgen, solange Ihr dort unten seid.", sourceObjective = "Sammelt 8 von Tua'keas Krabbenfallen ein und bringt sie wieder zu ihm. Er befindet sich im Hafen Moa'ki.", progress = "Wie viele Krabben habt Ihr denn mitgebracht?", completion = "Ich bin nur ein einfacher Fallensteller. Die Welt steht plötzlich Kopf. Es ergibt einfach keinen Sinn.\n\nIch hoffe, dass Ihr's wieder richten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12010] = { id = 12010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal Orlonds", description = "Als wir mit den Ausgrabungen begonnen haben, habe ich Feldmesser Orlond losgeschickt, die Stabilität der Tunnel in Thor Modan zu überprüfen. Ich habe ihn nicht entkommen sehen, als wir uns zu Beginn der Schlacht zurückzogen, und mache mir Sorgen, dass er noch immer in der Stadt gefangen ist.\n\nWenn wir eine Armee durch Thor Modan bewegen wollen, brauchen wir die Informationen, die er gesammelt hat. Starkmantel und seine Vorgesetzten würden mir die Haut abziehen, wenn eine Brigade unter den Tunneln begraben würde!", sourceObjective = "Findet Feldmesser Orlond innerhalb Thor Modans.", completion = "Eine kurze Untersuchung der Leiche ergibt, dass der Feldmesser schon geraume Zeit tot ist. In seiner Tasche findet Ihr einige handgeschriebene Notizen Orlonds.", sourceObjectiveStatus = "unverified-source-field" }
quests[12011] = { id = 12011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anzeichen großen wässrigen Ärgers", description = "Diese Krabbenfalle scheint von irgendwas zerstört worden zu sein, das viel größer ist, als die Haie, die in der Nähe umherkreisen.\n\nSollte Tua'kea, der Fischer im Hafen Moa'ki, vielleicht davon erfahren?", sourceObjective = "Informiert Tua'kea im Hafen Moa'ki über die zerstörte Krabbenfalle.", completion = "Das sind nicht gerade die Nachrichten, die ich hören wollte, {race}.\n\nNein, nein... es ist gut, dass Ihr's mir gesagt habt, doch ich befürchte, dass mein alter Erzfeind in diese Gewässer zurückgekehrt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[12012] = { id = 12012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Urahnen benachrichtigen", description = "Hiervon muss der gesamte Irdene Ring erfahren. Ich bin mir nicht sicher, wie es weitergehen soll, doch der Urahne, von dem Ihr überhaupt erst diese Aufgabe bekommen habt, könnte es wissen. Ich bitte Euch, kehrt zum Urahnen zurück und findet heraus, wie es weitergehen soll - wir müssen etwas unternehmen!", sourceObjective = "Reist in eine der Hauptstädte und sprecht mit dem Urahnen des Irdenen Rings.", completion = "Das sind in der Tat schlimme Neuigkeiten. Wir müssen alles tun, was in unserer Macht steht, um diesen Krieg zu verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[12013] = { id = 12013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg mit Arkanimus", description = "Es gibt eine letzte Sache, die Ihr für mich tun müsst, {class}. Ich möchte, dass Ihr Arkanimus für mich vernichtet!\n\nDie Zauberer im Westen benutzten dieses riesige Gerät am Himmel, um eine enorme Grube in unsere Ruhestätte zu bohren. Als sie dies taten, ließen sie das Ungeheuer frei!\n\nEs würde mich nicht stören, wenn es nur die Lebenden etwas anginge, doch Arkanimus ernährt sich von den Geistern der Toten.\n\nIhr werdet dem jetzt ein Ende bereiten!", sourceObjective = "Vernichtet Arkanimus und kehrt zu Ethenial Mondnacht bei den Mondruhgärten zurück.", completion = "Ihr habt meinen tiefsten Dank, {name}.\n\nFalls nicht schon geschehen, solltet Ihr Eure Vorgesetzten über die Gefahr informieren, die der blaue Drachenschwarm entfesselt hat. Indem sie den Leylinienanker unter den Gärten zerstören, drohen sie, uns alle zu vernichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[12014] = { id = 12014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fels in der Brandung?", description = "Orlonds Aufzeichnungen deuten darauf hin, dass er einen Ausrüstungsgegenstand namens \"tragbarer Seismograph\" mitbrachte, doch das Gerät ist nirgendwo zu finden.\n\nDie Messwertaufzeichnungen zeigen, dass Orlond all seine Messungen in den Tunneln von Thor Modan durchführte, bis auf eine einzige, die mit der Aufschrift \"östliches Ende der freigelegten Tunnel\" gekennzeichnet ist.\n\nDer letzte Eintrag in dem Buch deutet darauf hin, dass Orlond versuchte, im Wasser Zuflucht zu finden, und von unterirdischen Dreschern angegriffen wurde. Womöglich haben sie seine Ausrüstung mitgenommen. Ihr müsst es wiederbeschaffen, bevor Ihr die letzte Messung durchführen könnt.", sourceObjective = "Beschafft den tragbaren Seismographen und führt mit ihm Messungen durch, um die Stabilität in Thor Modan zu untersuchen. Kehrt anschließend zu Brugar Steinscher im Lager der Westfallbrigade zurück.", progress = "Was habt Ihr gefunden?", completion = "<Brugar überfliegt den Bericht.>\n\nDas ist gar nicht gut. Selbst wenn wir die Tunnel hinter der Blockade ausgraben könnten, hätten wir noch immer keine Garantie dafür, dass sie nicht einstürzen würden. Es sieht so aus, als wären ein paar dieser Bereiche seit Generationen nicht besucht worden. Wir werden Hauptmann Gryan die schlechten Neuigkeiten überbringen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12016] = { id = 12016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Köder", description = "Ich bin mir sicher... dass unser uralter aquatischer Erzfeind Tu'u'gwar, \"Der mit dem Essen spielt\", zurückgekehrt ist. Wir, das heißt Ihr und ich, müssen ihm eine Falle stellen.\n\nWenn Tu'u'gwar eine Schwäche hat, dann ist das sein Magen. Es gibt eine Sorte Fleisch, zu der er sicherlich nicht Nein sagen könnte.\n\nKili'ua, \"Zwei Gewaltige Scheren\", die Mutter aller Krabben, lebt auf einer Insel gen Südwesten. Ihr müsst Ihr einen Besuch abstatten und mir ihr Fleisch bringen.", sourceObjective = "Besorgt das Fleisch von \"Zwei gewaltige Scheren\" und liefert es bei Tua'kea im Hafen Moa'ki ab.", progress = "Habt Ihr Kili'uas saftiges Fleisch mitgebracht?", completion = "Wenn Ihr Kili'ua niederstrecken konntet... vielleicht könnt Ihr dann auch dasselbe mit Tu'u'gwar machen.\n\nVielleicht aber auch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12017] = { id = 12017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleisch am Haken", description = "Die Zeit ist gekommen, <mein Freund/meine Freundin>: wir müssen uns um Tu'u'gwar kümmern!\n\nIch habe das Fleisch so präpariert, dass das Biest mit Sicherheit kommen wird, sobald Ihr den Haken draußen im Wasser mit einem Köder verseht. Folgt einfach der Angelschnur hier und Ihr werdet ihn finden.\n\nWas auch immer Ihr macht, Tu'u'gwar darf Euch auf keinen Fall verschlingen, {name}!", sourceObjective = "Streckt Tu'u'gwar nieder und kehrt anschließend zu Tua'kea im Hafen Moa'ki zurück.", progress = "Ich meine gesehen zu haben, dass das Wasser aufgewühlt wurde... Ist Tu'u'gwar tot?", completion = "Wir freuen uns über Euren Erfolg, mein junger Freund! Da schwimmt Blut im Wasser und es ist das Blut unseres Feindes!\n\nDieser alte Fischer wird Euch auf ewig dankbar sein und mit Sicherheit auch alle Kalu'ak, sobald ich die Neuigkeit verbreitet habe!\n\nHier, ich bestehe darauf - nehmt bitte etwas als Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12018] = { id = 12018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache ist süß", description = "Du da... Du siehst nach einem Kämpfer aus. Seit die Geißel meine Familie ermordet hat, gelüstet es mich nach Rache. Besorgt mir 2 Gargoylekieselhaufen, damit ich sie zu Boden schmettern und auf ihnen herumtrampeln kann, bis sie in klitzekleine Stücke zersprungen sind.\n\nLos. Geht. Tötet.", sourceObjective = "Beschafft Euch 2 Gargoylekieselhaufen von Aasgargoyles von den östlichen Aasfeldern. Kehrt zu Lord Bevis zurück, sobald Ihr die Aufgabe erfüllt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12019] = { id = 12019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Riten", description = "Im Tod diente ich Arthas, denn ich hatte keine Wahl. Er hatte die Kontrolle über meinen Willen und meinen Körper. Die Mitglieder des Kults der Verdammten dienen Arthas als Lebende... aus freien Stücken.\n\nJetzt, da wir wissen, wie wir mit den Machtworten Naxxanar betreten, können wir dieser Kultistenseuche ein Ende bereiten. Geht nach En'kilah und sucht unter der schwebenden Zitadelle nach der Teleportationskugel.\n\nArbeitet Euch nach oben durch und trefft mich ganz oben. Bewaffnet Euch mit all Eurem Mut. Es kann sein, dass wir da nicht lebend rauskommen.", sourceObjective = "Geht zur Tempelstadt En'kilah und sucht die Teleportationskugel unter der schwebenden Geißelzitadelle von Naxxanar. Benutzt sie, um ganz nach oben zu gelangen und helft dort Thassarian.", completion = "Ihr habt Euch gut geschlagen, {name}. Ich hatte gehofft, meine Schwester vor alledem bewahren zu können. Dank Euch ist sie am Leben und wohlauf.\n\nMeine Pflicht gegenüber meinem König und meiner Armee ist getan. Es ist offensichtlich, dass ich unter meinen Kameraden nicht länger willkommen bin. Ich werde meinen eigenen Weg finden müssen, wo ich niemandes Kriege mehr schlage als meine eigenen und niemand anderem mehr folge als meinem Herzen.\n\nVielleicht sehen wir uns eines Tages wieder, {class}. Bis dahin nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[12020] = { id = 12020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dieses eine Mal, als ich betrunken war...", description = "Die Dunkeleisenzwerge haben einstecken müssen! Als sie zurück zum Grimmigen Säufer rannten, fiel ein Teil ihrer Ladung herunter. Was jedoch noch viel wichtiger ist: Dank Euch ist das Lager außer Gefahr... zumindest für heute.\n\nGeht zu Boxi und erzählt ihm von Eurem heldenhaften Sieg über die Dunkeleisenzwerge.", sourceObjective = "Sprecht mit Boxi Bolzendreher im Braufestlager.", completion = "Ihr konntet die Dunkeleisenzwerge also aufhalten... und wart dazu noch betrunken? Genau das ist es, {class}, worum es beim Braufest geht! Und wo wir schon mal dabei sind: Denke mal, dass Ihr Eure Biermarken haben wollt.\n\nDanke für Eure Hilfe, {name}. Weiterhin noch viel Spaß auf dem Braufest.", sourceObjectiveStatus = "unverified-source-field" }
quests[12021] = { id = 12021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Brief in die Heimat", description = "Der Brief wurde offenbar von einem verstorbenen Dorfbewohner der Aasfelder an einen Einwohner Sturmwinds adressiert. Vielleicht ist einer der überlebenden Dorfbewohner im östlichen Lager gewillt, ihn zu seinem vorgesehenen Empfänger zu bringen.", sourceObjective = "Bringt den Brief zu Lady Alustra in den östlichen Aasfeldern.", sourceObjectiveStatus = "unverified-source-field" }
quests[12022] = { id = 12022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haut weg das Zeug!", description = "Hey, Ihr seht aus, als hättet Ihr Euer Bräu fest im Griff!\n\nAber seid Ihr auch gut darin, es loszulassen?\n\nWir sorgen im Lager gerne für gute Stimmung und da geht doch nichts über eine gute, alte Runde Krugelstoßen!\n\nIhr glaubt, Ihr hättet das Zielvermögen, A.L.K. treffen? Schnappt Euch einen Freibierkrug, genehmigt Euch einen Schluck und schaut, ob Ihr einen Treffer landet. Ist schwieriger, als es aussieht, aber das ist ja der Spaß an der Sache. Tretet ruhig heran und versucht es mal!", sourceObjective = "Trefft A.L.K. fünfmal mit dem Krug alkoholfreies Braufestbier.", progress = "Hebt einen zu Euch und werft dann einen zu Ihr. A.L.K. hält das aus, dafür habe ich sie ja gebaut.", completion = "Wisst Ihr, was das war? Gnomische Ingenieurskunst von ihrer besten Seite! A.L.K. hat das weggesteckt wie ein Champion!\n\nIch glaube Ihr seid jetzt bereit, wenn die Dunkeleisenzwerge das nächste Mal wieder auftauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12023] = { id = 12023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch süßere Rache", description = "Schön knackig. Nun... zu Euch... Ihr, Ihr, {race}, Ihr... Es gibt eine Monstrosität, die am Südhang entlang wandert. Geht und bringt sie um. Sorgfältig.", sourceObjective = "Tötet die Monstrosität am Hang in den Östlichen Aasfeldern. Kehrt sofort zu Lord Bevis zurück, wenn Ihr mit der Hinrichtung fertig seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[12024] = { id = 12024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefallenen registrieren", description = "Danke, dass Ihr gekommen seid, {name}. Wir haben noch keine Nachricht von Wintergarde erhalten. Ich bin mir sicher, dass sie noch immer gegen die Geißel kämpfen, doch ich kann es gar nicht glauben, dass sie uns bei diesem Gemetzel im Stich gelassen haben.\n\nWir müssen die Namen aller Toten sammeln, damit wir ihre Familien benachrichtigen können. Als uns das Militär der Allianz hierher brachte, musste ein jeder von uns Siedlungspapiere ausfüllen und sie ständig bei sich tragen.\n\nGeht nun, durchsucht die Leichen und bringt mir alle Dokumente, die Ihr finden könnt, damit ich eine Namensliste anfangen kann.", sourceObjective = "Durchsucht die Skelette auf den Aasfeldern nach Siedlungsdokumenten der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[12025] = { id = 12025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Scharlachroter unter uns", description = "Gut zu sehen, dass nicht auch Ihr von der Geißel entstellt wurdet. Vielleicht möchtet Ihr uns hier zur Hand gehen.\n\nDer Scharlachrote Kreuzzug hat im Norden Stellung bezogen, um offensichtlich die Geißel zu bekämpfen. Was mich jedoch beunruhigt, ist, dass sie schon mit dem Bau beschäftigt waren, bevor wir angegriffen wurden - sie müssen irgendwelche Informationen gehabt haben.\n\nIch muss unbedingt wissen, ob einer unserer Dorfbewohner darin verwickelt gewesen ist. Sucht bei denjenigen von uns, die als Ghule zurückgebracht wurden, nach Hinweisen. Egal was Ihr findet, bringt es mir.", sourceObjective = "Sucht bei den erst kürzlich auferstandenen Aasghule in der östlichen Gegend der Aasfelder nach Beweisen hinsichtlich des Scharlachroten Kreuzzugs. Bringt Lady Alustra alles, was Ihr finden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12026] = { id = 12026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das beschädigte Tagebuch", description = "Dieses abgenutzte, mit Matsch beschmutzte Tagebuch hat auch schon bessere Tage gesehen. Beim Durchblättern fallen Euch Dutzende von Notizen, Diagrammen und Abbildungen ins Auge.\n\nDas einzige Stück Text, das Ihr lesen könnt, ist ein Eintrag, der mit dem Namen Brann Bronzebart unterschrieben ist.\n\nDie hintere Hälfte des Buches, die die jüngsten Einträge enthalten hätte, ist abgerissen worden. Jemand hielt die Notizen für wichtig genug, um sie zerstören zu wollen. Wenn Ihr die fehlenden Seiten auf dem Schlachtfeld finden könntet, würden sie vielleicht brauchbare Hinweise liefern.", sourceObjective = "Sammelt 8 der fehlenden Tagebuchseiten, ergänzt damit das Tagebuch und bringt der Weisen Paluna im Camp Oneqwah das vervollständigte Buch.", progress = "Was ist das, was Ihr da habt?", completion = "Wer ist dieser Brann Bronzebart? Die Eisenzwerge hatten keine Verwendung für ihn und ich verstehe nicht, warum wir ein Interesse an seinen Notizen haben sollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12027] = { id = 12027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mr. Floppys gefährliches Abenteuer", description = "Entschuldigt bitte, <mein Herr/meine Dame>, wisst Ihr den Weg zurück zum Soldatenlager?\n\nMr. Floppy und ich wollten einen Spaziergang im Wald machen und mein Bruder Walter sollte mit uns kommen, aber dann musste er Knappenaufgaben erledigen.\n\nAlso gingen Mr. Floppy und ich alleine, aber wir haben uns verlaufen und da war ein ganzer Haufen hungriger Wölfe. Da haben wir diesen Turm gefunden.\n\nDie Wölfe haben sich verzogen, aber wir wissen immer noch nicht, wo wir sind.\n\nIch habe Mr. Floppy gefragt, aber er weiß den Weg auch nicht. Würdet Ihr uns helfen? Bitte?", sourceObjective = "Helft Emily und Mr. Floppy, den Weg zurück zum Lager der Westfallbrigade zu finden, dann sprecht mit dem Knappen Walter.", completion = "Dem Himmel sei Dank, dass Ihr Emmy gefunden habt! Als sie ohne mich losgezogen ist, habe ich mir große Sorgen gemacht.\n\nIch freue mich auch, dass Mr. Floppy wohlbehalten wieder zurück ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[12028] = { id = 12028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirituelle Eingebung", description = "{race}, seitdem die Erde bebte und sich auftat, haben wir nichts mehr von unseren Leuten in Indu'le gehört!\n\nHabt Ihr schon einmal versucht, mithilfe einer Vision etwas in Erfahrung zu bringen? Ich meine, dass Loguhns Bezwinger auch dazu imstande wäre.\n\nIch werde Euch einen besonderen Weihrauch geben, den Ihr dann in meine Kohlenpfanne streuen müsst. Atmet seine Dämpfe tief ein und Euer Geist wird emporgehoben werden. Auf diese Weise könnt Ihr herausfinden, was sich in Indu'le ereignet hat.\n\nSolange Euer Geist frei dahinschwebt, werde ich durch Eure Augen blicken können.", sourceObjective = "Sprecht mit Toalu'u dem Mystiker im Hafen Moa'ki, nachdem Euch die spirituelle Eingebung zuteil wurde.", progress = "Was denkt Ihr?", completion = "Geister und dahingestammelter Unsinn? Das kann nicht sein!\n\nWir brauchen mehr Rat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12029] = { id = 12029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die angesengte Geißel", description = "<hicks>... Muss diese Leischen verbrennen, bevor sie anfangen rumzuwandern.\n\nPapa hat immer gesagt, das Einzige, was schlimmer is', als 'nen Troll töten zu müssen, is', ihn zweimal töten zu müssen.\n\nSagt mal, <hicks>... wegen der Geißel, wir kommen nisch in die Trollfestung im Norden, bis diese Trolle 'n bisschen weniger geworden sind.\n\nWie wär's, wenn Ihr was von mei'm Grog hier nehmt und die Bastarde von ihrem Leid erlöst?", sourceObjective = "Mack beim Granitquell möchte, dass Ihr seinen Grog benutzt, um 20 ausgemergelte Geißeltrolle in Drak'Tharon zu verbrennen.", completion = "Gut gemacht!\n\n<Mack lacht eine Weile hysterisch.>\n\nOoch, jetzt kommt schon. Das war lustisch...<Hick>.", sourceObjectiveStatus = "unverified-source-field" }
quests[12030] = { id = 12030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mana'loa der Älteste", description = "Mein Volk...\n\n<Der Mystiker ist kurz davor zusammenzubrechen.>\n\nAls Euer Geist durch das Dorf flog, spürte ich, dass der Älteste Mana'loa Euch bemerkte. {name}, er möchte mit Euch sprechen. Die Steinältesten gelten bei uns als Quell uralter Weisheiten und werden deswegen verehrt.\n\nDer Älteste muss helfen wollen. Ihr findet ihn in der nordwestlichen Ecke des Dorfes.", sourceObjective = "Sprecht mit der Statue vom Ältesten Mana'loa in Indu'le.", completion = "Ich habe Euch erwartet, {race}. Ich sah, wie Euer Geist vorbeiflog, und spürte den Blick des Mystikers in Euren Augen.\n\nEuer Schicksal und das der Kalu'ak sind nun eins.", sourceObjectiveStatus = "unverified-source-field" }
quests[12031] = { id = 12031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit den Verweilenden", description = "Der geheiligte Boden der Elfen im Westen wurde aufgerissen. Nun fließt ihre magische Energie übers Land und hinterlässt eine Spur der Verwüstung.\n\nDie Versuche des blauen Drachenschwarms, die Magie zu kontrollieren, stellen eine Gefahr für die Seelen der Kalu'ak dar.\n\nDie Energie kam aus den Tiefen des Sees. Für die meisten Dorfbewohner brachte sie den plötzlichen Tod und die Überlebenden trieb sie in den Wahnsinn.\n\n{name}, Ihr müsst diese Geister von ihrer Qual erlösen, damit sie ihre Reise fortsetzen können. Lasst die Wahnsinnigen jedoch in Frieden; vielleicht werden sie eines Tages wieder zu Verstand kommen.", sourceObjective = "Erlöst insgesamt 15 Geister von Indu'le, egal ob Fischer, Mystiker oder Krieger, und kehrt anschließend zum Ältesten Mana'loa in Indu'le zurück.", progress = "<Ältester Mana'loa durchschaut Euch. Er spürt, dass Ihr seinen Auftrag noch nicht ausgeführt habt.>", completion = "Nicht unbedingt die angenehmste Aufgabe, doch eine notwendige und gnadenvolle.\n\nDa wäre noch eine andere Sache, die Ihr für die Kalu'ak erledigen müsst und zu deren Erfüllung Ihr bestimmt seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[12032] = { id = 12032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräche mit den Tiefen", description = "Die Meeresgöttin Oacha'noa muss befragt werden. Nur sie wird wissen, welches Schicksal die Kalu'ak erwarten wird. Wisset auch, dass nur die Perle der Tiefen sie aus dem trüben Abyssal hervorlocken kann.\n\nVor der Südwestküste befindet sich die Salzzinne und auf ihr der Altar, auf dem auch die Perle liegt.\n\nNehmt am Altar mit Oacha'noa Verbindung auf und sie wird mit Sicherheit Eurem Ruf folgen. Tut, was sie verlangt, sonst werdet Ihr ihren Zorn auf Euch ziehen und damit auch das Ende aller Tuskarr einläuten.\n\nKehrt wieder zum Mystiker zurück, falls Ihr überleben solltet.", sourceObjective = "Nehmt mithilfe der Perle der Tiefen Verbindung mit der Meeresgöttin Oacha'noa auf und tut, was sie befiehlt.\n\nKehrt zu Toalu'u dem Mystiker im Hafen Moa'ki zurück, falls Ihr die Feuerprobe bestehen solltet.", completion = "Ihr habt mit Oacha'noa gesprochen?!\n\nNun, wenn es Ihr Wille ist, dass wir uns mit Eurem Volk verbünden sollen, dann soll es so sein. Ältester Ko'nani wird dies als unser Schicksal akzeptieren, ob zum Guten oder Schlechten.\n\nMein Volk glaubt, dass alle Seelen eins mit der Magie der Welt sind. Wir müssen die blauen Drachen davon abhalten, die Magie zu kontrollieren, oder wir sind verloren!\n\nIch hätte niemals gedacht, dass jemals ein {race} der Held der Kalu'ak sein würde, doch Ihr habt das Gegenteil bewiesen. Im Namen meines Volkes will ich mich bei Euch bedanken, {name}.\n\nMöget Ihr die Gunst und den Schutz der Götter ernten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12033] = { id = 12033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht aus dem Westen", description = "<Torvus schüttelt Eure Hand und steckt Euch heimlich einen Brief zu.>\n\n<Torvus flüstert leise.>\n\nSpielt einfach mit, {name}.\n\nSchön, Euch hier zu sehen, Soldat! Fürst Höllschrei hat Oberanführer Agmar zweifellos seine kräftigsten Krieger geschickt!\n\n<Torvus flüstert wieder.>\n\nLest ihn und werft ihn danach in den Feuerkrug neben mir.", sourceObjective = "Lest den Brief von Saurfang und zerstört ihn anschließend.\n\nSprecht mit Bote Torvus, sobald Ihr die Aufgabe abgeschlossen habt.", completion = "<Torvus nickt Euch zu.>\n\nHaben wir uns also verstanden? Ich werde zu meinem Fürsten zurückkehren und ihm sagen, dass Ihr eingewilligt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12034] = { id = 12034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sieg ist nahe...", description = "Die wahre Bedrohung geht jetzt nur noch von zwei Orten aus: der Schreckenszitadelle Naxxramas, die weit im Osten über der Allianzfestung Wintergarde schwebt, und der Grube von Narjun, durch welche die untoten Armeen von Azjol'Nerub an die Oberfläche gelangen. Es war auch genau diese Grube, aus der die Neruber der Anub'ar kamen, als sie das Taunkadorf Eisnebel angriffen und es letztendlich dem Erdboden gleichmachten.\n\nWir werden die Anub'ar vernichten und die Grube von Narjun zuschütten.\n\nMeldet Euch bei Schlachtrufer Juktok; er wird Euch über Einzelheiten informieren.", sourceObjective = "Sprecht mit Schlachtrufer Juktok in Agmars Hammer.", completion = "Zu Land und aus der Luft - so werden wir der Bedrohung durch die Anub'ar ein Ende setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12035] = { id = 12035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederverwertung von Technologie", description = "Okay, ich hab's! Die Neuverkabelung ist etwas kompliziert, aber nichts, was <ein cleverer/eine clevere:c> {class} wie Ihr nicht hinbekommen würde.\n\nNehmt meine Werkzeuge und setzt ein paar der Erntesammler außer Betrieb. Wenn das erledigt ist, benutzt die Werkzeuge, um alle roten Drähte in die blauen Buchsen zu stecken. Dadurch werden sie in den Selbstverteidigungsmodus übergehen. Beeilt Euch, {name}. Nicht mehr lange und es wird nicht mehr viel zu retten übrig sein.", sourceObjective = "Jeremias Hohning in Fernhain möchte, dass Ihr 5 Erntesammler zerstört und dann Jeremias' Werkzeuge benutzt, um sie neu zu verkabeln.", completion = "Gute Arbeit! Ich fühle mich endlich wieder nützlich... und das soll was heißen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12036] = { id = 12036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den Tiefen von Azjol-Nerub", description = "Die untoten Neruber, die Eisnebel angriffen, kamen aus einem gigantischen Schlundloch, das \"die Grube von Narjun\" genannt wird. Wenn sich niemand um sie kümmert, werden diese Scheusale unseren Truppen an der Pforte des Zorns in die Flanke fallen und unserem Siegeszug ein jähes Ende bereiten.\n\nIch brauche Späher vor Ort, {name}. Geht nach Westen und untersucht die Grube von Narjun. Wir müssen ihren Hauptausgang finden und ihn versiegeln! Findet heraus, wo er sich befindet.", sourceObjective = "Erforscht die Grube von Narjun und kehrt anschließend mit dem, was Ihr gefunden habt, zu Schlachtrufer Juktok in Agmars Hammer zurück.", completion = "Dieses verdammte Schlundloch muss direkt mit Azjol-Nerub verbunden sein. Es ist schlimmer als ich dachte.\n\n<Juktok hält einen Moment lang inne, um nachzudenken.>\n\nSuchen und vernichten... So wird unsere nächste Vorgehensweise aussehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12037] = { id = 12037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungsaktion", description = "Orcs... die hör'n einfach nich' zsch... zsch... zu... <Hick>! Wisst Ihr, was ich mein', {race}?\n\nKurzel is' schon seit Jahr'n bei uns. Man sollte denk'n, sie hätte mittlerweile begriff'n, wie die Dinge bei uns ablauf'n. Lock die Narren für die gefährliche Arbeit her, dann greif die Beute ab, wenn die Gefahr vorüber is'. Was is' daran scho schwer zu versteh'n?\n\nSie versteht's nich'... die läuft losch und will die Sache selbscht inne Hand nehmen. Wahrscheinlich isse schon tot, aber ich würd' mich schrecklich fühlen, wenn wir ihr nicht folgen würd'n... nur bin ich in keiner Verfassung dazu... <Hick>!\n\nAlso, was sagt Ihr, Kumpel?", sourceObjective = "Mack beim Granitquell möchte, dass Ihr nach Drak'Tharon geht und herausfindet, was mit Kurzel passiert ist.", completion = "Ich wusste es!\n\nSelbscht, nachdem ich eine Weile verschwunden war, sind mir diese rückgratlosen Ratten nich' nachgekomm'n.\n\nNun, sie ham Euch gesandt. Dann müssen wir das wohl zusammen durchstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12038] = { id = 12038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die angesengte Geißel", description = "Worauf wartet Ihr, {class}? Diese verseuschten Trolle bring'n sisch nisch selbst um!\n\nIhr wischt ja, worum's geht. Geht zur Feschde Drak'Tharon im Norden. Nehmt ein bisschen von dieschem Grog un' werft ihn nach ihnen aus sischerer Dischtanz…<hick>. Un' dann einfach surückleh'n und suguck'n, wie se in Flamm'n aufgeh'n.", sourceObjective = "Mack am Granitquell möchte, dass Ihr seinen Grog nehmt und 30 ausgemergelte Geißeltrolle in Flammen aufgehen lasst.", completion = "Gut gemacht!\n\n<Mack lacht einen Moment lang hysterisch.>\n\nOh, na kommt. Dasch hat Spaß gemacht…<hicks>.", sourceObjectiveStatus = "unverified-source-field" }
quests[12039] = { id = 12039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das schwarze Blut von Yogg-Saron", description = "Angrathar, die Pforte des Zorns... Ich sah, wie die Metallstreben des Tores pulsierten und zu schwingen begannen, als wären sie lebendig! In meinen 50 Jahren habe ich noch nie Metall \"atmen\" sehen.\n\nDie Einzigen, die etwas darüber wussten, waren die Tuskarr. Sie nannten es \"das schwarze Blut von Yogg-Saron\" und meinten, dass ich mich davon fernhalten solle.\n\nWestlich außerhalb von Eisnebel gibt es ein Schlundloch namens \"die Grube von Narjun\". Ich hörte, dass die Schlundlöcher reich an diesem seltsamen Erz seien. Könntet Ihr versuchen, mir ein paar Proben zu besorgen, falls Ihr in diese Richtung gehen solltet?", sourceObjective = "Borus Eisenbieger in Agmars Hammer in der Drachenöde möchte, dass Ihr ihm 10 Proben des schwarzen Blutes von Yogg-Saron beschafft.", progress = "Was wäre das Leben, wenn man kein Risiko einginge?", completion = "Es ist so leicht... als würde es nichts wiegen! Ich brauche etwas Zeit, um das Metall zu analysieren und um zu sehen, ob ich es irgendwie verwenden kann! Tests! Ich muss ein paar Tests machen!\n\nIch werde von mir hören lassen, {name}. Falls sich irgendwas ergeben sollte, dann werdet Ihr als Erster davon erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12040] = { id = 12040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arthas zum Feinde", description = "Wir befinden uns mitten im Bürgerkrieg. Im Herzen dieser Welt kämpfen meine letzten lebenden Artgenossen gegen die totale Vernichtung an. Der Lichkönig will das Königreich von Azjol-Nerub um jeden Preis in seine Gewalt bringen. Diejenigen, die dagegen sind, werden zu Feinden der Geißel erklärt und zum Tode verurteilt.\n\nArthas ist unser beider Feind...\n\nSchließt Euch uns an und befreit diesen Ort von den Anub'ar! Anub'arak selbst soll ihre quälenden Todesschreie hören!", sourceObjective = "Kilix der Entwirrer in der Grube von Narjun in der Drachenöde möchte, dass Ihr 6 Unterfürsten der Anub'ar tötet.", progress = "Das Reich Azjol wird wieder erblühen!", completion = "Es gibt noch Tausende ihrer Art und sie ergießen sich wie eine Flut aus jedem dunklen Spalt, den es in Nordend gibt. Ihr alleine habt keine Chance, doch zusammen... Zusammen vielleicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[12041] = { id = 12041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verlorene Reich", description = "Ihr habt gezeigt, dass Ihr bereit seid, dem Reich Azjol in Zeiten der Not beizustehen; aus diesem Grund wird das Reich Azjol der Horde seine Unterstützung zusichern.\n\nNehmt diese Schriftrolle hier und bringt sie zu Eurem Anführer. Darin beschrieben stehen die Stärken und Schwächen der Neruber, die für die Angriffe auf Eisnebel verantwortlich sind. Betrachtet es einfach als Zeichen unseres guten Willens - die Bereitschaft, Eurem Volke zur Hand zu gehen. Nutzt das Wissen auf diesen Seiten und vernichtet die Anub'ar. Tut dies und Ihr habt uns allen einen großen Dienst erwiesen.\n\nLebt wohl, {race}.", sourceObjective = "Liefert Kilixs Schlachtplan bei Oberanführer Agmar im östlichen Agmars Hammer ab.", progress = "Was habt Ihr da in Eurer Hand?", completion = "<Oberanführer Agmar überfliegt das Schreiben.>\n\nIst es das, von dem ich denke, dass es das ist? Mit dem Wissen, das darin geschrieben steht, werden wir den Ansturm der Anub'ar ZERSCHLAGEN!\n\nEs war eine gute Entscheidung, mir dieses Schreiben zu bringen, {name}. Womöglich wird es Euch gestattet sein, der letzten Schlacht bei Angrathar beizuwohnen oder sogar daran teilzunehmen! LOK'TAR!", sourceObjectiveStatus = "unverified-source-field" }
quests[12042] = { id = 12042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz der Uralten", description = "Geheimnisse der Zeitalter, offenbart euch mir jetzt!\n\n<Drakuru schaut durch das Auge der Propheten.>\n\nAah, glorreich is' meine Zukunft, {name}. Du hast Glück, mich zu kennen…\n\nDa! Ich seh's, Mann. Das Herz der Uralten. Das war zu einfach!\n\nDu findest das Herz in der Nähe von 'ner Goblinleiche östlich von hier. Sie is' oben in 'ner Kammer, in der Nähe eines Flusses aus zerbrochenen Bäumen.\n\nBeeil dich, Mann, bevor es jemand anderes findet!", sourceObjective = "Drakuru möchte, dass Ihr zur höchsten Kammer beim Holzfällerposten Blauhimmel geht und dort nach dem Herz der Uralten sucht.", completion = "Dieser unglückliche Goblin hat anscheinend das Herz während der Ausgrabungen in der Gegend aus der Erde geholt.\n\nEr hatte eindeutig keine Ahnung, was er dort gefunden hat.\n\nIhr kommt zu dem Schluss, dass es während des Chaos damals übersehen worden ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[12043] = { id = 12043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung von Düsenrost", description = "Ihr da, {class}! Diese Untoten südlich von uns belästigen ständig unsere Arbeit. Nun geht schon und räumt sie aus dem Weg.", sourceObjective = "Tötet 12 Buddler der Weiten und 1 Zuchtmeister der Weiten, die sich in den Ausgrabungsorten um Galakronds Ruhestätte herum befinden. Kehrt anschließend zu Narf im Düsenrostposten zurück, sobald die Aufgabe erledigt ist.", completion = "Oh! Ja, die Untoten. Hier ist Eure Bezahlung - nun trollt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12044] = { id = 12044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstockung", description = "Aber hallo! Die Diener der Geißel graben im Süden irgend so ein uraltes Drachending aus. Mir könnte es eigentlich völlig egal sein, aber die holen dabei auch Karrenladungen voll mit Kompositerz aus dem Boden.\n\nGeht und klaut mir ein wenig von dem Erz. Angesichts der vielen Waffen, die von der Horde hergestellt werden, sollte ordentlich was dabei rausspringen.", sourceObjective = "Geht zu den Ausgrabungsorten, die sich um Galakronds Ruhestätte herum befinden, sammelt 8 Ladungen Kompositerz und bringt sie anschließend zu Xink im Düsenrostposten.", progress = "Habt Ihr das Erz dabei? Mein Träger wird bald zurück sein - wir müssen diese Lieferung verschicken, solange der Kampf noch tobt!", completion = "Ha! Das ist ziemlich viel! Wie geht es Eurem Rücken?", sourceObjectiveStatus = "unverified-source-field" }
quests[12045] = { id = 12045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiskristalle", description = "Ich habe Euch noch nie zuvor gesehen... Seid Ihr neu in der Schlucht? Freut mich, Euch hier zu haben. Ein paar mehr helfende Hände kann ich immer gut gebrauchen.\n\nMachen wir's so: Ihr beschafft mir die Materialien, ich stelle meine Maschine fertig, dann verkaufen wir das Zeugs an diese Befehlshabertypen und alle gehen reich nach Hause.\n\nIch habe die meisten der Hauptkomponenten hier, also brauche ich nur noch ein paar der Materialien für die Waffe selbst. Narf hat gemeint, dass die gezackten Eissplitter dieser Elementare gen Norden die perfekten Schrapnelle für meine Bomben wären. Geht und holt mir ein paar, ok?", sourceObjective = "Sammelt 4 Eissplitterklumpen von den Eiselementaren gen Norden und bringt sie zu Zivlix im Düsenrostposten.", progress = "Habt Ihr die Splitter? Ich bin schon fast fertig mit der Hauptkühlungseinheit.", completion = "Ausgezeichnet! Sie sind sogar schärfer als erwartet. Ich werde sie erst einmal in den Schnee stecken und sie so lange dort lassen, bis die Bombe fertig ist.\n\nHmm, mal überlegen... Was kommt als Nächstes dran...", sourceObjectiveStatus = "unverified-source-field" }
quests[12046] = { id = 12046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiches Hüllenmaterial", description = "Meine Schrapnellbomben brauchen neues Hüllenmaterial. All das Zeug hier ist zu hart und die Schrapnelle werden bei der Explosion nicht richtig verstreut.\n\nWas wir brauchen ist richtig dünner Tierbalg. Die Jormungartunnelgräber im Westen würden womöglich geeignete Bälge hergeben... oder vielleicht auch die Kondore, die bei den Drachenknochen nach Essbarem suchen. Geht und bringt mir, was auch immer sich finden lässt.", sourceObjective = "Sammelt 12 dünne Tierbälge von den Jormungartunnelgräbern oder den Drachenknochenkondoren in der Nähe des Düsenrostpostens und bringt sie anschließend zu Zivlix.", progress = "Läuft die Jagd gut? Habt Ihr meine Bälge dabei?", completion = "Gut... gut... die hier sollten genügen. Die Schrapnellbomben sind fast fertig.\n\nHalt... was ist mit meinen Eissplittern passiert? Narf hat mir gesagt, dass die Splitter von diesen Elementaren verzaubert sein sollen, doch sie schmelzen genauso wie die Dinger, die von Narfs grimmiger Visage hängen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12047] = { id = 12047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas, das nicht schmilzt", description = "Nein, nein, nein! Diese Eissplitter funktionieren überhaupt nicht! Sie schmelzen, bevor sie überhaupt irgendwelchen Schaden anrichten. Das war das letzte Mal, dass ich auf Narfs Meinung in Sachen Materialien vertraut habe. Das bedeutet, dass wir irgendwas ganz anderes zur Herstellung des Schrapnells benötigen.\n\nIch hab's! Ich bin genial - Knochensplitter.\n\nHier liegen überall Knochen herum, an denen die Jormungar ziemlich gründlich herumgenagt haben. Seht einmal nach, ob Ihr mir nicht einen zersplitterten Knochen finden könnt, den ich gebrauchen kann.", sourceObjective = "Sucht inmitten der Drachenknochen östlich des Düsenrostpostens nach 12 zersplitterten Knochenstücken.", progress = "Konntet Ihr irgendwelche Splitter finden?", completion = "Ausgezeichnet! Mehr brauche ich nicht, um die neuen Bomben austesten zu können. Einen Moment, ich werde das hier mal austesten!", sourceObjectiveStatus = "unverified-source-field" }
quests[12048] = { id = 12048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen der Geißel", description = "Aus diesem verdammten Erz lässt sich nichts gewinnen. Es will einfach nicht zusammenhalten! Ich habe alles versucht, doch das Metall der Geißel lässt sich nicht verbiegen!\n\nWenn ich vielleicht ein paar Proben von den Waffen der Geißel hätte, wäre ich vielleicht dazu in der Lage, den Schmiedeprozess zurückzuverfolgen und sie gleichzeitig auseinanderzunehmen.\n\nEisnebel wimmelt nur so von gepanzerten Nerubern der Geißel. Geht dorthin und beschafft mir ein paar ihrer Waffen! Mit Eurer Hilfe könnte ich vielleicht sogar etwas aus diesem Erz machen.\n\nEisnebel liegt im Westen.", sourceObjective = "Borus Eisenbieger in Agmars Hammer in der Drachenöde möchte, dass Ihr ihm 8 Waffen der Geißel bringt.", progress = "<Borus pfeffert seine Werkzeuge auf den Boden.>\n\nDie sind nutzlos!", completion = "Diese hier befinden sich in einem ausgezeichneten Zustand, {name}. Ich werde mich sofort an die Arbeit machen. Wenn daraus irgendwas werden soll, dann werdet Ihr es als Erster erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[12049] = { id = 12049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwer zu schlucken", description = "Die Truppen werden sich sicherlich die Bäuche vollstopfen wollen.\n\nIch werde Euch in ein kleines Geheimnis einweihen, das <ein zart Besaiteter/eine zart Besaitete:r> {race} wie Ihr niemals wissen könnte... diese Jormungarwürmer schmecken nämlich wie Hühnchen.\n\nGeht nach Osten und fordert einen dieser riesigen, bulligen Jormungar heraus. Es ist eher unwahrscheinlich, dass Ihr dazu in der Lage sein werdet, einen von ihnen so mir nichts, dir nichts zu töten - wartet also, bis er sein Maul weit aufsperrt und werft das hier seinen Rachen hinunter. Bringt mir so viele Fleischstücke, wie Ihr nur schleppen könnt.", sourceObjective = "Kämpft so lange gegen einen bulligen Jormungar östlich des Düsenrostpostens, bis er sein Maul öffnet, um dann eine potente Sprengladung hineinzuwerfen. Sammelt, nachdem er explodiert ist, 6 Stücke verbranntes Jormungarfleisch vom Boden auf und bringt sie zu Xink.", progress = "Habt Ihr alles bekommen? Ihr stinkt zweifellos danach.", completion = "Ha, ha! Eins der Fleischstücke ist genau hier drüben gelandet! Saubere Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[12050] = { id = 12050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holz hacken", description = "Als Nächstes müssen wir etwas Holz für all die im Bau befindlichen Türme der Allianz beschaffen. Im Süden gibt es einige dünne Bäume, doch die Bäume im Norden, auf denen die Harpyien nisten, sehen so aus, als wären sie ein viel besseres Baumaterial für Gebäude.\n\nNehmt die Steuerung hier. Benutzt sie, wenn Ihr im Nistgebiet der Harpyien seid, und einer meiner Schredder wird zu Euch kommen. Sammelt so viel Holz, wie er nur tragen kann. Die Harpyien werden sicherlich damit nicht einverstanden sein, dass Ihr deren Zuhause fällt - kümmert Euch also um sie, falls nötig.\n\nLos, ran ans Holz!", sourceObjective = "Ruft mithilfe von Xinks Schreddersteuerung einen Schredder, sobald Ihr das Nistgebiet der Harpyien im Norden erreicht habt. Sammelt 50 Bündel Nutzholz von den Bäumen in der Gegend und kehrt anschließend zu Xink im Düsenrostposten zurück.\n\nWendet Euch an Xink im Düsenrostposten, falls Ihr Xinks Schreddersteuerung verlieren solltet, um eine neue zu erhalten.", progress = "Wo ist die Lastenmaschine? Hoffe, die Jormungar haben sie nicht erwischt. Sie hatte diesmal eine ziemlich große Ladung dabei.", completion = "Wenn ein Baum im Wald umfällt und Ihr wegen der Sägerei nichts hören könnt, macht er dann ein Geräusch?", sourceObjectiveStatus = "unverified-source-field" }
quests[12051] = { id = 12051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Federn rascheln lassen", description = "Diese Harpyien haben unsere Profite schon lange genug beeinträchtigt! Tötet sie alle.", sourceObjective = "Narf im Düsenrostposten möchte, dass Ihr 20 Harpyien nordwestlich des Düsenrostpostens tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12052] = { id = 12052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nimm das, Harpyie!", description = "{class}, habt Ihr das gesehen? Das ist die Harpyie, die den Überfall auf unsere Lieferungen zur Pforte angeführt hat! Ich hab' sie schon einmal gesehen: im hinteren Teil der Kaltwindanhöhen.\n\nDiese Harpyien haben unsere Profite schon lange genug beeinträchtigt! Tötet sie alle.", sourceObjective = "Tötet die Meisterin des Kaltwinds und 15 Kaltwindharpyien in den Bergen nordwestlich des Düsenrostpostens. Kehrt zu Narf zurück, sobald die Aufgabe erledigt ist.\n\nSprecht mit Xink im Düsenrostposten, falls Ihr seine Schreddersteuerung benötigen solltet.", completion = "Das sollte diese Scheusale eines Besseren belehren. Hier... nehmt Eure Belohnung und macht, dass Ihr davonkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12053] = { id = 12053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Horde", description = "Die Taunka sind zu unseren Waffenbrüdern geworden - wir müssen ein Zeichen der Solidarität setzen und Eisnebel zurückerobern.\n\nDas Dorf befindet sich am Fuß der Berge westlich von Agmars Hammer. Macht Euch auf den Weg dorthin und fordert die Neruber der Anub'ar zum Kampf heraus! Rammt unser geliebtes Banner der Horde in den Boden, sobald Ihr dort angelangt seid, und vernichtet all diejenigen, die es wieder niederreißen möchten!\n\nDie Anub'ar sollen die wahre Macht der Horde spüren! Möge unsere Schlachtstandarte das Letzte sein, das sie vor dem Tode sehen werden!", sourceObjective = "Schlachtrufer Juktok in Agmars Hammer in der Drachenöde möchte, dass Ihr die Schlachtstandarte des Kriegshymnenklans in Eisnebel aufstellt und sie gegen alle Angreifer verteidigt.\n\nBringt die Schlachtstandarte des Kriegshymnenklans wieder zurück, wenn Ihr die Aufgabe abgeschlossen habt.", progress = "Es ist nicht einfach, {name}!", completion = "Wir haben den Sieg zu Land errungen! Und bald werden wir ihn auch in der Luft erringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12054] = { id = 12054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tagebuch entschlüsseln", description = "Vor'takh hat Recht... Wir können uns diese Gelegenheit nicht durch die Lappen gehen lassen.\n\nZum Glück weiß ich, wie wir das Tagebuch dieses Branns übersetzen könnten.\n\nDie Schamanen der Rotfangfurbolgs, die sich am Schrein des Herzensblutes südlich des Lagers versammeln, pflanzen ein Kraut mit Namen 'Geisteratem' an. Ein erfahrener Mystiker kann daraus einen Weihrauch herstellen, mit dessen Hilfe er sich die Weisheit der Geister der Vorfahren zu Nutze machen kann.\n\nDie Gärten der Schamanen sind ein wohl gehütetes Geheimnis; doch sucht den Schamanen namens Grumbald Einauge auf - er sollte das Kraut bei sich tragen, da er es für seine Opfergaben an Ursoc benötigt.", sourceObjective = "Bringt der Weisen Paluna in Camp Oneqwah einen Geisteratemzweig.", progress = "Habt Ihr genug von dem Kraut mitgebracht?", completion = "Gut gemacht, {name}. Ich werde das Rauchwerk vorbereiten und dann werden wir sehen, was genau dieser königliche Zwerg so weit von zu Hause gemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12055] = { id = 12055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltsames Gerät", description = "Ihr seid Euch sicher, als Ihr das seltsame Gerät aufhebt, dass es von magischer Natur ist. Leider scheint es keinen erkennbaren Nutzen aufzuweisen.\n\nWomöglich weiß die Erzmagierin in Sternenruh östlich der Mondruhgärten mehr darüber.", sourceObjective = "Bringt Goramoshs seltsames Gerät zum Abbild der Erzmagierin Modera in Sternenruh.", progress = "Was habt Ihr denn da?", completion = "{name}, wenn ich mich nicht täusche, habt Ihr den Schlüssel entdeckt, mit dessen Hilfe wir die Absichten der Magierjäger genau erkennen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[12056] = { id = 12056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Tode verurteilt: Hochkultist Zangus", description = "Ich habe mit eigenen Augen beobachten können, wie er uns verriet! Der Verräter hat einen Angriff der Anub'ar auf diese Festung geleitet, bei dem einige meiner besten Soldaten ums Leben kamen.\n\n<Gort schüttelt den Kopf.>\n\nEr hat die ganze Zeit über gemeinsame Sache mit der Geißel gemacht und wir haben davon nichts gewusst! Wie viele Verräter wie Zangus gibt es denn? Wir werden sie alle finden und wenn wir sie haben...\n\n<Gort macht mit seinem Finger eine Bewegung, als durchschneide er seine Kehle.>\n\nErster auf der Liste ist Zangus. Unsere Späher berichten mir, dass er sich in der Grube von Narjun gen Westen verstecken soll. Findet ihn, tötet ihn und bringt mir seinen Kopf.", sourceObjective = "Tötet Hochkultist Zangus und bringt den Kopf des Hochkultisten Zangus zu Hauptmann Gort in Agmars Hammer in der Drachenöde.", progress = "Ist da der abgetrennte Kopf eines Orcs in Eurem Rucksack oder seid Ihr bloß froh, mich zu sehen?", completion = "<Gort hält den Kopf hoch und starrt in seine toten Augen.>\n\nIch hab' dir gesagt, dass wir dich erwischen würden...\n\nHier ist Eure Belohnung, {class}. Damit hätten wir eine Sorge weniger, die uns Kopfschmerzen bereitet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12057] = { id = 12057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der fleischgebundene Foliant", description = "Der Foliant ist in Fleisch eingebunden und es scheint, als würde er bluten. Nach näherer Betrachtung entdeckt Ihr unzählige Seiten, die über und über mit seltsamen blutigen Symbolen beschriftet sind.\n\nWelches Wissen auch immer in diesem Folianten enthalten sein mag, es könnte von Bedeutung sein. Bringt ihn zurück zu Hauptmann Gort in Agmars Hammer östlich von Eisnebel.", sourceObjective = "Bringt Hauptmann Gort in Agmars Hammer den fleischgebundenen Folianten.", progress = "<Gort hebt eine Braue.>", completion = "<Gort nimmt den Folianten an sich.>\n\nBarbaren... In Orcfleisch eingebunden... Diese Sprache... Dass sie wirklich existiert, wurde jedoch niemals bestätigt. Es ist die Sprache des Todes... die Zunge der Geißel.", sourceObjectiveStatus = "unverified-source-field" }
quests[12058] = { id = 12058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Runenprophezeiungen", description = "Branns Tagebuch enthält auch eine Legende für die Symbole der Eisenzwerge. Ich habe sie auf einen Schlüsselstein übertragen, der Euch beim Verstehen der Inschrift auf den Runenplatten helfen wird.\n\nLaut seinen Tagebucheinträgen scheint es, als suche Brann Hinweise auf die Herkunft seines Volks. Haltet Eure Augen nach jedem Hinweis auf seinen Aufenthaltsort offen.\n\nKehrt nach Thor Modan zurück, nordöstlich von hier, stellt Euch vor jede der Platten und verwendet den Stein, um ihren Inhalt zu bestimmen. Die Allianz darf ihn nicht vor uns finden.", sourceObjective = "Die Weise Paluna im Camp Oneqwah möchte, dass Ihr die drei Runenplatten entziffert.", completion = "<Die Weise Paluna hört Euch zu, als Ihr die Übersetzung der Platten wiederholt.>\n\nAlso glaubt Brann, eine neue Titanenstadt entdeckt zu haben?\n\n\"Die Wiege von Stein und Eisen.\"\n\n\"Ulduar schmiegt sich in den Sturm.\"\n\nIch werde den Häuptling bitten, Fernläufer zu den Sturmgipfeln zu entsenden. Mein Volk kennt diese Lande gut und sollte in der Lage sein, diesen eigensinnigen Zwerg aufzuspüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12059] = { id = 12059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltsames Gerät", description = "Ihr seid Euch sicher, als Ihr das seltsame Gerät aufhebt, dass es von magischer Natur ist. Leider scheint es keinen erkennbaren Nutzen aufzuweisen.\n\nWomöglich weiß der Erzmagier in Agmars Hammer nordöstlich der Mondruhgärten mehr darüber.", sourceObjective = "Bringt Goramoshs seltsames Gerät zum Abbild des Erzmagiers Aethas Sonnenhäscher.", progress = "Was habt Ihr denn da?", completion = "{name}, wenn ich mich nicht täusche, habt Ihr den Schlüssel entdeckt, mit dessen Hilfe wir die Absichten der Magierjäger genau erkennen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[12060] = { id = 12060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Projektionen und Pläne", description = "Das hier ist ein Teleportationsgerät. Müsste ich raten, würde ich meinen, dass es einen zur Sognadelplattform über den Mondruhgärten gen Westen teleportiert.\n\nIch möchte, dass Ihr es benutzt, um herauszufinden, was sich dort oben befindet. Es scheint, als könne man sich mit dem Gerät auch wieder zurückbefördern, also müsstet Ihr nicht herunterspringen.\n\nMeinen Erwartungen nach wird sich ganz oben auf der Sognadel eine Art Apparat befinden, den es zu untersuchen gilt.\n\nIhr solltet den Teleporter benutzen können, solange Ihr Euch in den Gärten aufhaltet.", sourceObjective = "Geht zur Projektion auf der Sognadel über den Mondruhgärten, um sie zu untersuchen.\n\nKehrt anschließend mit den Informationen zum Abbild der Erzmagierin Modera in Sternenruh zurück.", completion = "Was Ihr beschreibt... hört sich wie eine Projektion des Arkanomikons an!\n\n<Kurz kommt die Sorge der Erzmagierin zum Vorschein, doch dann gewinnt ihre unerschütterliche Fassung wieder die Oberhand.>\n\nDas Arkanomikon ist eine Karte all der Stellen auf der Welt, an denen sich die magischen Leylinien überkreuzen. Mit seiner Hilfe hat der blaue Drachenschwarm die 'Anker' der Leylinien entdeckt und zerstört, um die magische Energie wieder zurück zum Nexus zu leiten.\n\nNun stellt sich die Frage, weshalb sich der Zerstörungspfad nach Osten zieht, wenn er sich doch nach Westen ziehen sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12061] = { id = 12061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Projektionen und Pläne", description = "Das hier ist ein Teleportationsgerät. Müsste ich raten, würde ich meinen, dass es einen zur Sognadelplattform über den Mondruhgärten gen Südwesten teleportiert.\n\n{name}, ich möchte, dass Ihr mit seiner Hilfe herausfindet, was sich dort oben befindet. Es scheint, als könne man sich mit dem Gerät auch wieder zurückbefördern, also müsstet Ihr nicht herunterspringen.\n\nMeinen Erwartungen nach wird sich ganz oben auf der Sognadel eine Art Apparat befinden, den es zu untersuchen gilt.\n\nIhr solltet den Teleporter benutzen können, solange Ihr Euch in den Gärten aufhaltet.", sourceObjective = "Geht zur Projektion auf der Sognadel über den Mondruhgärten, um sie zu untersuchen.\n\nKehrt anschließend mit den Informationen zum Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer zurück.", completion = "Was Ihr beschreibt... hört sich wie eine Projektion des Arkanomikons an!\n\n<Nur kurz kommt die Sorge des Erzmagiers zum Vorschein, bis seine unerschütterliche Fassung wieder die Oberhand gewinnt.>\n\nDas Arkanomikon ist eine Karte all der Stellen auf der Welt, an denen sich die magischen Leylinien überkreuzen. Mit seiner Hilfe hat der blaue Drachenschwarm die 'Anker' der Leylinien entdeckt und zerstört, um die magische Energie wieder zurück zum Nexus zu leiten.\n\nNun stellt sich die Frage, weshalb sich der Zerstörungspfad nach Osten zieht, wenn er sich doch nach Westen ziehen sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12062] = { id = 12062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beleidigt Coren Düsterbräu", description = "Coren Düsterbräu ist im nächsten Raum und gerade dabei, Dunkeleisenzwerge zu einem weiteren Angriff auf das Braufest aufzustacheln. Macht ihn nieder!\n\nGeht zu ihm hin und provoziert einen Streit. Sagt ihm, dass nicht einmal Säue sein Bier saufen würden.\n\nMacht Euch auf einen Kampf gefasst, wenn Ihr das sagt - das letzte Mal, als jemand über sein Gebräu herzog... warf man ihn Schreckensebern zum Fraß vor.", sourceObjective = "Geht und fangt Streit mit Coren an.", sourceObjectiveStatus = "unverified-source-field" }
quests[12063] = { id = 12063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisnebels Stärke", description = "<Großmutter Eisnebel verbeugt sich.>\n\nEs ist mir eine Ehre, Euch kennenzulernen, <mein Held/meine Heldin>. Es ist Euch zu verdanken, dass viele von uns heute hier versammelt und am Leben sind, bereit, gegen die Geißel in die Schlacht zu ziehen.\n\nIhr habt so viel für uns getan, dass es mich in Verlegenheit bringt, Euch ein weiteres Mal um Unterstützung zu bitten. Es geht um meinen einzigen Sohn Banthok. Ich sprach mich zwar des Öfteren dagegen aus, doch er verließ diesen Ort, um sich auf die Suche nach seinem Vater, Oberhäuptling Eisnebel, zu begeben. Als er das letzte Mal gesehen wurde, zog er in Richtung Westen nach Eisnebel. Ich bitte Euch: Findet Banthok. Ich wüsste weder ein noch aus, würde ich meinen Sohn verlieren.", sourceObjective = "Sucht in Eisnebel nach Banthok Eisnebel.", completion = "Mein Vater ist noch immer am Leben! Wir müssen ihn retten! Ich schaffe es nicht alleine, {race}. Ihr müsst mir helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12064] = { id = 12064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ketten der Anub'ar", description = "Sie haben meinen Vater mit magischen Ketten gefesselt und halten ihn in der Mitte von Eisnebel fest. Alles, was ich in Erfahrung bringen konnte, ist, dass drei mächtige Magier der Anub'ar dafür sorgen, dass er gefangen gehalten wird, und dass ein jeder einen Teil des Schlüssels in Händen hält.\n\nDurchsucht Eisnebel nach diesen Magiern, tötet sie und nehmt ihnen die Schlüsselfragmente ab. Sobald wir erst einmal alle drei Teile haben, werden wir meinen Vater befreien können. Und sobald er frei ist...\n\nVergeltung wird sie ereilen, ehe sie sich versehen.", sourceObjective = "Banthok Eisnebel in Eisnebel in der Drachenöde möchte, dass Ihr ihm Anok'ras Schlüsselfragment, Tivax' Schlüsselfragment und Sinoks Schlüsselfragment beschafft.", progress = "Bringt mir diese Schlüsselfragmente!", completion = "Ja, das wird funktionieren.\n\n<Banthok fügt die Schlüsselfragmente mit äußerster Geschicklichkeit zusammen.>\n\nSo, fertig. Mit diesem Schlüssel werden wir meinen Vater aus den Klauen der Anub'ar befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[12065] = { id = 12065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fokus am Strand", description = "Die Streitkräfte der Magierjäger operieren am Glimmerstrand südlich der Mondruhgärten. Ich vermute, Ihr werdet dort einen schwer bewachten Fokus samt zuständigem Hauptmann vorfinden.\n\nEs besteht kein Zweifel, dass der Hauptmann der Truppe so etwas wie eine Steuerung für das Gerät bei sich trägt. Beschafft Euch diese Steuerung und wendet sie auf den Fokus an.\n\nMit etwas Glück, können wir ein wenig mehr darüber erfahren, was sie dort draußen wirklich vorhaben.", sourceObjective = "Beschafft Euch den Steuerungsring des Leylinienfokus und verwendet ihn, um Informationen vom Leylinienfokus am Glimmerstrand zu erhalten.\n\nKehrt anschließend zum Abbild der Erzmagierin Modera in Sternenruh zurück.", completion = "Wie merkwürdig, dass Euch diese Informationen auf magische Art und Weise übertragen wurden.\n\nWir wissen jetzt nicht nur, dass sie den Energiefluss des Mondruhgartens umgeleitet haben, sondern auch, dass sie diese Energie absichtlich irgendwie manipulieren. Was haben sie bloß mit all dieser Magie vor?\n\nMir gefällt das alles nicht, {name}, ganz und gar nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[12066] = { id = 12066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fokus am Strand", description = "Die Streitkräfte der Magierjäger operieren am Glimmerstrand südlich der Mondruhgärten. Ich vermute, Ihr werdet dort einen schwer bewachten Fokus samt zuständigem Kapitän vorfinden.\n\nEs besteht kein Zweifel, dass der Hauptmann der Truppe so etwas wie eine Steuerung für das Gerät bei sich trägt. Beschafft Euch diese Steuerung und wendet sie auf den Fokus an.\n\nWenn Ihr es geschickt anstellt, können wir etwas mehr darüber erfahren, was sie dort draußen wirklich vorhaben.", sourceObjective = "Beschafft Euch den Steuerungsring des Leylinienfokus und verwendet ihn, um Informationen vom Leylinienfokus am Glimmerstrand zu erhalten.\n\nKehrt anschließend zum Abbild des Erzmagiers Aethas Sonnenhäscher bei Agmars Hammer zurück.", completion = "Wie merkwürdig, dass Euch diese Informationen auf magische Art und Weise übertragen wurden.\n\nWir wissen jetzt nicht nur, dass sie den Energiefluss des Mondruhgartens umgeleitet haben, sondern auch, dass sie diese Energie absichtlich irgendwie manipulieren. Was haben sie bloß mit all dieser Magie vor?\n\nMir gefällt das alles überhaupt nicht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12067] = { id = 12067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Brief an Zuhause", description = "Im Innenfutter ihrer Robe findet Ihr einen Brief, in dem Folgendes geschrieben steht:\n\n\"Vater,\n\nes tut mir leid, dass ich mich nicht gemeldet habe und du nicht wusstest, wo ich bin. Wenn du diesen Brief liest, dann bin ich schon tot.\n\nIch wurde dazu gezwungen, für Malygos' Armeen zu arbeiten, da sie mir gedroht haben, unsere Familie umzubringen, wenn ich mich weigerte. Ich schäme mich so sehr dafür.\n\nIch bitte dich alles zu tun, was in deiner Macht steht, um sie zu bekämpfen. Und mach dir keine Sorgen um mich. Ich halte sie zum Narren und sabotiere sie nun von innen.\n\nIch liebe dich, Papa!\n\nEm\"\n\nKommandantin Saia Azurstahl wird das hier sicherlich sehen wollen!", sourceObjective = "Liefert Hauptmann Malins Brief bei Kommandantin Saia Azurstahl in Sternenruh ab.", progress = "Ein Brief für mich?\n\n<Die Kommandantin liest einen Moment lang in Eurem Gesicht.>\n\nIch denke nicht... - müssen schlechte Nachrichten sein.", completion = "Oh nein... und wir haben Euch dorthin geschickt, um sie zu töten, stimmt's?\n\n<Die Kommandantin schüttelt den Kopf und seufzt.>\n\nEs tut mir leid. Ich werde mich darum kümmern, dass der Brief umgehend an ihren Vater Erzmagier Malin in Sturmwind geschickt wird. Macht Euch keine Sorgen; man wird Euch mit der Sache nicht in Verbindung bringen... Es war nicht Eure Schuld.\n\nVersucht es zu vergessen. Ihr hättet es auf keinen Fall wissen können, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12068] = { id = 12068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmen aus dem Staub", description = "<Drakuru platziert das Auge des Propheten über seiner Augenbraue und das Herz der Uralten auf seine Brust.>\n\nWir sind nah' dran, Mann, sehr nahe!\n\nWir müssen nur noch die Tafeln der Drakkari finden. Niemand weiß, wie alt sie sind oder was auf ihnen geschrieben steht, doch mithilfe des Auges und des Herzens kann Drakuru sie lesen. Sie befinden sich tief in der Krypta in Drakil'jin, östlich von hier.\n\nBesorg' dir heiliges Mojo von den Orakeln und Beschützern, nachdem du die Tafeln gefunden hast, und beschwör' mich. Sie sollten stolz sein, dafür sterben zu dürfen.", sourceObjective = "Drakuru möchte, dass Ihr in die Ruinen von Drakil'jin geht, dort die Tafeln der Drakkari sammelt und 5 Einheiten heiliges Mojo von den Orakeln und Beschützern der Drakkari sammelt. Geht danach zu Drakurus Kohlenbecken in den Ruinen, benutzt Drakurus Elixier und ruft sein Abbild herbei.", progress = "Gut, dich zu sehen, {name}.\n\nHaste die Tafeln gefunden?", completion = "Wir haben es vollbracht, {name}!\n\nWir haben alle Komponenten, die wir brauchen, um das Läuterungsritual durchzuführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12069] = { id = 12069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Oberhäuptlings", description = "<Banthok überreicht Euch den Gefängnisschlüssel.>\n\nIhr müsst Euch beeilen, {name}. Nehmt den Schlüssel und befreit meinen Vater aus dem Gefängnis der Anub'ar. Helft ihm anschließend dabei, ihren Anführer Unterkönig Anub'et'kan zu töten. Reißt dann ein Stück seines Chitinpanzers heraus und präsentiert es der Horde in Agmars Hammer als Trophäe. Agmar soll die Macht des Oberhäuptlings mit eigenen Augen sehen!", sourceObjective = "Befreit Oberanführer Eisnebel mit dem Gefängnisschlüssel von Anub'ar und helft ihm dabei, Unterkönig Anub'et'kan zu besiegen.\n\nNehmt Euch ein Bruchstück aus Anub'et'kans Panzer und bringt es zurück zu Oberanführer Agmar in Agmars Hammer in der Drachenöde.", progress = "Worum geht's, {name}? Ich bin äußerst beschäftigt.", completion = "Ihr seid ein mutiger {class}, {name}. Ihr habt den Oberanführer befreit und der Horde damit einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12070] = { id = 12070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Kraft für die Truppen", description = "Die Söhne des Eisens haben ihre Runen benutzt, um viele meiner Brüder zu fesseln und benutzen sie dazu, die Belagerung von Thor Modan zu beenden. Ich wünschte, wir müssten sie nicht bekämpfen, aber wir haben keine andere Wahl.\n\nMeine Riesen werden ihnen nicht lange standhalten können.\n\nIch habe diesen irdenen Splitter mit einem Segen versehen, der unseren Verbündeten helfen wird. Nehmt ihn mit Euch in die Schlacht in den Felshügeln im Norden und benutzt ihn, um meinen Brüdern Vertrauen und Stärke einzuflößen. \n\nTötet alle Eisenzwerge, die sich Euch in den Weg stellen.", sourceObjective = "Benutzt den Splitter der Erde, um den Grizzlyhügelriesen, die in den Felshügeln kämpfen, neue Kraft einzuflößen. Tötet alle Eisenzwerge, die sich Euch widersetzen, und erstattet dann Kurun auf dem Hügel, der Thor Modan überblickt, Bericht.", progress = "Habt Ihr meinen Segen den Riesen meinen Segen übermittelt?", completion = "Ihr habt unseren Verbündeten die Kraft gegeben, weiterzukämpfen, und dafür danke ich Euch. Trotzdem müssen wir einen Weg finden, diese Schlacht zu beenden, bevor wir überrannt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12071] = { id = 12071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff aus der Luft!", description = "Sie haben gesehen, über welche Macht die Horde auf Land verfügt, nun müssen sie unsere Kraft aus der Luft zu spüren bekommen! Ich möchte, dass Ihr Euch umgehend bei Valnok Windzürner meldet! Er befindet sich hier, in Agmars Hammer.\n\nValnok wurde schon über die Einzelheiten Eurer Mission unterrichtet und erwartet Euch.", sourceObjective = "Sprecht mit Valnok Windzürner in Agmars Hammer.", completion = "<Valnok salutiert.>\n\nIhr seid also das Ass, oder was?", sourceObjectiveStatus = "unverified-source-field" }
quests[12072] = { id = 12072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammt sollen die Seuchenbestien sein!", description = "Ihr habt zweifellos die Armee der Seuchenbestien der Anub'ar gesehen, die in Eisnebel erschaffen wird. Die Anub'ar wollen diese Monster auf unsere Soldaten an der Pforte des Zorns hetzen - doch das darf nicht passieren!\n\nNehmt diese Leuchtpistole, geht nach Eisnebel im Westen und feuert sie ab, um einen meiner Kriegsreiter zu rufen. Sitzt auf und vernichtet mit seiner Hilfe die Seuchenbestien, die man vom Boden aus nicht erreichen kann!\n\nKehrt zu mir zurück, sobald Ihr ihre Luftstreitkräfte dezimiert habt, und holt Eure Belohnung ab!", sourceObjective = "Geht nach Eisnebel, benutzt Valnoks Leuchtpistole, um einen Kriegsreiter der Kor'kron zu rufen, setzt auf und tötet mit seiner Hilfe 25 Seuchenbestien der Anub'ar!\n\nKehrt anschließend wieder zu Valnok Windzürner in Agmars Hammer zurück, sobald Ihr diese Mission erfüllt habt.", completion = "<Valnuk salutiert.>\n\nUnd aus der Luft kam ihre Vernichtung! Vielleicht werdet Ihr schon bald nach Angrathar beordert, Held!", sourceObjectiveStatus = "unverified-source-field" }
quests[12073] = { id = 12073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Eisen bearbeiten", description = "Die Allianz ist nicht die einzige Macht, die sich uns in den Grizzlyhügeln entgegenstellt. Die Eisenzwerge halten die Ostküste unter ihrer Kontrolle, obwohl Thor Modan im Nordosten von Steinriesen belagert wird.\n\nEin fähiger Krieger nutzt die Schwäche seiner Gegner aus, und wir wären töricht, wenn wir die Verwundbarkeit der Eisenzwerge in Thor Modan ignorieren würden. Zeigt ihnen keine Gnade. Erschlagt alle und jeden, der sich Euch in den Weg stellt.\n\nDie 'Söhne des Eisens' werden die Horde schon fürchten lernen.", sourceObjective = "Tötet 10 beliebige Eisenzwerge in Thor Modan und kehrt dann zu Späher Vor'takh im Camp Oneqwah zurück.", completion = "<Späher Vor'takh lächelt.>\n\nThor Modan steht also kurz vor dem Fall?\n\nSehr gut. Dann können wir bald unsere Aufmerksamkeit auf Dun Argol richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12074] = { id = 12074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein nützlicher Verbündeter", description = "Die alte Zwergenhauptstadt Thor Modan, weit im Nordosten, wird von einer mysteriösen Truppe, bestehend aus Steinriesen und Irdenen, belagert.\n\nWarum die Schöpfungen der Titanen gegeneinander Krieg führen, geht über meinen Horizont und liegt außerhalb des Interessengebietes der Horde. Jedoch haben wir hier eine Gelegenheit, einen gemeinsamen Feind zu schwächen.\n\nReist nach Thor Modan und sucht diesen 'Kurun', der die Riesen und die Irdenen befehligt. Macht mit ihm gemeinsame Sache und benutzt seine Streitkräfte, um die Eisenzwerge zu zermalmen.", sourceObjective = "Sprecht mit Kurun auf dem Hügel, der Thor Modan überblickt.", completion = "<Ihr stellt Euch Kurun vor.>\n\nSo sind die Söhne des Eisens also auch Eure Feinde?\n\nMeine Streitkräfte haben die Eisenzwerge in ihrer Stadt eingeschlossen, aber wir könnten Hilfe bei der Erstürmung gebrauchen. Werdet Ihr uns unterstützen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12075] = { id = 12075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mageres Angebot", description = "Kalt hier draußen, findet Ihr nicht, {race}?\n\nKo'char hat sich geweigert, mich zu treffen. Es scheint, als hätte er dringlichere Dinge auf dem Herzen - nämlich Angriffe der Jormungar, die in der Höhle dort unten hausen. Vielleicht könntet Ihr mir dabei helfen, Ko'char davon zu überzeugen, dass ich einer der Guten bin.\n\nIch sah, wie einige der Würmer am Höhleneingang im Norden an einem der Riesen herumnagten... Mir ist es noch immer schleierhaft, weshalb die Würmer sie so leicht töten können. Bringt mir eine Probe seiner Wunden.", sourceObjective = "Beschafft eine Steinfleischprobe von der Eisriesenleiche am Höhleneingang nördlich von Zort in der Kristallschlucht und kehrt wieder zu ihm zurück, sobald die Aufgabe abgeschlossen ist. Er befindet sich in der Nähe des Zentrums der Schlucht.", progress = "Seid Ihr nun mit meiner Probe zurückgekehrt? Ich bin froh, dass Euch die Kälte nicht erwischt hat.", completion = "Das ist perfekt. Danke Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12076] = { id = 12076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreckige Angelegenheit", description = "Sogar beim ersten Anblick lässt sich ganz deutlich erkennen, dass die von Euch gebrachte Probe Zeichen einer ätzenden Spucke aufweist. Logischerweise ist anzunehmen, dass die Würmer dieselbe Substanz, mit der sie sich durch die Erde graben, auch als wirksame Waffe gegen die Eisriesen einsetzen.\n\nNehmt diesen Schaber und fordert ein paar dieser Würmer zum Kampf heraus. Entfernt mit dem Schaber ihre Spucke, wenn Ihr davon getroffen wurdet, und bringt sie hierher.\n\nBeschafft mir eine ordentliche Menge - ich werde das Zeug als Basis für ein Elixier verwenden müssen.", sourceObjective = "Füllt 2 Phiolen mit ätzendem Speichel, indem Ihr den Schaber auf Euch anwendet. Bringt die Phiolen wieder zu Zort in der Kristallschlucht, wenn Eure Aufgabe abgeschlossen ist.", progress = "Da, auf Eurer Schulter scheint noch immer etwas Spucke zu kleben, {race}. Passt auf oder es wird sich glatt durch Eure Rüstung brennen.", completion = "Noch immer frisch. Einen Moment, ich werde das hier mit dem Rest des Elixiers vermischen, das ich vorbereitet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[12077] = { id = 12077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Mal am Tag anwenden", description = "Dieses Elixier sollte Schutz vor ihrer Spucke bieten. Würdet Ihr es Ko'char anbieten? Sagt ihm auch, dass es noch viel mehr davon gibt und er es haben kann, wenn er sich erkenntlich zeigen wird.", sourceObjective = "Bietet das von Zort zubereitete Elixier Ko'char dem Unbezwingbaren an.", progress = "Der Wicht möchte, dass wir für ihn kämpfen, nicht wahr? Wie bin ich überrascht.", completion = "Um ehrlich zu sein, mein Kleiner, traue ich dieser Mixtur nicht und werde sie auch nicht probieren. Behalte sie... Du hast vielleicht mehr Vertrauen in diesen naiven Wicht als ich und kannst sie besser gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12078] = { id = 12078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wurmcowboy", description = "So soll es sein. Vielleicht können wir diese Würmer zu irgendwas gebrauchen, wenn die Riesen uns schon nicht helfen wollen. Die Brutmutter in der Höhle dort oben hat sicherlich ihren Nachwuchs in der Nähe. Nehmt diesen Kasten, fangt mir 3 Exemplare ihres Nachwuchses und bringt sie anschließend zu mir.\n\nWo Diplomatie versagt, ist Versklavung eine absolut rentable Alternative.", sourceObjective = "Betretet die Höhlen in der Kristallschlucht und fangt mithilfe stabiler Kisten 3 Exemplare der Jormungarbrut. Achtet jedoch darauf, dass Ihr die Kisten einsteckt, sobald die Jormungarbrut gefangen ist!\n\nBringt sie dann zu Zort in der Kristallschlucht.", progress = "Ihr seid zurückgekehrt! Habt Ihr die Biester mitgebracht? Ich muss hier raus... Ich bin mir ziemlich sicher, dass mich Ko'char vor ein paar Minuten zertreten wollte.", completion = "Das dürfte reichen. Vielleicht werde ich diese Biester, sobald sie voll ausgewachsen sind, zurückbringen und sie eigenhändig mit den Riesen bekannt machen.\n\nEin Haufen unnützer Steine, wenn Ihr mich fragt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12079] = { id = 12079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Revier", description = "Sei gegrüßt, <mein Kleiner/meine Kleine>. Ich weiß zwar nicht, welcher Wahnsinn dich in die Kristallschlucht getrieben hat, doch du bist mir willkommen.\n\nDiese Eiswürmer... diese Jormungar haben Geschmack an meinen Brüdern gefunden. Dass meinesgleichen dir in irgendeiner Art und Weise wohlgesinnt sein werden, halte ich für unwahrscheinlich, doch wenn du uns dabei helfen willst, mit den Würmern fertigzuwerden, dann hast du meine ungeteilte Aufmerksamkeit.\n\nWenn wir die Höhle wieder in unseren Besitz bringen wollen, müssen wir zuerst die Schlucht von diesen Jormungarfressern befreien. Steh unserem Kampf bei, {race}!", sourceObjective = "Ko'char der Unbezwingbare möchte, dass Ihr die Höhlen am nördlichen Ende der Kristallschlucht erforscht und 8 Eiskernjormungarfresser tötet.", completion = "Ein Gemetzel nach meinem Geschmack.", sourceObjectiveStatus = "unverified-source-field" }
quests[12080] = { id = 12080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächtig großer Wurm", description = "In den Höhlen dort unten gibt es eine Brutmutter. Wir nennen sie Rüttelbohrer - ein Name, der Ihr von einem Abenteurer aus den Pestländern beschert wurde. Ich schlug gerade ihren ersten Angriff zurück, als ich sie für einen Moment zu Gesicht bekam. Sie ist so groß, dass sie eines meiner Jungen ganz verschlingen könnte. Wir werden die Höhle erst wieder in unseren Besitz bringen können, wenn sie beseitigt ist.", sourceObjective = "Betretet die Eiskernhöhlen und streckt Rüttelbohrer nieder. Benutzt Zorts schützendes Elixier, falls Ihr es noch besitzen solltet, um Euch vor dem ätzenden Speichel der Jormungar zu schützen.\n\nKehrt zu Ko'char dem Unbezwingbaren in der Kristallschlucht zurück, wenn die Aufgabe abgeschlossen ist.", completion = "Sie ist also tot - gut, so soll es sein. Du hast auf jeden Fall bewiesen, dass deine Absichten nobler sind als die des Wichts.\n\nÜber die nördliche Schlucht erreicht Ihr den Kristallsangwald. Es ist ein verfluchter und gefährlicher Ort, {race}. Sei auf der Hut, wenn das dein nächstes Ziel sein sollte.\n\nHier, nimm das als Belohnung für deine Mühen, mein Kleiner. Du hast meinen Segen. Gute Reise.", sourceObjectiveStatus = "unverified-source-field" }
quests[12081] = { id = 12081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gavrock", description = "Ohne Eure Hilfe wären wir nicht dazu in der Lage gewesen, das Blatt in der Schlacht um Thor Modan zu unseren Gunsten zu wenden. In dieser uralten Stadt tobt schon seit langem ein Kampf zwischen den Kräften der Erde und des Gesteins. Ich kann nur hoffen, dass wir die Situation eine zeitlang beruhigt haben.\n\nDie Eisenzwerge können noch immer ihre Magie dazu benutzen, um meine Brüder zu versklaven. Gavrock sucht nach einem Weg, wie wir die runenbeschriebenen Riesen befreien können. Ihr könnt ihn auf einer kleinen Inselgruppe namens Ruinen von Tethys finden. Diese Gruppe liegt vor dem zentralen Teil der Ostwindküste gen Süden.", sourceObjective = "Sprecht mit Gavrock in den Ruinen von Tethys.", completion = "Ich weiß, dass Kurun für Eure Hilfe dankbar ist. Der Sieg über Thor Modan wird eine große Errungenschaft für uns sein, doch unsere Brüder werden wir dadurch nicht befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[12082] = { id = 12082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dan-ta dan-ta dan-ta-dah!", description = "Hört zu, <Kleiner/Kleines>. Das hier ist kein Ort, an dem Ihr herumtollen solltet.\n\nIch mach' gleich den Abflug. Bleibt dicht hinter mir und ich hol' Euch hier raus.", sourceObjective = "Eskortiert Harrison aus den Ruinen von Drakil'jin, sprecht dann mit Harkor im gleichnamigen Lager.", completion = "Ihr habt also das kleine Abenteuer mit unserem guten Freund überlebt, hm?\n\nDas sollte Euch eigentlich schon Belohnung genug sein, aber hier - ich habe heute meinen großzügigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12083] = { id = 12083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über den Waldländern", description = "Ich bin davon überzeugt, dass es noch mehr von diesen Fokussen geben muss, von denen wiederum jeder die Leylinienenergien weiterleitet. Wir wissen allerdings immer noch nicht genau, was sie mit all der Energie anstellen wollen.\n\nIch schätze, dass sich ein weiterer auf dem höchsten Punkt des Waldlandes von Lothalor gen Südosten befinden muss. Ihr werdet also wieder einmal herausfinden müssen, wer dort das Sagen hat, und ihm anschließend das Steuergerät abnehmen, da ich mir sicher bin, dass es für jeden Fokus ein spezielles Gerät geben muss.\n\nSeid auf der Hut, {name}, die Wälder sind voller Gefahren.", sourceObjective = "Beschafft Euch das Steuerungsamulett des Leylinienfokus und verwendet es, um Informationen vom Leylinienfokus in den Waldländern von Lothalor zu erhalten.\n\nKehrt anschließend zum Abbild der Erzmagierin Modera in Sternenruh zurück.", completion = "Sie erfüllen mithilfe des Fokus ihre Truppen mit Macht? Das ergibt keinen Sinn; so mächtig sind die Magierjäger nicht.\n\nDas muss also bedeuten, dass sie die Magie ausschließlich dort verwenden, wo auch immer sie die jeweilige Leylinie hinleiten.\n\nWir werden mehr Informationen benötigen, wenn wir sie finden und aufhalten wollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12084] = { id = 12084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über den Waldländern", description = "Ich bin überzeugt, dass es mehr dieser Fokusse gibt - jeder von ihnen leitet die Energie der Leylinien um. Wir wissen jedoch noch nicht genau, was sie mit all dieser Energie anstellen.\n\nIch schätze, Ihr werdet einen weiteren hoch über den Waldländern im Süden finden. Ihr werdet erneut die zuständige Person finden müssen und die Steuerung, welche diese bei sich trägt, an Euch nehmen - ich bin mir sicher, dass jeder Fokus über eine eigene verfügt.\n\nBeeilt Euch bei Eurem Auftrag, {class} Ich spüre, dass uns die Zeit davonrinnt.", sourceObjective = "Beschafft Euch das Steuerungsamulett des Leylinienfokus und verwendet es, um Informationen vom Leylinienfokus in den Waldländern von Lothalor zu erhalten.\n\nKehrt anschließend zum Abbild des Erzmagiers Aethas Sonnenhäscher bei Agmars Hammer zurück.", completion = "Sie bündeln diese Energie in ihren Truppen? Aber das ergibt keinen Sinn - die Magierjäger sind nicht entsprechend mächtig.\n\nDas kann nur bedeuten, dass sie die Energie in Wirklichkeit nur am Endpunkt der Umleitung, die sie an den Leylinien vorgenommen haben, nutzen.\n\nWir werden weitere Informationen benötigen, wenn ich einen Plan ausarbeiten soll, um sie zu stoppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12085] = { id = 12085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Brief an Zuhause", description = "Im Innenfutter seiner Robe findet Ihr einen Brief, in dem Folgendes geschrieben steht:\n\n\"Deino,\n\nTut Ta'zinni leid, dass er verschwunden ist. Wenn du diesen Brief liest, dann bin ich tot.\n\nDie haben mich gezwungen, für Malygos' Armeen zu malochen. Die haben mir gedroht, meine Familie umzumurksen, wenn ich mich weigerte. Und Ta'zinni wollte das nicht zulassen!\n\nMach dir um mich keine Sorgen, pass nur gut auf deine Kinder auf. Ich hab die hier ausgetrickst und sabotiere sie jetzt von innen heraus.\n\nHab dich lieb, Schwester!\n\nTa'zinni\"\n\nOberanführer Agmar wird das hier sicherlich sehen wollen!", sourceObjective = "Liefert Leutnant Ta'zinnis Brief bei Oberanführer Agmar in Agmars Hammer ab.", progress = "Was soll das? Wollt Ihr etwa einen Brief verschicken?\n\nAlle Briefe gehen erstmal über mich. Hier gibt es nämlich Spione und Verräter!\n\n<Der Oberanführer mustert Euch kurz. Ihr fragt Euch, ob er nicht auf der Stelle die Wachen rufen und Euch umbringen lassen wird.>\n\nNun gut, aber macht schnell. Sollte mir jedoch nicht gefallen, was ich da geschrieben sehe, dann werde ich Euch an meine Worgs verfüttern.\n\n<Agmar grinst, als sich Gar'mak und Lak'tuk zu Euch umdrehen, mit einem Blick in ihren Augen, als wärt Ihr ihre nächste Mahlzeit.>", completion = "Ahahahaha... ach Herr je, wie rührend.\n\n<Der herablassende Ton im tiefen Gelächter des Oberanführers ist unüberhörbar.>\n\nWas habe ich gesagt? Verräter! Immerhin, es gab einmal eine Zeit, da kannte ich Deino. Zumindest ist sie ein Troll von Ehre!\n\nSie wird herausfinden, was mit ihrem Bruder geschehen ist - dafür werde ich sorgen. Und bei der Gelegenheit werde ich sogar vergessen ihr zu sagen, dass Ihr für seinen Tod verantwortlich seid.\n\n<Agmar starrt Euch an. Sein Blick wirkt berechnend.>\n\nDoch nun gehört Ihr mir, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12086] = { id = 12086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karkuts Sohn", description = "Der Mann, nach dem Ihr sucht, ist weit nach Osten gegangen und hat einen Ort in Küstennähe jenseits von Unu'pe aufgesucht, den man Todeswehr nennt.\n\nSeid vorsichtig, wenn Ihr dorthin geht und nach ihm sucht, {name}. Er trug das Zeichen Karkuts... der über die Toten wacht.", sourceObjective = "Geht in Richtung Osten nach Todeswehr jenseits von Unu'pe.", completion = "Thassarian? Ja, er war hier... was ist mit ihm? Wir haben dringendere Probleme im Moment, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12088] = { id = 12088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thassarian der Todesritter", description = "Nun, {name}, Ihr habt uns also geholfen... deshalb ist es wohl nur angemessen, wenn wir Euch auch helfen.\n\nIhr sucht nach Thassarian? Er verschwand heute Morgen. Wir vermuten, dass er gen Norden zur Klagenden Ziggurat gegangen ist. Wenn wir nicht Seite an Seite mit ihm gekämpft hätten, würden wir ihn sogar für einen Verräter halten.\n\nIhr müsst verstehen, er ist ein Todesritter... und ich weiß, dass diese auf unserer Seite sind und so weiter... aber vor nicht allzu langer Zeit waren diese Arthas' Diener.\n\nAber nicht Thassarian. Er ist ein guter Kerl. Geht zur Klagenden Ziggurat und seht, ob er zurechtkommt.", sourceObjective = "Seht nach Thassarian im Inneren der Klagenden Ziggurat nördlich von Todeswehr.", completion = "Leryssa... sucht nach mir? Ihr müsst mir helfen, {name}. Wir müssen dies zu Ende bringen, bevor ihr etwas zustößt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12089] = { id = 12089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Magister Keldonus", description = "Auf Erlass des Oberanführers Agmar:\n\nAngeklagter: Magister Keldonus\n\nVerbrechen: Verrat\n\nZustand: lebendig\n\nIm Namen der Horde ist Magister Keldonus, einstiger Magierkommandant von Agmars Hammer, auf der Stelle zu töten.\n\nGesichtet wurde Keldonus das letzte Mal, als er auf dem Weg nach Südwesten in Richtung der Mondruhgärten unterwegs war, um sich dort dem blauen Drachenschwarm und dem Feldzug gegen die Magie anzuschließen.\n\nKeldonus sollte mit Vorsicht begegnet werden.\n\nHauptmann Gort in Agmars Hammer ist für die Auszahlung aller Kopfgelder verantwortlich.", sourceObjective = "Erschlagt Magister Keldonus und kehrt anschließend zu Hauptmann Gort in Agmars Hammer in der Drachenöde zurück.", completion = "Nicht das Erste dieser Magierweicheier, das uns verraten hat, und sicherlich nicht das Letzte. Ist aber auch verdammt schade... Er war einer unserer besten Magier. Er konnte ein Büffet herzaubern, dass einem das Wasser im Munde zusammenlief und Herzen höher schlugen...\n\nBAH!", sourceObjectiveStatus = "unverified-source-field" }
quests[12090] = { id = 12090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Gigantaur", description = "Auf Erlass des Oberanführers Agmar:\n\nAngeklagter: Gigantaur\n\nVerbrechen: Angriffe auf die Horde; \"potthässlich\"\n\nZustand: lebendig\n\nDer Magnataurenfürst Gigantaur wird in Verbindung mit einer Reihe von Angriffen auf die Soldaten und Anlagen der Horde in der Drachenöde gesucht.\n\nZuletzt wurde Gigantaur in den Wäldern und auf den Straßen südlich und südöstlich von Agmars Hammer gesehen.\n\nGigantaur gilt als bewaffnet und extrem gefährlich.\n\nHauptmann Gort in Agmars Hammer ist für die Auszahlung aller Kopfgelder verantwortlich.", sourceObjective = "Erschlagt Gigantaur und kehrt anschließend zu Hauptmann Gort in Agmars Hammer in der Drachenöde zurück.", completion = "Ihr habt dieses hässliche Pferdegesicht also erwischt, hm? Tja, eine Plage weniger, um die sich unsere Soldaten draußen auf den eisigen Weiten kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12091] = { id = 12091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schreckensklaue", description = "Auf Erlass des Oberanführers Agmar:\n\nAngeklagter: Schreckensklaue\n\nVerbrechen: Angriffe gegen die Horde\n\nZustand: lebendig\n\nSchreckensklaue wird wegen zahlreicher Angriffe auf Karawanen der Horde in der Nähe von Gallgrimm gesucht.\n\nEr hält sich meist auf einer Anhöhe über dem Rubindrachenschrein östlich von Agmars Hammer auf. Ihm sollte mit äußerster Vorsicht begegnet werden.\n\nHauptmann Gort in Agmars Hammer ist für die Auszahlung aller Kopfgelder verantwortlich.", sourceObjective = "Erschlagt Schreckensklaue und kehrt anschließend zu Hauptmann Gort in Agmars Hammer in der Drachenöde zurück.", completion = "Wurde auch langsam mal Zeit, dass jemand der Metzelei dieser dreckigen Bestie ein Ende macht! Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12092] = { id = 12092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkt die Urtume", description = "Nicht nur Euer Volk ist von dem betroffen, was der blaue Drachenschwarm getan hat. Auch die Urtume der Wälder von Lothalor gen Südosten bekamen die Auswirkungen zu spüren.\n\nEinige fielen der Verderbnis anheim - diese müsst Ihr um jeden Preis meiden -, doch die meisten können noch immer gerettet werden. Die Treants in den Wäldern scheinen jedoch immun gegen die Magie zu sein, die durch das Land sickert und mit der auch die Wyrms kommen.\n\nBittet die Treants um ihre Borke und gebt sie den Urtumen zu essen. Hoffentlich wird das genügen, um sie zu retten.", sourceObjective = "Benutzt die Borke der Wanderer und stärkt damit 3 Urtume von Lothalor. Kehrt anschließend zu Sarendryana in Sternenruh zurück.", completion = "Ich danke Euch, {race}! Wir haben schon so viel verloren. Ihr habt dafür gesorgt, dass uns die Majestätischsten von Nordends Kindern erhalten bleiben.\n\nIch werde bald gehen und mit den Urtumen sprechen, die Ihr gerettet habt. Mal sehen, ob sie uns in diesen Zeiten der Not nicht helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12093] = { id = 12093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runen des Zwangs", description = "Noch während Kurun Thor Modan angreift, wirken die Eisenzwerge ihre Magie gegen unsere Brüder. Indem sie unsere Brüder aus der Erde beschwören und sie mit Runen an sich binden, zwingen die Söhne des Eisens sie zum Kampf gegen die Kinder des Steins.\n\nEntlang der Ostwindküste verwenden sie Runen des Zwangs, um versklavte Riesen zu den Schlachtfeldern im Norden zu entsenden.\n\nFindet die vier Runen des Zwangs und zwingt ihre Aufseher zum Erscheinen, indem Ihr die Runenweber überwältigt, die jede Rune bemannen. Ohne die Aufseher sind die Runen nutzlos.", sourceObjective = "Gavrock in den Ruinen von Tethys möchte, dass Ihr die vier Runen des Zwangs ausschaltet, indem Ihr Aufseher Durval, Aufseher Korgan, Aufseher Lochli und Aufseher Brunon besiegt.", completion = "Gut. Nun müssen wir rasch handeln, bevor die Söhne des Eisens bemerken, dass ihre Runen wirkungslos geworden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[12094] = { id = 12094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Latente Macht", description = "So lange die Runen des Zwangs nicht aktiv sind, besteht die Chance, dass wir die runenbeschriebenen Riesen freilassen können.\n\nIch werde Euch ein Stück des Steins geben, der schon seit meiner Erschaffung ein Teil von mir geblieben ist. Erfüllt man ihn mit der richtigen Kraft, so kann man mit seiner Hilfe die gefangenen Riesen befreien.\n\nZwischen dem Waldrand und dem Eisenpfad befinden sich Orte der Macht - Orte, die Euer Volk Leylinienknotenpunkte nennen würde - und dort gibt es auch zwei uralte Steinmarkierungen. Eine weitere Steinmarkierung befindet sich auf einer Insel am südlichen Ende dieser Ruinen. Ladet den Splitter bei jedem dieser Steine auf.", sourceObjective = "Ladet den Splitter von Gavrock am ersten, zweiten und dritten uralten Stein auf und kehrt anschließend zu Gavrock in den Ruinen von Tethys zurück.", progress = "Habt Ihr die uralten Steine gefunden?", completion = "Ich kann die Macht spüren, mit der Ihr den Splitter erfüllt habt, und ich hoffe, dass sie genügen wird, um die runische Magie zu bannen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12095] = { id = 12095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Drachenjägerposten", description = "Östlich von hier, im Herzen der Drachenöde, befindet sich ein Feld, auf dem sich nichts als Drachenknochen und Schnee befinden. Die Geißel hat mehrere Lager in der zentralen Tundra aufgeschlagen und ruft Frostwyrms wieder ins Leben, um sie dann auf unsere Streitkräfte an der Pforte des Zorns zu hetzen. Rokhan und seine Drachenjäger können zwar mit den meisten dieser Frostwyrms fertigwerden, doch einer von ihnen erweist sich als problematisch.\n\nSucht Rokhan in Drachensturz im Nordosten auf. Helft ihm und seinen Männern Sarathstra niederzustrecken und Ihr werdet reichlich belohnt werden!", sourceObjective = "Sprecht mit Rokhan in Drachensturz in der Drachenöde.", completion = "Denkst du, dass du dort siegen kannst, wo Rokhan versagt?", sourceObjectiveStatus = "unverified-source-field" }
quests[12096] = { id = 12096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkt die Urtume", description = "Die Urtume des Waldlandes von Lothalor im Süden werden von Arkanwyrm verderbt... Wyrm, die direkt aus der Erde gekommen sind!\n\nDie schon Verderbten sind tödlich und nützen uns nichts, doch die meisten können noch immer gerettet werden. Zum Glück scheinen die Treants der Wälder immun gegen alles zu sein, was dort vor sich geht.\n\nBittet die Treants, Euch etwas von ihrer Rinde abzugeben, und verfüttert diese anschließend an die Urtume - das sollte sie stärken.\n\nNun lasst mich in Ruhe arbeiten! Ich muss ein Auge auf diese Apotheker werfen.", sourceObjective = "Benutzt die Borke der Wanderer, um 3 Urtume von Lothalor zu stärken, und kehrt anschließend zu Erdwächter Graif in Agmars Hammer zurück.", completion = "Habt meinen Dank, {class}.\n\nSobald ich herausgefunden habe, was diese widerwärtigen Apotheker vorhaben, werde ich mich auf den Weg zu den Wäldern machen und sehen, ob ich die Urtume davon überzeugen kann, dass sie sich uns anschließen.\n\nZumindest sollte ich sie davon überzeugen können, ihre Retter in Frieden zu lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12097] = { id = 12097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sarathstra, Geißel des Nordens", description = "Meine Jäga sind tot oda eingefrostet, {name}. Noch imma Lust drauf? Ein Wort reicht und ich werde nochmal nach'm Drachen rufen.\n\nBring das gefrorene Herz vom Biest nach Agmars Hammer und gib es Gort. Er wiad dich ganz bestimmt dick belohnen, Mann.", sourceObjective = "Sprecht mit Rokhan, um den Frostwyrm Sarathstra herbeizurufen.\n\nTötet Sarathstra und liefert Sarathstras gefrorenes Herz bei Hauptmann Gort in Agmars Hammer ab.", progress = "<Gort hebt eine Braue.>\n\nSchon zurück?", completion = "HA! Ihr habt es geschafft! Die Soldaten an der Pforte des Zorns stehen in Eurer Schuld, {name}! Das wird einigen von ihnen sicherlich ein paar Tage mehr auf dieser Welt bescheren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12098] = { id = 12098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchsucht Indu'le", description = "Ich bin mir sicher, dass Ihr den nächsten Leylinienfokus irgendwo in den Überresten von Indu'le im Südosten finden werdet. Das Problem ist nur, dass wir überhaupt keine Meldungen darüber erhalten haben, ob es dort einen gibt oder nicht.\n\nWenn Ihr das Dorf bitte nach irgendwelchen Hinweisen über den Fokus oder die Magierjäger und ihren Kommandanten in der Gegend durchsuchen würdet, wäre ich dankbar.\n\nVergesst nicht, auch im See nachzusuchen, wenn es sein muss.", sourceObjective = "Sucht in Indu'le und im Wasser von Indu'le nach dem Kommandanten der Magierjägertruppen.", completion = "An dieser Stelle findet Ihr die Leiche des Kommandanten der Magierjäger.\n\nNach seinem Aussehen und dem Zustand der Truppen um ihn herum zu urteilen, scheinen sie nicht ertrunken zu sein. Vielmehr erweckt die Szene den Eindruck, als hätten sie den Angriff der Elementare aus den Rissen im Seebett nicht erwartet.\n\nDem Anschein nach waren die Magierjäger für ihr eigenes Ableben verantwortlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[12099] = { id = 12099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich frei", description = "Der Steinsplitter, den Ihr mit Kraft erfüllt habt, sollte mächtig genug sein, um die runische Magie zu bannen, die meine Brüder gefangen hält.\n\nNehmt ihn mit und sucht nach den runenbeschriebenen Riesen, die im Norden die Ostwindküste entlang marschieren. Setzt die Macht, die im Stein gespeichert ist, frei und seht, was passiert.\n\nFalls er funktionieren sollte, dann müssten die Riesen wieder zur Besinnung kommen und den Befehlen der Eisenzwerge nicht mehr Folge leisten. Sollte der Stein nicht funktionieren, ist es möglich, dass die Riesen geschwächt werden und Euch angreifen. Doch haben wir überhaupt eine Wahl? Wenn wir es nicht versuchen, werden sie für immer versklavt bleiben.", sourceObjective = "Befreit mit Gavrocks Runenbrecher 4 runenbeschriebene Riesen und kehrt anschließend zu Gavrock in den Ruinen von Tethys zurück.", completion = "Das Ding ist also nicht zuverlässig? Ich wünschte, dass es keine Frage des Glücks wäre, doch zumindest sind wir auf dem richtigen Weg. Ohne Eure Hilfe, wäre dies nie möglich gewesen. Falls Ihr noch mehr über die Machenschaften der Eisenzwerge und deren Pläne bezüglich der Steinkinder herausfinden solltet, dann sucht uns auf und wir werden Euch anhören, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12100] = { id = 12100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verwesung Einhalt gebieten", description = "Die Geißel bringt Tod und Krankheit mit sich. Wir übersehen nur zu oft, dass die Tierwelt in den von der Geißel verseuchten Gegenden stark angeschlagen ist und durch die ansteckende Verwesung letztendlich ausgelöscht wird.\n\nFür die meisten einheimischen Tiere der Drachenöde ist es schon zu spät. Die Tiere sind schon mit der Krankheit der Geißel infiziert, deren Kennzeichen eitrige Pusteln sind - nun verwesen sie vor sich hin und sind von Tollwut befallen.\n\nGeht nach Westen zur Grube von Narjun und tötet die infizierten Tiere. Seht nach, ob sich in ihren Leichen ein gut erhaltenes Organ finden lässt, da wir eins brauchen, um ein Gegengift daraus herzustellen.", sourceObjective = "Soar Falkenzorn in Agmars Hammer in der Drachenöde möchte, dass Ihr 15 infizierte Wildtiere tötet und ein verwesungsresistentes Organ beschafft.", progress = "Tötet die Tiere, um die Verbreitung der Krankheit zu verhindern, und bringt mir ein verwesungsresistentes Organ.", completion = "Zwar schmerzt es mich, Tiere zu töten, jedoch müssen wir uns dieser Pflicht annehmen. Kommen wir nun zum nächsten Schritt: der Impfung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12101] = { id = 12101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gute Doktor...", description = "Die Verlassenen, unsere Verbündeten, haben die wichtigsten Mitglieder ihrer Apothekervereinigung hierher entsandt, um uns bei der Vernichtung der Geißel an der Pforte des Zorns zu unterstützen. Unter ihnen befindet sich jemand namens Doktor Sintar Malefius, ein Kenner, wenn es um die Fäulnis der Geißel und deren Verbreitung geht. Ich hatte zuvor mit ihm eine Einigung in Bezug auf die Impfung der betroffenen Tiere erzielt - seitdem wartet er auf ein Organ.\n\nLiefert dieses verwesungsresistente Organ bei Dr. Malefius ab und lasst ihn wissen, dass es von mir ist. Von ihm werdet Ihr auch Euren nächsten Auftrag erhalten.", sourceObjective = "Liefert das verwesungsresistente Organ bei Doktor Sintar Malefius in Agmars Hammer ab.", progress = "Was jetzt?", completion = "Der rüpelhafte Ochsenmensch konnte tatsächlich ein verwesungsresistentes Organ besorgen? Verflucht... ich war mir sicher, dass diese Aufgabe seinen missgebildeten Geist bis ins nächste Jahrtausend beschäftigen würde.\n\nNa gebt schon her, Junge. Ich habe ohnehin schon viel zu tun, auch wenn Eure schwächlichen Bedürfnisse mir nicht gerade im Weg stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12102] = { id = 12102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach dem rubinfarbenen Flieder", description = "Ein Glücksfall, dass der Rubindrachenschrein gleich im Osten liegt. Dort findet sich auch eine Blume, die man den rubinfarbenen Flieder nennt. Diese lebensspendende Pflanze ist alles, was ich brauche, um einen Impfstoff für die gesunden Tiere dieser Region herzustellen.\n\nGeht nach Osten und sucht im Rubindrachenschrein nach dem Flieder.\n\nEine Sache noch: Wie alle Drachenschreine in dieser verfluchten Einöde so wird auch dieser Drachenschrein von der Geißel heimgesucht. Passt also auf, wo Ihr hintretet. Wir wollen doch nicht, dass Ihr von einem Glutwyrm verschlungen werdet.\n\n<Sintar lacht.>", sourceObjective = "Doktor Sintar Malefius in Agmars Hammer in der Drachenöde möchte, dass Ihr 1 rubinfarbenen Flieder pflückt.", progress = "Habt Ihr den rubinfarbenen Flieder dabei?", completion = "Das war doch nicht so schwer, oder?\n\nNun gebt mir ein wenig Zeit, damit ich den Impfstoff herstellen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12103] = { id = 12103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor dem Sturm", description = "{name}! Ich habe schon überall in dieser seltsamen Stadt nach Euch gesucht!\n\nGroßmeister Hight hat angeordnet, dass alle erfahrenen Mönche so schnell wie möglich zum Gipfel der Ruhe zurückkehren sollen. Das gilt natürlich auch für Euch.\n\nIch wette eine Wochenration Gebräu darauf, dass dies etwas mit dem Angriff auf die Verheerte Küste zu tun hat, von dem ich gehört habe!", sourceObjective = "Unterstützt Großmeister Hight am Gipfel der Ruhe.", completion = "Willkommen zurück im Land der Lebenden, {name}. Wir hätten Euch fast bei dieser Explosion verloren! Was für ein Glück, dass sich die Wandernde Insel gerade in der Nähe befand.\n\nDie Leute hier haben uns freundlicherweise erlaubt, uns im Tempel niederzulassen. Es ist nicht gerade der Gipfel der Ruhe, aber dennoch ein schönes, neues Zuhause.", sourceObjectiveStatus = "unverified-source-field" }
quests[12104] = { id = 12104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Soar zurück", description = "<Doktor Malefius gibt Euch eine Phiole, die mit einer trüben Flüssigkeit gefüllt ist.>\n\nBitte schön, {race}. Bringt das hier wieder zu diesem Rindvieh und lasst es wissen, dass damit alle Schulden beglichen sind. Wir sind nun ganz offiziell wieder quitt.\n\nLasst mich allein, bevor ich Jennings auf Euch loslasse.", sourceObjective = "Liefert Sintars Impfstoff bei Soar Falkenzorn in Agmars Hammer ab.", progress = "Habt Ihr den Impfstoff dabei?", completion = "<Soar hält die Phiole in die Höhe und überprüft seinen Inhalt.>\n\nBleibt nur noch eine Sache zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[12105] = { id = 12105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstieg in die Dunkelheit", description = "Das Tagebuch wurde von einem Einwohner Silberwassers namens Mikhail geschrieben. Es beschreibt die Ankunft einer Gruppe von Schattenanbetern, die sich \"Wolfskult\" nannten.\n\nZunächst waren die Dorfbewohner zögerlich, sich dem Kult anzuschließen, aber mit der Zeit gab es mehr und mehr Sympathisanten unter der Bevölkerung.\n\nBeunruhigt dadurch, schickte Mikhail seine Tochter Dasha aus Silberwasser fort, und er versuchte, vernünftig mit den Dörflern zu reden.\n\nSein letzter Eintrag erwähnt eine Versammlung der Dorfoberen, um nicht näher beschriebene Ereignisse in der Hohlsteinmine zu diskutieren.", sourceObjective = "Bringt Mikhails Tagebuch zu Leutnant Dumont bei der Ammertannhütte.", progress = "Was habt Ihr da?", completion = "Ich dachte mir doch, dass es mehr damit auf sich hat, als lediglich ein isoliertes Dorf voller Feinde.\n\nWir haben ein paar Männer in der Nähe der Hohlsteinmine, vielleicht lohnt es sich ja, sich dort ein wenig umzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12106] = { id = 12106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchsucht Indu'le", description = "Ich bin mir sicher, dass Ihr den nächsten Leylinienfokus irgendwo in den Überresten von Indu'le im Südosten finden werdet. Das Problem ist nur, dass ich überhaupt keine Meldungen darüber erhalten habe, ob es dort einen gibt oder nicht.\n\nIch möchte, dass Ihr Euch im Dorf nach irgendwelchen Hinweisen über den Fokus oder die Magierjäger und ihren Kommandanten in der Gegend umseht.\n\nSucht auch im See nach, wenn es sein muss!", sourceObjective = "Sucht in Indu'le und im Wasser von Indu'le nach dem Kommandanten der Magierjägertruppen.", completion = "An dieser Stelle findet Ihr die Leiche des Kommandanten der Magierjäger.\n\nNach seinem Aussehen und dem Zustand der Truppen um ihn herum zu urteilen, scheinen sie nicht ertrunken zu sein. Vielmehr erweckt die Szene den Eindruck, als hätten sie den Angriff der Elementare aus den Rissen im Seebett nicht erwartet.\n\nDem Anschein nach waren die Magierjäger für ihr eigenes Ableben verantwortlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[12107] = { id = 12107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endstation", description = "In seinen Roben findet Ihr zwei Dinge von Interesse.\n\nZum einen handelt es sich um einen Talisman, der eindeutig zur Steuerung eines Fokus dient. Zum anderen um eine Sammlung mehrerer Befehle, die von jemand namens Sidragos ausgestellt wurden und letztendlich für den Anführer in den Mondruhgärten gedacht waren.\n\nLaut Anordnung auf dem nassen Pergament, soll Goramosh all seine Magierjägertruppen nach Osten zum Azurdrachenschrein beordern.\n\nVielleicht solltet Ihr so viel wie möglich von dem Fokus erfahren und dann nach Osten gehen, um den Drachenschrein von der westlichen Seite her beobachten zu können.", sourceObjective = "Benutzt den Steuerungstalisman des Leylinienfokus, um Informationen vom Leylinienfokus unter dem Wasser von Indu'le zu erhalten. Geht anschließend nach Osten zum Azurdrachenschrein, der sich vom Zentrum der Drachenöde aus gesehen weiter südlich befindet, und beobachtet das dortige Vorgehen vom westlichen Felsvorsprung aus.\n\nKehrt danach zum Abbild der Erzmagierin Modera in Sternenruh zurück.", completion = "WAS?!\n\n<Einen Augenblick lang verzerrt sich das Abbild vor Euch, während die Erzmagierin versucht, ihre Fassung wiederzugewinnen.>\n\nAber natürlich, wir hätten eigentlich wissen müssen, dass sie das die ganze Zeit über vorhatten. Schnell, Wir haben keine Zeit zu verlieren.\n\nWyrmruh muss gewarnt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12109] = { id = 12109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Gryan Starkmantel... schon wieder", description = "Die Jungs von Westfall wurden nach Osten geschickt, um einen Weg in die nördlichen Territorien zu finden. Ihr zweites Missionsziel ist das Sicherstellen von strategisch wichtigen Ressourcen - ich bin mir also sicher, dass es ihnen nichts ausmachen würde, eine Mine zu untersuchen.\n\nSucht nach dem Lager der Westfallbrigade weit im Nordosten und sucht nach Gryan Starkmantel. Ihr werdet Euch vielleicht noch an ihn erinnern können, wenn Ihr jemals schon in Westfall gewesen seid. Sagt ihm auf jeden Fall, dass ich Euch geschickt habe.\n\nEr wird Euch nur zu gerne erlauben, eine intakte Mine für den König in Besitz zu nehmen.", sourceObjective = "Sprecht mit Hauptmann Gryan Starkmantel im Lager der Westfallbrigade.", completion = "Dumont hat Euch geschickt? Schön. Sehen wir einmal, was Ihr für uns tun könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12110] = { id = 12110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endstation", description = "In seinen Roben findet Ihr zwei Dinge von Interesse.\n\nZum einen handelt es sich um einen Talisman, der eindeutig zur Steuerung eines Fokus dient. Zum anderen um eine Sammlung mehrerer Befehle, die von jemand namens Sidragos ausgestellt wurden und letztendlich für den Anführer in den Mondruhgärten gedacht waren.\n\nLaut Anordnung auf dem nassen Pergament, soll Goramosh all seine Magierjägertruppen nach Osten zum Azurdrachenschrein beordern.\n\nVielleicht solltet Ihr so viel wie möglich von dem Fokus erfahren und dann nach Osten gehen, um den Drachenschrein von der westlichen Seite her beobachten zu können.", sourceObjective = "Benutzt den Steuerungstalisman des Leylinienfokus, um Informationen vom Leylinienfokus unter dem Wasser von Indu'le zu erhalten. Geht anschließend nach Osten zum Azurdrachenschrein, der sich vom Zentrum der Drachenöde aus gesehen weiter südlich befindet, und beobachtet das dortige Vorgehen vom westlichen Felsvorsprung aus.\n\nKehrt danach zum Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer zurück.", completion = "WAS?!\n\n<Einen Augenblick lang verzerrt sich das Abbild vor Euch, während der Erzmagier versucht, seine Fassung wiederzugewinnen.>\n\nAber natürlich, wir hätten eigentlich wissen müssen, dass sie das die ganze Zeit über vorhatten. Schnell, es gibt keine Zeit zu verlieren.\n\nDer Wyrmruhtempel muss gewarnt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12111] = { id = 12111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo die wilden Tiere wohnen", description = "In dieser Packung befinden sich mehrere Phiolen mit dem von Sintar hergestellten Gegengift. Nun möchte ich, dass Ihr die Wälder in der Nähe nach Schneewehenelchen und arktischen Grizzlys absucht. Werft, wenn Ihr eines der Tiere gefunden habt, eine Phiole in deren Nähe. Die Phiole wird zerspringen und ein dünnes Gas freisetzen, das als Impfstoff dienen wird. Die Tiere müssen lediglich in die Gaswolke hineingehen, um geimpft und letztendlich gerettet zu werden.\n\nVerabreicht den Impfstoff so vielen Tieren wie nur möglich und kehrt anschließend zu mir zurück.", sourceObjective = "Soar Falkenzorn in Agmars Hammer in der Drachenöde möchte, dass Ihr mithilfe der Packung mit Impfstoffen 5 Schneewehenelche und 5 arktische Grizzlys impft.", completion = "Ihr habt etwas Ehrenhaftes getan, {name}. Ich bitte Euch, sucht Euch eine Belohnung aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[12112] = { id = 12112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstarrte Verhandlungen", description = "Nun, es scheint, als hättet Ihr Euch letztendlich doch ein wenig nützlich gemacht. Meiner Erfahrung nach, gibt es nicht viele Eures Volkes, die das von sich behaupten können.\n\nWir haben hier keine Verwendung mehr für Euch. Geht zur Kristallschlucht und seht nach, ob mein Bruder Zort ein helfendes Händchen gebrauchen könnte. Er wollte die Riesen davon überzeugen, ob sie nicht ihr Leben lassen wollen, damit wir's nicht tun müssen. In unserer Familie galt er nicht gerade als der Klügste.", sourceObjective = "Findet Zort im Zentrum der Kristallschlucht, nordöstlich des Düsenrostpostens.", completion = "Ich lass mir was einfallen, wie Ihr Euch nützlich machen könnt - bleibt noch ein Weilchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12113] = { id = 12113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Fleisch kein Preis", description = "Guten Tag, {class}! Wollt Ihr Euch nicht an mein Feuer setzen?\n\nIch würde Euch zwar eine gute, heiße Mahlzeit anbieten, nur habe ich keine. Ich sitze hier fest und warte auf einen Kumpanen, ansonsten würde ich mich selbst um die Sache kümmern.\n\nIhr scheint mehr als genug Zeit übrig zu haben und in dieser Gegend gibt es eine Menge Fleisch. Was würdet Ihr davon halten, wenn Ihr mir helfen und etwas zu Essen beschaffen würdet?", sourceObjective = "Harkor in Harkors Lager möchte, dass Ihr 10 Stück feinfasriges Worgfleisch von den streunenden Grauheulern und 10 Schaufelhornsteaks von den Langhufgrasfressern beschafft.", progress = "Mein Bauch knurrt, {race}. Konntet Ihr etwas zu Essen beschaffen?", completion = "Ausgezeichnet!\n\nNichts schmeckt besser zum Bier als ein heißes Stück Fleisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12114] = { id = 12114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therapie", description = "Trolle… Ich hass'se alle! <Harkor spuckt.>\n\nIch hab's ja mal geschafft, so 'ner Bande von Bestien in die Hände zu fallen… War so nah dran, mir meinen Kopf schrumpfen zu lassen!\n\nMeine Freunde sagen mir, ich solle einfach weitermachen und das alles hinter mir lassen, aber das geht einfach nich'.\n\nWollt Ihr wissen, was mich glücklich machen würde, {race}? 'Nen Haufen ihrer Leichen zu sehen, so hoch, dass er die Sonne verdunkelt! Ich hab' gutes Gold für Euch, wenn Ihr das möglich macht.", sourceObjective = "Harkor in Harkors Lager möchte, dass Ihr 10 Drakkaribeschützer und 10 Drakkariorakel außerhalb der Ruinen von Drakil'jin tötet.", completion = "Habt Dank, {class}.\n\nWenn es die Zeit erlaubt, werd' ich aufsteh'n und mal ein bisch'n herumschauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12115] = { id = 12115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koltira und die Sprache des Todes", description = "Es gibt einen, der sich vor Kurzem unserer Sache verschrieben hat, jemanden, der diesen Folianten womöglich entschlüsseln kann. Ein freier Todesritter hat sich vorübergehend hier in Agmars Hammer niedergelassen. Einst stand er im Dienste von Arthas und war ein Mitglied der Geißel - vielleicht ist er dazu imstande, die Sprache der Toten zu übersetzen.\n\nNehmt den fleischgebundenen Folianten, bringt ihn zu Koltira und bittet ihn, die Seiten zu übersetzen.", sourceObjective = "Bringt den fleischgebundenen Folianten zu Koltira Todesweber.", progress = "Was ist, {race}?", completion = "Es gibt nur zwei Dinge im Leben, die mich interessieren, Peon, und einen Folianten der Geißel für Euch zu übersetzen, gehört nicht dazu.\n\nJedoch... vielleicht könnte sich ja was arrangieren lassen, das uns beiden zugute kommt.\n\n<Koltira zieht sein Schwert aus der Scheide.>\n\nDas ist meine Runenklinge Bifrost - und Bifrost durstet es nach dem Blut des Lichkönigs und seiner Diener; doch zuerst muss ich Runen der Macht auf seine Klinge einprägen: Symbole des Frosts, des Blutes und des Unheiligen. Bringt mir die passenden Quellen der Macht und ich werde Euren Folianten übersetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12116] = { id = 12116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man braucht schon einen starken Magen…", description = "Seid gegrüßt, {class}. Nett von Euch, anzuhalten und Euch Kraz' Geschichte anzuhören.\n\nSeit vielen Jahren bemüht sich Kraz, die Geister zu hören und ihre Wünsche zu erfüllen.\n\nIn letzter Zeit hat Kraz viele Stimmen aus diesen Ruinen rufen gehört. Sie streben nach Frieden, den sie alleine nicht finden können.\n\nWenn Ihr den Geistern derer, die zuvor gekommen sind, helfen wollt, so betretet die Gruft und sammelt etwas, das einst diesen gequälten Seelen gehörte.", sourceObjective = "Kraz in Harkors Lager möchte, dass Ihr Euch in die Ruinen von Drakil'jin begebt und 5 Drakkarikanopen einsammelt.", progress = "Was habt Ihr in der Gruft für Kraz gefunden, {class}?", completion = "Innereien? Eine interessante Wahl, {race}.\n\nKraz soll mal sehen, was man alles von ihnen lernen kann. Danke, dass Ihr Euch in die Tiefen dieses Ortes gewagt und der Gefahr getrotzt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12117] = { id = 12117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reist zum Hafen Moa'ki", description = "{race}, gerade erhielten wir Kunde aus dem Hafen Moa'ki. Heute früh ist dort etwas ganz Schreckliches passiert!\n\nIhr wart uns hier eine große Hilfe. Wäre es denkbar für Euch, auf das Boot zu steigen und in Richtung Drachenöde zu reisen?\n\nSo wie sich die Dinge anhören, könnte Häuptling Ko'nani mit Sicherheit Eure Hilfe gebrauchen.", sourceObjective = "Reist zum Hafen Moa'ki in der Drachenöde und sprecht mit dem Ältesten Ko'nani.", completion = "Was sagt Ihr, {race}? Hotawa hat Euch geschickt?\n\nGut, gut... es gibt viel zu tun. Wir können jede Hilfe, die man uns anbietet, gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12118] = { id = 12118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reist zum Hafen Moa'ki", description = "{race}, gerade erhielten wir Kunde aus dem Hafen Moa'ki. Heute früh ist dort etwas ganz Schreckliches passiert!\n\nIhr wart uns hier eine große Hilfe. Wäre es denkbar für Euch, auf das Boot zu steigen und in Richtung Drachenöde zu reisen?\n\nSo wie sich die Dinge anhören, könnte Häuptling Ko'nani mit Sicherheit Eure Hilfe gebrauchen.", sourceObjective = "Reist zum Hafen Moa'ki in der Drachenöde und sprecht mit dem Ältesten Ko'nani.", completion = "Was sagt Ihr, {race}? Anuniaq hat Euch geschickt?\n\nGut, gut... es gibt viel zu tun. Wir können jede Hilfe, die man uns anbietet, gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12119] = { id = 12119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz erhalten", description = "{name}, Ihr müsst so schnell, wie Ihr könnt, zum Wyrmruhtempel reisen und dem Bediensteten Tariolstrasz diesen Brief überreichen.\n\nDer Tempel liegt im Zentrum der Drachenöde. Folgt der Straße in östliche Richtung bis zu ihrem Ende und durchquert die Dracheneiswüste, um dorthin zu gelangen.\n\nWenn der Bedienstete Euer Vorstellungsschreiben erst einmal gesehen hat, wird er Euch sicherlich eine Audienz bei Königin Alexstrasza beschaffen, denke ich. Wir können nur darauf hoffen, dass es nicht schon zu spät ist.\n\nIch danke Euch für all das, was Ihr für uns getan habt. Gute Reise!", sourceObjective = "Geht zum Wyrmruhtempel und liefert das Vorstellungsschreiben bei Tariolstrasz ab.", progress = "Ja? Was kann ich für Euch tun, {race}?", completion = "Ein Vorstellungsschreiben und Gesuch um ein Treffen mit der Königin? Zeigt einmal her.\n\nWas auch immer Euer Anliegen auch sein mag, ich hoffe, es ist wichtig. Der Himmel wimmelt heute nur so von angreifenden Blauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12120] = { id = 12120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlaghammer von Drak'aguul", description = "Verderbnis...\n\nKraz hatte sie sogar schon spüren können, bevor Ihr die Töpfe brachtet. Die Verderbnis erfüllt die uralten Drakkarigeister mit großer Angst und hält sie davon ab, die Ruhe zu finden, nach der es sie verlangt.\n\nKraz wird nicht lügen, {class}. Diesen Ort zu reinigen wird ein großes Opfer abverlangen, doch darüber werden wir ein anderes Mal sprechen.\n\nUnter den Lebenden hier befindet sich einer, der den Schlüssel zu seiner Läuterung in Händen hält. Sucht Drak'aguul auf und bringt Kraz seinen Schlaghammer.", sourceObjective = "Kraz in Harkors Lager möchte, dass Ihr Drak'aguul außerhalb der Ruinen von Drakil'jin tötet und mit dem Schlaghammer von Drakil'jin zurückkehrt.", progress = "Habt Ihr den Schlaghammer gefunden, {name}?", completion = "So weit, so gut, {name}, doch nun kommt die wahre Prüfung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12121] = { id = 12121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sehen uns auf der Anderen Seite wieder", description = "Diese Drakkari sind Euch eindeutig mit barbarischer Feindschaft begegnet. Ihr schuldet ihnen gar nichts. In der Tat sind es nur wenige, welche die Aufgabe, die Kraz heute von Euch verlangt hat, ausführen würden.\n\nUm diesen Ort zu reinigen und die Geister ihrer letzten Ruhe zu übergeben, müsst Ihr sie im Reich des Todes wiedertreffen.\n\nIn der Krypta ist jemand, der Euch auf der anderen Seite erwartet. Er hat die Informationen, die wir benötigen, {name}.\n\nSchlagt die Gongs mit dem Hammer. Der Geist dessen, der diesen Ort verderbt, wird Euch mit Sicherheit in die Geisterwelt befördern.\n\nKraz erwartet Eure Wiederkehr.", sourceObjective = "Kraz in Harkors Lager möchte, dass Ihr den Schlaghammer von Drakil'jin auf die Gongs außerhalb der Ruinen von Drakil'jin anwendet. Ihr sollt die Ruinen betreten, sobald Ihr erschlagen wurdet, und mit dem Geist von Gan'jo sprechen, solange Ihr tot seid.", completion = "Euer Kommen wurde vorhergesagt, {class}. Es ist gut, dass Ihr gekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[12122] = { id = 12122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz erhalten", description = "{name}, Ihr müsst so schnell wie Ihr könnt zum Wyrmruhtempel reisen und dem Bediensteten Tariolstrasz diesen Brief überreichen.\n\nDer Tempel liegt im Zentrum der Drachenöde. Folgt der Straße in östliche Richtung bis zu ihrem Ende und durchquert die Dracheneiswüste, um dorthin zu gelangen.\n\nWenn der Bedienstete Euer Vorstellungsschreiben erst einmal gesehen hat, wird er Euch sicherlich eine Audienz bei Königin Alexstrasza beschaffen, denke ich. Wir können nur darauf hoffen, dass es nicht schon zu spät ist.\n\nIch danke Euch für all das, was Ihr für uns getan habt. Gute Reise!", sourceObjective = "Geht zum Wyrmruhtempel und liefert das Vorstellungsschreiben bei Tariolstrasz ab.", progress = "Ja? Was kann ich für Euch tun, {race}?", completion = "Ein Vorstellungsschreiben und Gesuch um ein Treffen mit der Königin? Zeigt einmal her.\n\nWas auch immer Euer Anliegen auch sein mag, ich hoffe, es ist wichtig. Der Himmel wimmelt heute nur so von angreifenden Blauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12123] = { id = 12123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Königin verständigen", description = "<Der Drachenwächter zieht Euer Vorstellungsschreiben aus dem Ärmel.>\n\nJa... ja, ich meine, dass Ihr jetzt zur Königin gehen könnt.\n\nSagt mir Bescheid, wenn Ihr bereit seid, und ich werde dafür sorgen, dass einer dieser Drachen Euch sicher zur obersten Etage des Tempels bringen wird. Ihr werdet Euren Brief persönlich an Königin Alexstrasza überreichen müssen.", sourceObjective = "Liefert Euer Vorstellungsschreiben bei Alexstrasza der Lebensbinderin im Wyrmruhtempel ab.", progress = "Schön, Euch endlich persönlich kennenzulernen, {name}. Ich kannte Euch schon, da wart Ihr noch nicht geboren.", completion = "Ihr habt viel Mut, uns diese Informationen zu bringen. Ich habe mich schon gewundert, weshalb der blaue Drachenschwarm einen so waghalsigen Angriff auf den Tempel selbst eingeleitet hat. Nun wissen wir, dass sie riesige Mengen genau der Magie verwenden, die ihrer Ansicht nach eine Bedrohung für Azeroth darstellt.\n\n<Die Königin schüttelt ihren Kopf, offenbar vor Ratlosigkeit.>\n\nScheinheilig, aber was soll's. Wenn Malygos nicht wieder zur Vernunft kommt, haben wir keine andere Wahl, als auf ihren Angriff Taten folgen zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12124] = { id = 12124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Königin verständigen", description = "<Der Drachenwächter zieht Euer Vorstellungsschreiben aus dem Ärmel.>\n\nJa... ja, ich meine, dass Ihr jetzt zur Königin gehen könnt.\n\nSagt mir Bescheid, wenn Ihr bereit seid, und ich werde dafür sorgen, dass einer dieser Drachen Euch sicher zur obersten Etage des Tempels bringen wird. Ihr werdet Euren Brief persönlich an Königin Alexstrasza überreichen müssen.", sourceObjective = "Liefert Euer Vorstellungsschreiben bei Alexstrasza der Lebensbinderin im Wyrmruhtempel ab.", progress = "Schön, Euch endlich persönlich kennenzulernen, {name}. Ich kannte Euch schon, da wart Ihr noch nicht geboren.", completion = "Ihr habt viel Mut, uns diese Informationen zu bringen. Ich habe mich schon gewundert, weshalb der blaue Drachenschwarm einen so waghalsigen Angriff auf den Tempel selbst eingeleitet hat. Nun wissen wir, dass sie riesige Mengen genau der Magie verwenden, die ihrer Ansicht nach eine Bedrohung für Azeroth darstellt.\n\n<Die Königin schüttelt ihren Kopf, offenbar vor Ratlosigkeit.>\n\nScheinheilig, aber was soll's. Wenn Malygos nicht wieder zur Vernunft kommt, haben wir keine andere Wahl, als auf ihren Angriff Taten folgen zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12125] = { id = 12125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste des Blutes", description = "Einst stillte das Blut Unschuldiger den Durst der Klinge - doch leider bietet sich mir diese Möglichkeit nicht mehr.\n\n<Koltira hält inne und denkt nach.>\n\nWir müssen improvisieren. Südlich von hier, oben auf den hohen Klippen befindet sich das Tuskarrdorf Indu'le. Erst kürzlich wurde es vom blauen Drachenschwarm mit seiner chaotischen Magie überrannt, was die dort heimischen Tuskarr in den Wahnsinn trieben.\n\nNehmt diese Blutgemme hier und wendet sie auf die geistig verwirrten Dorfbewohner an. Wenn ich das Blut Unschuldiger schon nicht haben kann, dann soll mir das Blut der Sanftmütigen gehören!", sourceObjective = "Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die Blutgemme auf die verstörten Bewohner von Indu'le anwendet und sie gefüllt wieder zu ihm zurückbringt.", progress = "Bringt mir das Blut der Sanftmütigen.", completion = "Eine simple Aufgabe für jemanden so simpel, wie Ihr es seid. Ihr habt meine Erwartungen erfüllt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12126] = { id = 12126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste des Unheiligen", description = "Die Macht des Unheiligen ist unter meinesgleichen begehrt. Sie ist Grundlage unserer Existenz und gewährt jenen den Tod, die es wagen sollten, sich darüber zu mokieren! Glücklicherweise gibt es einen Quell, der mich in Zeiten der Not mit Energie versorgt.\n\nNehmt diese unheilige Gemme und macht Euch auf den Weg zum östlich gelegenen Rubindrachenschrein. Dort werdet Ihr auch Fürst Vallenhal, einen von Arthas' Todesrittern, finden. Schwächt ihn im Kampfe und entfesselt dann die Macht der Gemme. Sie wird ihm den Rest geben und ihm seine unheilige Energie nehmen!", sourceObjective = "Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die unheilige Gemme auf Fürst Vallenhal anwendet und sie gefüllt wieder zu ihm zurückbringt.", progress = "Füllt die Gemme mit unheiliger Macht!", completion = "<Koltira macht große Augen.>\n\nBeeindruckend. Ihr habt einen von Arthas' Todesrittern besiegt... Sicherlich wart Ihr nicht allein... doch immerhin...", sourceObjectiveStatus = "unverified-source-field" }
quests[12127] = { id = 12127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste des Frosts", description = "Die beißende Kälte beschützt den Todesritter und hält seine Feinde fern. Er beherrscht die Macht des Frosts, bringt Chaos und Zerstörung!\n\nNehmt diese Frostgemme und durchquert die Tundra der Drachenöde, bis Ihr den Spiegel der Morgenröte östlich des Wyrmruhtempels erreicht. Dort, auf dem zugefrorenen See, werdet Ihr Euch Legionen von Eisklagegeistern stellen müssen und ihnen die Essenz des Frosts abnehmen. Bedient Euch der Macht der Gemme, sobald sie geschwächt sind, {name}!", sourceObjective = "Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die Frostgemme auf die Eisklagegeister anwendet und sie gefüllt zu ihm zurückbringt.", progress = "Hier in Nordend stehen wir alle im Dienste des Frosts.", completion = "Ich spüre, {name}, wie mich die Kälte durchströmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12128] = { id = 12128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht mal nach Raegar", description = "Bei all der Aufregung um die Armee, die versucht, durch Thor Modan zu ziehen, hätte ich Raegars Truppe unten beim Prospektorat beinahe vergessen.\n\nIch habe Raegar und seine Assistenten gemeinsam mit einem Bergsteigerfreund dorthin geschickt, um einen kleinen Posten in der Nähe von Dun Argol am südlichen Zipfel der Ostwindküste zu errichten.\n\nSie wollten die Eisenzwerge ausspionieren, die sich in den südlichen Hügeln aufhalten, doch ich habe noch nichts von ihnen gehört. Könntet Ihr einmal nachsehen, ob es ihnen gut geht, wenn Ihr schon in diese Richtung unterwegs seid?", sourceObjective = "Sprecht mit Raegar Brechbraue im Prospektorat.", completion = "Hmm... Ihr seht zwar nicht wie ein Forschungsassistent aus, doch das macht nichts. Die Eisenzwerge bereiten sich auf einen Krieg vor und mein Forschungsteam ist noch nicht zurückgekehrt. Wir könnten hier etwas Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12129] = { id = 12129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der perfekte Plan", description = "Die Eisenzwerge machen keinen Hehl daraus, dass sie Kriegsvorbereitungen treffen. Mit ihren Riesen, Golems und Blitzelementaren haben sie den technologischen Vorteil gegenüber der Westfallbrigade. Sollte es ihnen nicht rechtzeitig gelingen, einen Weg in den Norden zu finden, könnten die Eisernen sie überraschen.\n\nWir müssen sie hier halten und ich weiß auch genau den richtigen Weg dafür. Dun Argol ist voller Runenschmiede, die am Fließband Kriegsgolems produzieren. Sie tragen die Pläne für die spezifischen Teile bei sich, also müsst Ihr alle Stücke finden und zusammensetzen.", sourceObjective = "Bringt Raegar Brechbraue im Prospektorat die kompletten Blaupausen für einen Kriegsgolem.", progress = "Ist es Euch gelungen, die Pläne von den Runenschmieden zu bekommen?", completion = "Ihr habt sie alle? Exzellent! Ich kann es kaum abwarten, den Ausdruck auf ihren Gesichtern zu sehen, sobald der Golem fertig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[12130] = { id = 12130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieber requirieren als produzieren", description = "Wir haben die Blaupausen, aber ohne entsprechende Bauteile können wir nichts damit anfangen! Wir haben keinen Zugang zu einer Schmiede, zu Materialien noch viel weniger. Aber es gibt in Dun Argol eine ganze Ladung Materialien.\n\nEuer Job?\n\nGebt ihnen ein neues Zuhause.\n\nVermutlich sind sie um die Gebäude, in denen die Eisenrunenschmiede arbeiten, herum verteilt. Würde mich nicht wundern, wenn die Runenschmiede ein wenig gereizt reagieren, wenn Ihr ihnen die Früchte ihrer harten Arbeit stehlt. Je mehr Ihr bringen könnt, desto besser wird dieser Golem.", sourceObjective = "Bringt 8 Teile eines Kriegsgolems zu Raegar Brechbraue im Prospektorat.", progress = "Ich sehe, dass Ihr es in einem Stück da raus geschafft habt. Habt Ihr die Teile?", completion = "<Raegar wischt sich mit der Handfläche über die Stirn.>\n\nOh, nein. Das wird härter, als ich dachte. Diese Dinger haben keine Seriennummern oder ähnliches, wie?\n\nWann immer man einen Gnom braucht, ist keiner da…", sourceObjectiveStatus = "unverified-source-field" }
quests[12131] = { id = 12131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir haben die Macht", description = "Wir sind fast da, doch der Kriegsgolem will ohne Energie nicht funktionieren. Den Informationen nach, die ich in Argul sammeln konnte, bevor wir entdeckt wurden, erschaffen Runenschmied Durar und Runenschmied Kathorn jeweils eine Energiezelle.\n\nWir werden eine Energiezelle von jedem Runenschmied benötigen, um unseren Golem zum Laufen zu kriegen.\n\nDie Runenschmiede sollten in ihren Werkstätten auf der zentralen Ebene von Dun Argol zu finden sein.", sourceObjective = "Bringt Durars Energiezelle und Kathorns Energiezelle zu Raegar Brechbraue im Prospektorat.", progress = "Nun, habt Ihr diese Energiezellen dabei?", completion = "<Raegar nimmt Euch die Batterien ab.>\n\nAusgezeichnet! Wir sollten jetzt loslegen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12132] = { id = 12132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht zu Zerstören...", description = "Ihr habt zwar schon viel für mich getan, doch eine Sache bleibt noch.\n\nNeben der Euch bekannten Welt existiert eine zweite, die Welt der Schatten, die Welt meiner Peiniger - von wo aus sie mich beständig angreifen. Nun bin ich meinen eigenen Dämonen gegenüber machtlos, doch Ihr könntet ihrer Herrschaft des Schreckens ein Ende setzen. Ihr besitzt die Stärke, ich habe es mit meinen eigenen Augen gesehen.\n\nBegebt Euch in die Welt der Schatten und stellt Euch den Dämonen, die mich quälen!\n\nTut dies und ich werde den Folianten wie versprochen übersetzen.", sourceObjective = "Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die Welt der Schatten betretet und 6 schattenhafte Peiniger besiegt.\n\nSprecht mit Koltira Todesweber, solltet Ihr die Welt der Schatten wieder betreten müssen.", completion = "Die Macht, die ich besitze hat ihren Preis, {name}. Viele Ritter, ob des Lichts oder der Dunkelheit, ließen in der letzten Schlacht bei der Kapelle des Hoffnungsvollen Lichts ihr Leben. Die Zukunftsaussichten sehen schlecht aus, doch zumindest weiß ich jetzt, was mich erwartet. Der Lichkönig wird mich nie gänzlich aus seinem Griff entlassen und für das allein muss er sterben!", sourceObjectiveStatus = "unverified-source-field" }
quests[12133] = { id = 12133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zermatsch den Kürbis", description = "Diese große Kürbislaterne befindet sich im Zentrum des Dorfes. Ihre Augen betrachten jeden, der sie ansieht, und verraten, dass eine dunkle Bedrohung dahinter lauert.\n\nWenn man den Kürbis zermatscht, wird ein altes, versengtes, heiliges Symbol offenbart.", sourceObjective = "Bring das versengte, heilige Symbol zur kostümierten Waisenmatrone.", progress = "Ja, {name}?", completion = "Ihr habt das in der Kürbislampe des kopflosen Reiters gefunden? Es ist ein altes Symbol des Lichts. Es muss einst dem Reiter gehört haben, bevor er verflucht und zu dem Monster wurde, das er heute ist. Habt Dank, {name}. Dieses Symbol gehört in Paladinhände. Ich werde sicherstellen, dass sie es erhalten.\n\nOh, und das hätte ich fast vergessen! Ihr habt einen stillen Bewunderer...\n\nEines der Kinder wollte, dass Ihr dies erhaltet. Sie war zu schüchtern, es Euch selbst zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12134] = { id = 12134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sashas Jagd", description = "Dieses Ding... dieser Fluch... der sich auf Silberwasser und Julheim auswirkt... er verwandelt mein Volk in Bestien.\n\nMein Vater hat versucht, sie zu warnen, doch stattdessen hörten sie alle lieber auf den Wolfskult.\n\nSie sind nun schon zu lange verwandelt - es ist Zeit, sie auszuschalten... um ihrer selbst willen.", sourceObjective = "Sasha möchte, dass Ihr nach Julheim geht und dort 12 Jäger von Julheim tötet.", completion = "Diese Monster zu töten, wird meinen Vater nicht zurückbringen... doch das spielt jetzt keine Rolle, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[12135] = { id = 12135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Lasset die Feuer kommen!\"", description = "Ihr müsst uns helfen! Der kopflose Reiter wird das Dorf jede Sekunde angreifen. Überall werden Feuer brennen! Die Kinder sind nicht mehr in Sicherheit!\n\nBitte, {name}, stellt Ihr Euch den Feuern des kopflosen Reiters entgegen? Wenn er kommt, müsst Ihr Euch der Brandwache anschließen. Schnappt Euch einen Eimer Wasser und löscht die Feuer damit. Ihr könnt den Eimer auch an einen Freund weitergeben, der näher an den Flammen steht. Wenn Ihr alle Feuer löscht, sind wir vielleicht schon gerettet!", sourceObjective = "Die kostümierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht, nachdem der kopflose Reiter diese entzündet hat. Sprecht noch einmal mit der kostümierten Matrone, sobald alle Feuer erloschen sind.", progress = "{name}, Ihr hattet geschworen, die Kinder zu retten!", completion = "Oh, vielen Dank! Möge das Licht Eure guten Taten segnen, gutherziger Herr. Der kopflose Reiter wirft zwar noch immer seinen bedrohlichen Schatten voraus, aber das Dorf ist jetzt erst einmal vor seinen Flammen sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[12136] = { id = 12136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der übersetzte Foliant", description = "Hier ist es, {name}. Ich habe alles, was auf den Seiten des Folianten geschrieben steht, übersetzt. In seinem Inneren befindet sich eine Liste, auf der die Namen aller Anhänger des Kults der Verdammten geschrieben stehen, die es auf diesem Kontinent gibt.\n\nIhr Netzwerk an Spionen und Agenten ist gelinde gesagt beeindruckend.\n\nLebet wohl, <werter Freund/werte Freundin>. Möge das Buch Euch und Eurem Volke gut dienen.", sourceObjective = "Liefert den übersetzten fleischgebundenen Folianten bei Hauptmann Gort in Agmars Hammer ab.", progress = "Es wurde auch langsam Zeit! Wo seid Ihr nur gewesen?", completion = "<Gort nimmt Euch den Folianten ab und fängt an zu lesen.>\n\nWAS! Das kann nicht stimmen. Ein paar dieser Orcs kenne ich nun schon seit Jahren!\n\nLasst mich alleine, {name}. Ich habe viel Arbeit zu tun und viele Verräter hinzurichten.\n\nNehmt einen dieser Gegenstände als Entschädigung für den Ärger, der Euch bereitet wurde. Ihr habt der Horde heute einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12137] = { id = 12137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganz ruhig, Mann", description = "Es is', wie die Prophezeiung sagte, Mann. <Ein/Eine:r> {race} kommt, um unsre Geister zur Ruhe zu bring'n. Wir warten jetzt schon lange Zeit!\n\nDie Drakkari sind 'n verlor'nes Volk geworden, grimmig und wild.\n\nAber es is' allein unsre Schuld, Mann. Dieser Ort muss geläutert werd'n und nur die Lebenden können das machen.\n\nRed' wieder mit mir, wenn du bereit bist, in deinen Körper zurückzukehren. Nimm dann den Schnee aus der Truhe hier neben mir un' bring meine Brüda in den Schlaf.\n\nBring ihre Überreste zu deinem Geisterführer, der weiß, was als Nächstes zu tun is'.", sourceObjective = "Gan'jo möchte, dass Ihr den Schnee des ewigen Schlafes von seiner Kiste in den Ruinen von Drakil'jin nehmt.\n\nIhr müsst den Schnee bei den dortigen uralten Drakkarigeistern einsetzen und anschließend die Partikel der Drakkarigeister zurück zu Kraz in Harkors Lager bringen.", progress = "Habt Ihr Eure Aufgabe in der Krypta erledigt, {class}?", completion = "Gute Arbeit.\n\nBitte, setzt Euch und hört zu. Es gibt viele Dinge, die wir besprechen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12138] = { id = 12138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... oder vielleicht doch nicht", description = "Man könnte meinen, dass die Jungs, die diese Energiezellen hergestellt haben, auch daran gedacht hätten, sie aufzuladen - aber nein, sie müssen die Sache komplizierter machen.\n\nNun gut, wir werden diese Zellen auf die schwierige Art und Weise aufladen. In ihnen ist zwar genug Energie gespeichert, um den Golem für kurze Zeit zum Laufen zu bringen, doch erwartet nicht von ihm, dass er auch gut im Kämpfen ist.\n\nKönnt Ihr die Blitzwachen sehen, die von den Eisenzwergen an der Grenze von Dun Argol postiert wurden? Nehmt den Golem mit, geht nah an sie heran, zerstört die Wachen und lasst den Golem ihre Energie absorbieren.", sourceObjective = "Ladet Euren Kriegsgolem mit der Energie von 10 Blitzwachen auf und kehrt anschließend zu Raegar Brechbraue im Prospektorat zurück.", completion = "Endlich ist er bereit. Ich hoffe nur, dass er so lange zusammenhält, bis die Arbeit getan ist. Wenn wir den in Dun Argol kommandierenden Than nicht ausschalten, dann wird Hauptmann Gryan eine böse Überraschung erleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12139] = { id = 12139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Lasset die Feuer kommen!\"", description = "Der kopflose Reiter wird das Dorf jede Sekunde angreifen. Überall werden Feuer brennen!\n\nBitte, {name}, stellt Ihr Euch den Feuern des kopflosen Reiters entgegen? Wenn er kommt, müsst Ihr Euch der Brandwache anschließen. Schnappt Euch einen Eimer Wasser und löscht die Feuer damit. Ihr könnt den Eimer auch an einen Freund weitergeben, der näher an den Flammen steht. Wenn Ihr alle Feuer löscht, sind wir vielleicht schon gerettet!", sourceObjective = "Die maskierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht. Sprecht noch einmal mit der maskierten Matrone, sobald alle Feuer erloschen sind.", completion = "Die Feuer sind erloschen! Ihr wart mit Eurer Brandwache erfolgreich! Hah!\n\nDer Angriff des kopflosen Reiters ist fehlgeschlagen, aber solange er und sein Kopf nicht vernichtet werden, wird er wieder zurückkehren.\n\nLasst uns bis dahin Trost in der Sicherheit finden, die Ihr uns und unseren Kindern beschert habt. Es war mir eine Ehre, heute Zeuge Eurer Taten zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12140] = { id = 12140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hoch auf Roanauk!", description = "Wie die Tauren, die Verlassenen, Trolle und Blutelfen, so brauchen auch die Taunka einen Anführer, der von ihrem eigenen Blute abstammt. Der eine, den Ihr aus Eisnebel befreit habt - Roanauk -, wird dieser Anführer sein.\n\n<Oberanführer Agmar überreicht Euch ein Pergament.>\n\nIch gebe Euch etwas, das Ihr schon kennt - auf ihm steht der Blutschwur der Horde geschrieben.\n\nBringt das Pergament zu Roanauk Eisnebel und nehmt ihn als Anführer der Taunka in die Horde auf.\n\nLassen wir ihn nicht warten.\n\n<Agmar nickt Euch zu.>", sourceObjective = "Geht nach Agmars Hammer, sucht Roanauk Eisnebel auf und macht ihn zu einem Mitglied und Anführer der Hordestreitkräfte.\n\nKehrt anschließend mit dem Blutschwur der Horde zu Oberanführer Agmar zurück, sobald Ihr diese Aufgabe abgeschlossen habt.", completion = "Ein so mächtiger Schamane wird uns an der Pforte des Zorns sicherlich den Sieg bescheren!", sourceObjectiveStatus = "unverified-source-field" }
quests[12141] = { id = 12141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine diplomatische Mission", description = "Ich sehe, dass Ihr sehr begierig drauf seid, zu helfen, {name}. Ihr seid nicht den ganzen Weg nach Nordend gereist, damit Ihr Euch in einer Stadt verkriecht! Ich hab genau die richtige Aufgabe für Euch... etwas, das Euch weit weg von hier bringt.\n\nWir haben lange versucht, uns das Wohlwollen der in Nordend heimischen Tuskarr zu sichern. Neulich kam ein junger Tuskarr zu uns und ersuchte Hilfe, etwas, womit wir zu dieser Zeit nicht dienen konnten.\n\nJetzt, da Ihr da seid, könnt Ihr ihm vielleicht zur Hand gehen. Sucht nach Karuk in der Nähe des Strandes der Peitschennarbe südwestlich von hier und schaut, was Ihr für ihn tun könnt.", sourceObjective = "Sprecht mit Karuk am Strand der Peitschennarbe südwestlich der Valianzfeste.", completion = "Ihr seid gekommen, um mir zu helfen? Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12142] = { id = 12142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädlingsbekämpfung", description = "Uhh! Als wir uns um den letzten Drachen gekümmert haben, hat einer dieser kleinen Schneeboldwichte unser Lager verwüstet. Jedes Mal, wenn wir ihnen den Rücken kehren, bereiten sie uns irgendwelchen Ärger... Ich hab's satt!\n\nDie Schneebolde gen Süden verstecken sich hinter den örtlichen Magnatauren - hängen an ihren Rockzipfeln sozusagen. Geht und schlachtet sie nieder.\n\nUnd falls die Magnatauren für ihre Sklaven eintreten sollten, dann tötet sie auch.", sourceObjective = "Duane bei der Front der 7. Legion möchte, dass Ihr 10 Schneebolde der Schneeebene und 3 Magnatauren der Drachenöde in den Lagern um den Wyrmruhtempel herum tötet.", progress = "Habt Ihr diese Schädlinge beseitigt?", completion = "Ein Glück, dass wir sie los sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[12143] = { id = 12143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd durch die Schluchten", description = "Ich kann es nicht fassen! Gerade wollte noch so eine Bande von diesem Gezücht mit unseren Vorräten abhauen. Sie machen sich in Richtung der nördlichen Schlucht davon. Verfolgt sie und kümmert Euch um ihren Anführer!", sourceObjective = "Duane möchte, dass Ihr die Schneebolde im Canyon nordöstlich der Front der 7. Legion verfolgt und Euch anschließend um deren Anführer kümmert.", completion = "Kühlhauer, wie? Ich hab' den Namen schon mal gehört. Richtig gute Arbeit, {class}. Hoffentlich können wir jetzt wieder unsere Aufmerksamkeit den Drachen zuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12144] = { id = 12144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädlingsbekämpfung", description = "Ai, Mann! Ein von dene kleine rattige Schneebolds hat bei die letzte Drachenangriff unsere Lager auf'n Kopp gestellt, Mann. Die sin' uns imma auf'n Fersen, sobald wir ihn' den Rücken zudreh'n. Un' ich hab genug! \n\nIm Osten vastecke'n die sich unter die Röcke von 'nen paar Magnataur'n, die hia leben. Geht un tut sie abschlacht'n. Un' wenn die Magnataur'n sich da für ihre Sklaven reinhäng'n tun, tötet sie auch, Mann.", sourceObjective = "Kontokanis in Drachensturz möchte, dass Ihr 10 Schneebolde der Schneeebene und 3 Magnatauren der Drachenöde in den Lagern um den Wyrmruhtempel herum tötet.", completion = "Nich' schad' um die, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12145] = { id = 12145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd durch die Schluchten", description = "Ich kann das nich' glauben! Noch 'ne Bande von dem Gezücht wollt' grad mit mea von unsere Vorräte abhau'n! Die flitzen grad runta in die Schlucht, lauft ihn' nach un' kümmat Euch um den ihr Chef!", sourceObjective = "Kontokanis möchte, dass Ihr die Schneebolde in der Schlucht südlich von Drachensturz verfolgt und anschließend ihren Anführer beseitigt.", completion = "Eisfaust, ai? Den Namen hab ich schon mal gehört. Das war mal gute Arbeit, Mann. Jetz' können wir Dunk'lspea uns hoff'ntlich wieda um die Drach'n kümman.", sourceObjectiveStatus = "unverified-source-field" }
quests[12146] = { id = 12146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beunruhigende Hinweise", description = "Die untere Seite des Horns schmückt ein Siegel, das einen Hammer und einen Blitz zeigt. Irgendetwas an diesem Horn wirkt bei einem Magnataur vollkommen fehl am Platze.\n\nGeht nach Süden den Pfad der Titanen entlang, bringt das Horn zum Wyrmruhtempel und sucht jemanden auf, der an diesen bedrohlichen Hinweisen Interesse haben könnte.", sourceObjective = "Bringt das geschmückte Kriegshorn zum Wyrmruhtempel und sucht dort nach jemandem, der die drohende Gefahr einschätzen kann.", progress = "Ja, {race}?", completion = "Es ist für einen Magnatauren in der Tat seltsam, so einen Gegenstand bei sich zu tragen... und sehr beunruhigend. Ich bin froh, dass Ihr es mir gezeigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12147] = { id = 12147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beunruhigende Hinweise", description = "Die untere Seite des Horns schmückt ein Siegel, das einen Hammer und einen Blitz zeigt. Irgendetwas an diesem Horn wirkt bei einem Magnataur vollkommen fehl am Platze.\n\nGeht nach Osten, durchquert die Dracheneiswüste und bringt das Horn zum Wyrmruhtempel. Sucht dort jemanden auf, der an diesen bedrohlichen Hinweisen Interesse haben könnte.", sourceObjective = "Bringt das geschmückte Kriegshorn zum Wyrmruhtempel und sucht dort nach jemandem, der die drohende Gefahr einschätzen kann.", progress = "Ja, {race}?", completion = "Es ist für einen Magnataur in der Tat seltsam, so einen Gegenstand bei sich zu tragen... und sehr beunruhigend. Ich bin froh, dass Ihr es mir gezeigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12148] = { id = 12148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzigartig", description = "So ein seltsames Siegel bei einem Magnatauren... das lässt auf ungewöhnlich viel Organisation schließen.\n\nEs kommt nur selten vor, dass Magnatauren ihr aggressives Naturell beiseitelegen, um miteinander zu kooperieren. Ich vermute, dass sie ihre Aufmerksamkeit darauf gerichtet haben, einen Überfall auf eine große Siedlung zu starten.\n\nIch bezweifle sehr, dass dieses Horn einzigartig ist - Ihr müsst mich also vom Gegenteil überzeugen. In der Schlucht gen Nordwesten des Azurdrachenschreins befindet sich Knochenkracher. Geht, fordert ihn heraus und bringt mir irgendwelche Informationen, die meine Befürchtungen bestätigen könnten.", sourceObjective = "Findet und tötet Knochenkracher in der Nähe der Schlucht nordwestlich des Azurdrachenschreins. Bringt jegliche Informationen zurück zu Aurastrasza im Wyrmruhtempel.", progress = "Habt Ihr irgendwas herausfinden können?", completion = "Es ist also wahr? Sie hätten sich für solch einen Angriff keinen besseren Zeitpunkt aussuchen können... zwischen der Geißel und dem blauen Drachenschwarm - es ist unwahrscheinlich, dass es sonst noch irgendjemand bemerkt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12149] = { id = 12149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die mächtigen Magnatauren", description = "Magnatauren sind furchtbar gewalttätige Kreaturen... das ist der eigentliche Grund dafür, weshalb man nie größere Ansammlungen von ihnen zu Gesicht bekommt, ohne dass sie sich gerade gegenseitig abschlachten. Irgendwo gibt es einen neuen mächtigen Anführer unter ihnen. Wir müssen ihm nachstellen, wenn wir dieser Bedrohung ein Ende setzen wollen.\n\nIch werde mich einmal umhören und möchte, dass Ihr sie in der Zwischenzeit so gut wie möglich ablenkt.\n\nÖstlich von hier wurden 3 Fackeln aufgestellt, in deren Nähe sich 3 dominante Magnatauren befinden. Schaltet sie aus und beschafft uns ein wenig Zeit, damit wir diesen Anführer zur Strecke bringen können.", sourceObjective = "Bringt Blutschmaus, Eisberster und Drachenblut, die sich östlich des Wyrmruhtempels befinden, zur Strecke.\n\nBlutschmaus wohnt im südöstlichen Bereich der Dracheneiswüste, gleich nördlich des Smaragddrachenschreins. Eisberster patrouilliert an der nördlichen Grenze des Spiegels der Morgenröte. Drachenblut wandert am Fuße der Klippen westlich des Bronzedrachenschreins umher.\n\nKehrt zu Aurastrasza im Wyrmruhtempel zurück, sobald Ihr die Magnatauren erschlagen habt.", completion = "Ausgezeichnete Arbeit. Niemand konnte mir zwar sagen, wer dieser Anführer nun sein könnte, doch ich habe den Namen von jemandem herausfinden können, der ihn uns verraten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12150] = { id = 12150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zurückgezogene Runenmeister", description = "Dregmar Runenbrand ist ein magnataurischer Runenmeister... eine Seltenheit unter seinesgleichen. Er verbringt zwar die meiste Zeit allein, ist jedoch dafür bekannt, schon seit einiger Zeit mit den mächtigeren und einflussreicheren Magnatauren der Drachenöde zu verkehren. Er wird schon wissen, wer dieser neue Anführer sein soll.\n\nEs ist eher unwahrscheinlich, dass wir von ihm in irgendeiner Form Hilfe in Bezug auf die wachsende Bedrohung durch die Geißel und den blauen Drachenschwarm erwarten können, also möchte ich, dass Ihr alles Notwendige unternehmt, um die Informationen von Dregmar zu beschaffen.\n\nMir wurde gesagt, dass er sich auf den Klippen am Spiegel der Morgenröte aufhält.", sourceObjective = "Sucht Dregmar Runenbrand auf. Er befindet sich in der Nähe seiner Höhle auf dem Weg zu den Klippen am Spiegel der Morgenröte. Fordert ihn heraus und tut, was notwendig ist, um den Namen des magnataurischen Anführers herauszufinden. Kehrt zu Aurastrasza im Wyrmruhtempel zurück, sobald Ihr die Information erhalten habt.", completion = "Grom'thar der Donnerbringer. Gut. Lasst uns also dieser Magnataurenbedrohung hier und jetzt ein Ende setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12151] = { id = 12151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rücksichtsloser Kriegsherr", description = "Es gibt keinen Grund daran zu zweifeln, dass Dregmars Worte wahr sind. Ob nun Grom'thar Euch unterliegt oder Ihr von ihm besiegt werdet... Es macht keinen Unterschied: Er wird sich seine Hände reinwaschen können.\n\nFolgt seinen Anweisungen... nehmt das Horn, das Ihr mir zuvor gebracht habt, geht zum Fackelring südlich des Azurdrachenschreins und stoßt zum Zeichen der Herausforderung hinein.\n\nTötet anschließend Grom'thar den Donnerbringer und bringt mir seinen Kopf.", sourceObjective = "Geht zum Fackelring südlich des Azurdrachenschreins und stoßt in das geschmückte Kriegshorn. Besiegt Grom'thar den Donnerbringer und bringt seinen Kopf zurück zu Aurastrasza im Wyrmruhtempel.", progress = "Habt Ihr diese Gefahr endgültig aus der Welt schaffen können?", completion = "Wirklich beeindruckend.\n\nNun da Grom'thar der Donnerbringer nicht mehr ist, können wir die restlichen Magnatauren sich gegenseitig bekämpfen lassen und unsere Aufmerksamkeit größeren Gefahren zuwenden.\n\nBeeindruckende Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
